/* 問題バンク（読解プリントメーカー v86 から移したデータ） */
Yomi.bank = {"skills":[{"unit":"1","name":"主語・主体","desc":"誰が何をしたかを正確に取る"},{"unit":"2","name":"指示語","desc":"指示語の中身を本文に戻す"},{"unit":"10","name":"会話文","desc":"発言の意図と本心を読む"},{"unit":"5","name":"事実・推測","desc":"本文の事実と推測を分ける"},{"unit":"3","name":"接続関係","desc":"前後の論理関係を捉える"},{"unit":"4","name":"因果関係","desc":"原因と結果を整理する"},{"unit":"11","name":"具体と抽象","desc":"具体例を一般化する"},{"unit":"12","name":"人物関係","desc":"相手への見方・関係の変化を読む"},{"unit":"8","name":"きっかけ","desc":"人物を動かした出来事を捉える"},{"unit":"6","name":"心情","desc":"行動・表情・会話から心情を読む"},{"unit":"7","name":"心情変化","desc":"変化前と変化後を捉える"},{"unit":"9","name":"人物像","desc":"行動を根拠に人物像をまとめる"},{"unit":"13","name":"表現効果","desc":"比喩・情景を文脈と結び付ける"},{"unit":"14","name":"文章全体","desc":"初期状態・転換点・変化を捉える"},{"unit":"19","name":"要約","desc":"中心と具体例を分けて圧縮する"},{"unit":"15","name":"設問分析","desc":"何を、どんな条件で答えるか整理する"},{"unit":"17","name":"抜き出し","desc":"答えの意味を予測して探す"},{"unit":"16","name":"選択肢照合","desc":"主体・時点・因果・程度を照合する"},{"unit":"18","name":"記述","desc":"必要な答案部品を集めて組み立てる"}],"groups":[["文の内容を正確につかむ",0,4],["文と文の関係をつかむ",4,7],["物語の内容を読み取る",7,13],["文章全体をとらえる",13,15],["入試の答案を作る",15,19]],"problems":[{"id":"p01","skill":"主語・主体","level":1,"stage":"basic","passage":"遥は美咲にノートを渡した。「昨日のところ、まとめておいたよ」と言って笑った。","q":"「笑った」のは誰ですか。","answer":"遥","guide":["【この問題の焦点】一文内の主語を特定","「言って」の主語は誰か確認しよう。","主語を補って「［　　］が言って、［　　］が笑った」と書こう。"],"retry":"「笑った」のは誰ですか。理由も短く書きましょう。","explain":"主語が省略されているときは、直前の文脈と動作の連続性から補います。"},{"id":"p02","skill":"指示語","level":1,"stage":"basic","passage":"美咲は自分の意見をすぐに言わず、まず相手の話を最後まで聞いた。そのことが、話し合いを落ち着かせることにつながった。","q":"「そのこと」が指す内容を本文の言葉を使って書きなさい。","answer":"美咲がまず相手の話を最後まで聞いたこと。","guide":["【この問題の焦点】直前の語句を指す","「そのこと」の直前にある出来事に線を引こう。","「そのこと」をその内容に置き換えて文を読み直そう。"],"retry":"「そのこと」が指す内容を書きなさい。","explain":"指示語は直前の一語だけでなく、前の文の内容全体を指すことがあります。"},{"id":"p03","skill":"接続関係","level":1,"stage":"basic","passage":"この方法は時間がかからず便利だ。しかし、いつでも正しい結果が得られるとは限らない。","q":"「しかし」の前後はどのような関係ですか。","answer":"前の内容に対して、後ろで反対・制限を加える関係。","guide":["【この問題の焦点】基本的な順接・逆接","「しかし」の前を「利点／問題点」に分けるとどちらか。","後ろは前の内容をそのまま強めているか、制限しているか。"],"retry":"「便利だ」と「正しい結果が得られるとは限らない」の関係を説明しなさい。","explain":"逆接では、前で述べた内容に対して、後ろで反対方向の内容や制限が加わります。"},{"id":"p04","skill":"因果関係","level":1,"stage":"basic","passage":"美咲に励まされた。健太は勇気が出た。そこで、発表者に立候補した。","q":"健太が発表者に立候補したのはなぜですか。原因から結果までを説明しなさい。","answer":"美咲に励まされて勇気が出たため、発表者に立候補した。","guide":["美咲が健太にしたことを探す。","その後、健太の気持ちがどうなったかを確認する。","励まし→勇気→立候補の順に説明する。"],"retry":"「勇気が出た」原因を本文から探し、立候補までの流れを説明しなさい。","explain":"原因は美咲の励ましであり、勇気が出たことを経て立候補につながった。気持ちだけを答えず、出来事のつながりを説明する。"},{"id":"p05","skill":"事実・推測","level":1,"stage":"basic","passage":"遥は返事をせず、しばらく窓の外を見ていた。","q":"本文から確実に分かることを書きなさい。","answer":"遥が返事をせず、しばらく窓の外を見ていたこと。","guide":["【この問題の焦点】本文に書かれた事実を取る","本文に直接書かれた行動に線を引こう。","「怒っている」「悲しい」は事実か推測か、○で囲もう。"],"retry":"本文の事実だけを使って答えを書き直しなさい。","explain":"ありそうな気持ちと、本文に明記された事実を区別します。"},{"id":"p06","skill":"心情","level":1,"stage":"basic","passage":"名前を呼ばれた瞬間、健太は握っていた紙をもう一度開き、深く息を吸った。","q":"健太はどのような気持ちだと考えられますか。根拠となる行動も書きなさい。","answer":"紙をもう一度開き深く息を吸っていることから、緊張している。","guide":["【この問題の焦点】行動から基本心情を読む","心情の根拠になる行動に二重線を引こう。","「行動→そこから分かる気持ち」の形でメモしよう。\n行動［　　　　　　］→気持ち［　　　　　　］"],"retry":"根拠と心情を「～ことから、～気持ち。」の形で書きなさい。","explain":"心情は自分の想像だけで決めず、本文中の行動・表情・会話・状況を根拠にします。"},{"id":"p07","skill":"心情変化","level":2,"stage":"single","passage":"発表前、健太は何度も「無理だ」と言っていた。発表を終えると、「次はもう少しうまくできそうだ」と笑った。","q":"健太の気持ちはどのように変化しましたか。","answer":"発表への不安・消極的な気持ちから、次への自信を持つ気持ちへ変化した。","guide":["【この問題の焦点】きっかけを含めて整理","変化前［　　　　　　　　　］","変化後［　　　　　　　　　］"],"retry":"「～から、～へ」の形で変化を書きなさい。","explain":"変化問題は変化後だけでなく、必ず変化前と対にします。"},{"id":"p08","skill":"きっかけ","level":2,"stage":"single","passage":"健太は自分だけ失敗したと思い込んでいた。美咲が「私も同じところで何度も間違えたよ」と話した。その言葉を聞き、健太はもう一度練習してみようと思った。","q":"健太の考えが変わったきっかけは何ですか。","answer":"美咲から、自分も同じところで何度も間違えたと聞いたこと。","guide":["【この問題の焦点】言葉と気づきを区別","変化前［　　　　　　］→きっかけ［　　　　　　］→変化後［　　　　　　］","考えが変わる直前の出来事に線を引こう。"],"retry":"健太がもう一度練習しようと思ったきっかけを書きなさい。","explain":"きっかけは、変化の直前にあり、その変化を生んだ出来事・言葉・気づきです。"},{"id":"p09","skill":"具体と抽象","level":2,"stage":"single","passage":"失敗には、自分の方法を見直す働きがある。例えば、試合で負けた選手が原因を分析し、練習方法を変えることがある。","q":"選手の例は何を説明するためのものですか。","answer":"失敗が自分の方法を見直すきっかけになること。","guide":["【この問題の焦点】例と一般論を対応","「例えば」の前の一般的な説明に線を引こう。","具体例［選手が～］を一段抽象的な言葉に直そう。"],"retry":"「この例は、～ことを示している。」の形で書きなさい。","explain":"具体例は、それ自体より「何の例なのか」を捉えることが重要です。"},{"id":"p10","skill":"設問分析","level":2,"stage":"single","passage":"【設問】傍線部①について、その理由を、直前の段落の内容を踏まえ、「不安」という言葉を使って、四十字以内で説明しなさい。","q":"この設問で守るべき条件をすべて書き出しなさい。","answer":"理由を答える／直前の段落を踏まえる／「不安」を使う／40字以内。","guide":["【この問題の焦点】条件・範囲・字数を分解","何を答える？［　　　　］","どこを使う？［　　　　］　必須語［　　　　］　字数［　　　　］"],"retry":"設問を【問い】【参照範囲】【必須語】【字数】に分けなさい。","explain":"本文を読む前に設問条件を分解すると、問いずれや条件落ちを防げます。"},{"id":"p11","skill":"選択肢照合","level":2,"stage":"single","passage":"本文：発表前は不安だった健太は、美咲に励まされ、少し笑って原稿を閉じた。","q":"「健太は励まされて不安が完全になくなった」という選択肢の問題点を説明しなさい。","answer":"本文は「少し笑った」だけで、不安が完全になくなったとは言えず、程度が強すぎる。","guide":["【この問題の焦点】一部一致の誤答を除く","本文の程度を表す語に線を引こう。","選択肢の「完全に」と本文の程度は同じか。"],"retry":"「本文では～だが、選択肢では～」の形でズレを書きなさい。","explain":"選択肢は主体・対象・時点・因果・程度などに分けて本文と照合します。"},{"id":"p12","skill":"記述","level":3,"stage":"combined","passage":"健太は発表を断ろうとしていた。人前で話すことが苦手で、失敗するのが怖かったからだ。しかし、同じ班の美咲が毎日遅くまで資料を直し、ほかの班員も練習を重ねていると知った。健太は、準備を一人に任せていることが気になり始めた。さらに、美咲から「原稿は一緒に確認しよう」と声をかけられ、失敗への不安が少し和らいだ。翌日、健太は「僕が発表する」と申し出た。","q":"健太が発表を断ろうとしていたのに引き受けた理由を、班員の行動と美咲の言葉の両方に触れて説明しなさい。","answer":"班員が準備や練習を重ねる姿を知って自分も役割を果たしたいと思い、美咲に一緒に原稿を確認しようと言われて失敗への不安が和らいだから。","guide":["初めに断ろうとした理由を確かめる。","班員の準備を知った後の気持ちと、美咲の言葉の効果を別々に探す。","二つの根拠を合わせ、引き受けた理由を説明する。"],"retry":"班員の行動と美咲の言葉は、健太の決断にそれぞれどう働いたか整理しなさい。","explain":"班員の努力は役割を果たそうとする動機になり、美咲の言葉は失敗への不安を和らげた。二つの要因をそろえる。"},{"id":"p13","skill":"要約","level":3,"stage":"combined","passage":"説明を聞いた直後、葵は内容を理解したつもりになっていた。ところが、翌日友人に説明しようとすると、理由を尋ねられた部分で言葉に詰まった。教科書を読み直すと、結論は覚えていたが、その根拠を理解していなかったと分かった。葵は、分かったかどうかを確かめるには、自分の言葉で理由まで説明してみることが必要だと考えた。","q":"葵の経験と、そこから得た考えを含めて、この文章を一文で要約しなさい。","answer":"友人に理由を説明できず理解の不足に気づいた葵は、本当に理解したか確かめるには根拠まで自分の言葉で説明する必要があると考えた。","guide":["【本文を分けて読む】出来事・条件・結果を順に見つけよう。","【根拠を対応させる】設問が求める要素ごとに、本文の該当箇所に印を付けよう。","【答案を組み立てる】複数の根拠を関係が分かるようにつなぎ、本文にない断定を避けよう。"],"retry":"本文から根拠となる箇所を二つ以上選び、どの表現が答案のどの部分に対応するか示した上で、もう一度答えなさい。","explain":"本文の複数箇所を対応させる。設問で要求された要素を漏らさず、事実と解釈、条件と結果の違いを保って説明する。模範解答は一例。"},{"id":"p14","skill":"人物像","level":2,"stage":"single","passage":"遥は自分の意見をはっきり述べた。一方で、美咲の案も最後まで聞き、「その部分は残した方がいい」と提案した。","q":"遥はどのような人物だと考えられますか。二つの行動を根拠に答えなさい。","answer":"自分の意見をはっきり述べながら、相手の考えのよさも認める人物。","guide":["【この問題の焦点】発言と行動を合わせる","遥自身の意見についての行動［　　　　　　　　　］","美咲の意見に対する行動［　　　　　　　　　］","二つに共通する人物の特徴を一言でまとめよう。［　　　　　　　　　］"],"retry":"二つの行動を根拠に、遥の人物像を一文で書きなさい。","explain":"人物像は一つの行動から決めつけず、複数の行動に共通する特徴をまとめます。"},{"id":"p15","skill":"会話文","level":2,"stage":"single","passage":"「全然緊張してないよ」と健太は笑った。しかし、その手は机の下で何度もハンカチを握り直していた。","q":"健太の言葉と実際の気持ちにはどのような違いがありますか。","answer":"言葉では緊張していないように振る舞っているが、実際には緊張している。","guide":["【この問題の焦点】相手への働きを読む","健太が口にした言葉［　　　　　　　　　］","地の文に書かれた行動［　　　　　　　　　］","言葉と行動は一致しているか。　はい・いいえ"],"retry":"「言葉では～が、実際には～」の形で書きなさい。","explain":"会話文だけで本心を決めず、前後の行動や表情と照合します。"},{"id":"p16","skill":"人物関係","level":2,"stage":"single","passage":"美咲は遥の厳しい言い方が苦手だった。しかし、遥が放課後に残って一緒に練習してくれた後は、遥の助言を自分から聞くようになった。","q":"美咲と遥の関係はどのように変化しましたか。","answer":"美咲が遥を苦手にしていた関係から、遥の助言を自分から受け入れる関係へ変化した。","guide":["【この問題の焦点】前後の関係変化を読む","はじめの美咲→遥［　　　　　　　　　］","きっかけ［　　　　　　　　　］","その後の美咲→遥［　　　　　　　　　］"],"retry":"「～関係から、～関係へ」の形で書きなさい。","explain":"人物関係は、相手への見方と相手に対する行動の前後を比べます。"},{"id":"p17","skill":"表現効果","level":2,"stage":"single","passage":"発表台までの数歩が、健太には果てしなく続く道のように思えた。","q":"「果てしなく続く道のよう」と表現したことで、健太のどのような状態が伝わりますか。","answer":"強く緊張しているため、実際には数歩の距離を非常に長く感じている状態。","guide":["【この問題の焦点】対比・反復などの効果","実際の距離［　　　　］／健太が感じた距離［　　　　］","実際と感じ方に大きな差が生まれた理由を考えよう。［　　　　　　　　　］"],"retry":"比喩を普通の言葉に直して、健太の状態を説明しなさい。","explain":"比喩は文字どおりではなく、実際の状況と人物の心理に戻して読みます。"},{"id":"p18","skill":"文章全体","level":3,"stage":"combined","passage":"美咲は「一人でやった方が早い」と考え、班員の意見を聞こうとしなかった。話し合いで行き詰まった後、仲間の案を取り入れて発表を完成させた。最後、美咲は「次は最初からみんなに聞いてみる」と言った。","q":"この文章で描かれている美咲の最も大きな変化を説明しなさい。","answer":"一人で進めようとする姿勢から、他者の意見を取り入れようとする姿勢へ変化した。","guide":["【この問題の焦点】段落同士の役割を整理","冒頭の考え［　　　　　　　　　］","途中の転換点［　　　　　　　　　］","結末の考え［　　　　　　　　　］"],"retry":"【最初→転換点→最後】を意識して、美咲の変化を一文で書きなさい。","explain":"物語全体を捉えるときは、出来事を全部並べるのではなく、初期状態・転換点・変化を軸にします。"},{"id":"p19","skill":"抜き出し","level":2,"stage":"single","passage":"発表前、美咲は手を強く握っていた。発表が始まると、声が少し震えた。発表後、美咲は大きく息を吐いた。","q":"美咲が「発表中に」緊張していたことが最も直接分かる部分を抜き出しなさい。","answer":"声が少し震えた。","guide":["【この問題の焦点】範囲・字数条件を満たす","設問の時点に○をつけよう。　発表前・発表中・発表後","その時点の美咲の行動・様子に線を引こう。"],"retry":"時点の条件を確認して、もう一度抜き出しなさい。","explain":"抜き出しは意味が近いだけでは不十分です。人物・対象・時点・範囲などの条件も一致させます。"},{"id":"p20","skill":"因果関係","level":2,"stage":"single","passage":"朝、健太はパンを食べた。学校へ行く途中で美咲に励まされた。その言葉で勇気が出て、発表者に立候補した。","q":"健太が発表者に立候補した理由を説明しなさい。","answer":"美咲に励まされて勇気が出たから。","guide":["【この問題の焦点】原因→途中→結果","立候補より前の出来事をすべて囲もう。","そのうち、本文中で立候補につながっているものだけに○をつけよう。","「先に起きたこと」と「原因」を区別しよう。"],"retry":"立候補の直接の理由だけを一文で書きなさい。","explain":"時間的に先に起きた出来事がすべて原因になるわけではありません。本文の因果表現を確認します。"},{"id":"p21","skill":"心情","level":2,"stage":"single","passage":"結果発表の紙に自分の番号を見つけた美咲は、何度も番号を確かめた後、大きく息を吐いた。","q":"結果発表の紙に自分の番号を見つけた美咲は、どのような気持ちだと考えられますか。本文の行動を根拠に答えなさい。","answer":"番号を何度も確かめてから大きく息を吐いたことから、自分の番号を見つけて安心した気持ちだと考えられる。","guide":["【この問題の焦点】状況と行動を組み合わせる","美咲が何度も確かめたもの［　　　　　　　　　］","確認後の行動［　　　　　　　　　］","「何に対する」安心なのかまで書こう。"],"retry":"「～ことが分かり、～気持ち。」の形で答えなさい。","explain":"番号を見つけたことは本文の事実ですが、何の試験や選考の結果かは書かれていません。「合格した」と断定せず、行動から読み取れる安心にとどめます。"},{"id":"p22","skill":"選択肢照合","level":3,"stage":"combined","passage":"美咲は遥の厳しい指摘を苦手に感じていたが、一緒に練習してもらった後は、その指摘が自分の上達を願ってのものだと考えるようになった。","q":"次の選択肢が不適切な理由を説明しなさい。「美咲は遥の厳しい指摘を最後まで嫌い続けた。」","answer":"最初に苦手に感じていた点は合うが、その後、指摘の意図を理解して受け止め方が変化したことを無視しているから。","guide":["【この問題の焦点】言い換え・強すぎる表現を判定","選択肢のうち本文と合う部分に○をつけよう。","本文の後半で変化した内容に線を引こう。","一部一致でも、全体として本文と一致するか確認しよう。"],"retry":"「前半は～だが、後半の～と合わない」の形で説明しなさい。","explain":"選択肢問題では、一部分が本文と一致している誤答がよくあります。全要素を照合します。"},{"id":"p23","skill":"記述","level":3,"stage":"combined","passage":"最初、美咲は遥を厳しく怖い先輩だと思っていた。しかし、練習後に遥が自分の経験を話し、一緒に残って練習してくれた。その後、美咲は遥の指摘を前向きに受け止めるようになった。","q":"美咲の遥に対する見方がどのように変化したか、そのきっかけを含めて説明しなさい。","answer":"遥を厳しく怖い先輩だと思っていたが、遥が経験を話して一緒に練習してくれたことをきっかけに、遥の指摘を前向きに受け止めるようになった。","guide":["【この問題の焦点】複数根拠を組み合わせる","変化前［　　　　　　　　　］","きっかけ［　　　　　　　　　］","変化後［　　　　　　　　　］","三つの部品を【前→きっかけ→後】の順につなごう。"],"retry":"三つの答案部品をすべて使って一文で書きなさい。","explain":"「変化＋きっかけ」の記述では、変化前・きっかけ・変化後の三部品が必要です。"},{"id":"p24","skill":"要約","level":3,"stage":"combined","passage":"新しい技術によって、私たちは多くの作業を短時間で終えられるようになった。これは大きな利点である。しかし、空いた時間にさらに多くの仕事を入れれば、忙しさは変わらない。技術が時間を生み出すだけで、余裕まで与えてくれるわけではない。生まれた時間をどう使うかは、私たち自身が考えなければならない。","q":"文章全体を、筆者の主張が分かるように要約しなさい。","answer":"技術で時間を節約できても余裕が生まれるとは限らず、生まれた時間の使い方は自分で考える必要がある。","guide":["【この問題の焦点】対比・因果など骨組みを圧縮","技術の利点［　　　　　　　　　］","「しかし」の後の問題点［　　　　　　　　　］","最後の筆者の主張［　　　　　　　　　］","具体的説明を削り、問題点と主張を中心につなごう。"],"retry":"「利点だけ」で終わらないように、一文で要約しなさい。","explain":"要約では中心主張と、それを成立させる主要な関係を残します。具体例や細部は優先度を下げます。"},{"id":"p25","skill":"主語・主体","level":1,"stage":"basic","passage":"健太は窓を開けた。そして、外を見た。","q":"「外を見た」の主語を補いなさい。","answer":"健太","guide":["【この問題の焦点】一文内の主語を特定","二つの動作をした人物が同じか確認しよう。"],"retry":"「［　］が外を見た」と書きなさい。","explain":"省略された主語は、直前の主体と動作のつながりから補います。"},{"id":"p26","skill":"指示語","level":1,"stage":"basic","passage":"雨が強くなった。そのため、試合は延期された。","q":"「そのため」の「その」が受けている内容を書きなさい。","answer":"雨が強くなったこと。","guide":["【この問題の焦点】直前の語句を指す","直前の出来事を「こと」の形にしよう。"],"retry":"指示内容を入れて文を読み直しなさい。","explain":"指示内容を実際に代入して、文が自然につながるか確認します。"},{"id":"p27","skill":"接続関係","level":1,"stage":"basic","passage":"この道は近い。しかし、坂が急だ。","q":"前後の内容は同じ方向ですか、反対方向ですか。","answer":"反対方向。","guide":["【この問題の焦点】基本的な順接・逆接","「近い」は利点、「坂が急」は不利な点と考えよう。"],"retry":"「しかし」が示す関係を書きなさい。","explain":"逆接は、前と後で評価や方向が切り替わります。"},{"id":"p28","skill":"具体と抽象","level":1,"stage":"basic","passage":"果物にはさまざまな種類がある。例えば、りんごやみかんがある。","q":"「りんごやみかん」は何の具体例ですか。","answer":"果物の種類。","guide":["【この問題の焦点】具体例の共通点を取る","「例えば」の前を見よう。"],"retry":"「～の具体例」と答えなさい。","explain":"具体例は一般的な説明と対応させます。"},{"id":"p29","skill":"設問分析","level":1,"stage":"basic","passage":"【設問】傍線部の理由を、三十字以内で書きなさい。","q":"①何を答えるか、②字数条件、をそれぞれ書きなさい。","answer":"①理由　②30字以内","guide":["【この問題の焦点】何を答えるか確認","問いを表す語と数字に印をつけよう。"],"retry":"【問い】［　］【字数】［　］と整理しなさい。","explain":"問われている内容と形式条件を分離します。"},{"id":"p30","skill":"抜き出し","level":1,"stage":"basic","passage":"健太は朝から不安だった。昼休み、美咲と話して少し安心した。","q":"「昼休みの健太の気持ち」を表す言葉を抜き出しなさい。","answer":"少し安心した","guide":["【この問題の焦点】同じ意味の箇所を探す","人物・時点の二条件を確認しよう。"],"retry":"「昼休み」に限定して探し直しなさい。","explain":"抜き出しは意味だけでなく時点などの条件を合わせます。"},{"id":"p31","skill":"心情変化","level":3,"stage":"combined","passage":"美咲は発表係に決まったとき、「私には無理」と目を伏せた。練習中、遥から「最初よりずっと聞きやすくなった」と言われた。本番後、美咲は「次は原稿を見ないで話してみたい」と笑った。","q":"美咲の心情の変化を、そのきっかけを含めて説明しなさい。","answer":"自分には無理だという不安から、遥に上達を認められたことをきっかけに、さらに挑戦したいという前向きな気持ちへ変化した。","guide":["【この問題の焦点】段階的な変化を追う","変化前［　　　　　　　　　］","きっかけ［　　　　　　　　　］","変化後［　　　　　　　　　］"],"retry":"【前→きっかけ→後】で書きなさい。","explain":"心情変化・会話・きっかけを組み合わせて処理します。"},{"id":"p32","skill":"文章全体","level":3,"stage":"combined","passage":"健太は、失敗を人に知られるのが恥ずかしく、分からないことがあっても質問しなかった。ある日、友人が自分の間違いを笑わずに教えてくれた。健太は、間違えることより分からないままにする方が問題だと気づき、その後は自分から質問するようになった。","q":"健太の考え方の変化を、きっかけを含めて説明しなさい。","answer":"失敗を知られるのを恥ずかしがり質問を避ける考えから、友人が間違いを笑わず教えてくれたことをきっかけに、分からないままにせず質問しようとする考えへ変化した。","guide":["【この問題の焦点】段落同士の役割を整理","最初の考え［　　　　　　　　　］","転換点［　　　　　　　　　］","最後の考え［　　　　　　　　　］"],"retry":"出来事の列挙ではなく考え方の変化としてまとめなさい。","explain":"文章全体では、行動の奥にある認識の変化を捉えます。"},{"id":"p33","skill":"記述","level":3,"stage":"combined","passage":"遥は美咲に何度も厳しい助言をした。美咲は初め、それを責められているように感じていた。ところが、遥が自分の失敗談を話し、「同じ失敗をしてほしくないんだ」と言ったことで、美咲は助言の受け止め方を変えた。","q":"美咲が遥の助言の受け止め方を変えたのはなぜですか。最初の受け止め方にも触れて説明しなさい。","answer":"初めは遥の助言を責められているように感じていたが、遥の失敗談と「同じ失敗をしてほしくない」という言葉から、自分を思っての助言だと分かったから。","guide":["【この問題の焦点】複数根拠を組み合わせる","最初［　　　　　　　　　］","きっかけ［　　　　　　　　　］","分かったこと［　　　　　　　　　］"],"retry":"三条件の抜けがないか確認して書き直しなさい。","explain":"本文理解と設問条件の両方を答案に残します。"},{"id":"p34","skill":"選択肢照合","level":3,"stage":"combined","passage":"図書委員になった健太は、利用者を増やすため、話題の本を目立つ場所に並べればよいと考えていた。ところが、美咲から「いつも同じ人しか借りていない」と言われ、貸出記録を調べると、一部の生徒に利用が偏っていた。そこで健太は、短時間で読める本や写真の多い本も紹介するカードを作った。数週間後、それまで図書室をほとんど利用しなかった生徒の貸出も増えた。健太は、本を増やすことより、本との出会い方を増やすことが大切なのだと考えた。","q":"次の説明の問題点を書きなさい。「健太は、話題の本を増やしたことで、図書室を利用しなかった生徒も本を借りるようになった。」","answer":"結果は合うが、健太が行ったのは話題の本を増やすことではなく、さまざまな本を紹介するカードを作ることであり、原因が本文と異なる。","guide":["【この問題の焦点】言い換え・強すぎる表現を判定","選択肢の【原因】に線を引こう。","本文で実際に行った工夫を探そう。","結果だけでなく原因も照合しよう。"],"retry":"「結果は合うが、原因が～」の形で説明しなさい。","explain":"結果を本文に合わせつつ原因だけをすり替える誤答を見抜きます。"},{"id":"p35","skill":"要約","level":3,"stage":"combined","passage":"便利な道具は、私たちの手間を減らしてくれる。しかし、手間が減ることと、物事について考えなくてよくなることは同じではない。例えば、地図アプリを使えば目的地までの道順はすぐ分かるが、なぜその道が選ばれたのか、周囲にどのような場所があるのかまでは意識しないこともある。道具に任せられる部分が増えたからこそ、人が何を考えるべきかを意識する必要がある。","q":"筆者の主張が分かるように、文章全体を要約しなさい。","answer":"便利な道具に任せて手間を減らせるようになったからこそ、道具任せにせず、人が何を考えるべきかを意識する必要がある。","guide":["【この問題の焦点】対比・因果など骨組みを圧縮","利点［　　　　　　　　　］","「しかし」の後の注意点［　　　　　　　　　］","具体例と主張を分けよう。","最後の主張を中心にまとめよう。"],"retry":"具体例をそのまま残さず一文で要約しなさい。","explain":"逆接の前後と結論を押さえ、具体例を一般化します。"},{"id":"p36","skill":"記述","level":3,"stage":"combined","passage":"美咲は、班で意見が分かれたとき、全員が納得するまで話し合うことが大切だと思っていた。しかし、締切が迫っても結論が出ず、遥から「全員が同じ意見になる必要はない。違いを残したまま、何を優先するか決めることも話し合いだ」と言われた。美咲はその言葉を聞き、話し合いとは意見を一つにそろえることではなく、違いを理解した上で判断することなのだと考えるようになった。","q":"美咲の「話し合い」に対する考えはどのように変化しましたか。遥の言葉の内容を踏まえて説明しなさい。","answer":"全員の意見を一つにそろえることが大切だという考えから、意見の違いを理解した上で何を優先するか判断することが話し合いだという考えへ変化した。","guide":["【この問題の焦点】複数根拠を組み合わせる","変化前の定義［　　　　　　　　　］","遥の指摘［　　　　　　　　　］","変化後の理解［　　　　　　　　　］"],"retry":"【変化前→遥の指摘→変化後】で書きなさい。","explain":"認識変化と、それを生んだ会話内容を統合して書きます。"},{"id":"p37","skill":"主語・主体","level":2,"stage":"single","passage":"美咲が教室に入ると、遥は窓を閉めた。そのあと、机の上の紙を集めた。","q":"「机の上の紙を集めた」のは誰か。","answer":"遥。","guide":["【この問題の焦点】省略された主語を動作の連続から補う","直前から続く動作の主体を補う。","答えの根拠になる本文の部分を書き出そう。"],"retry":"根拠と答えの関係が分かるように書き直しなさい。","explain":"②単一技能：直前から続く動作の主体を補う。"},{"id":"p38","skill":"主語・主体","level":3,"stage":"combined","passage":"放課後、遥は図書室で返却された本を整理していた。美咲は入口で利用者に案内をしていた。健太が「机の上の本も戻そうか」と尋ねると、遥は「それは私がやるから、掲示を貼って」と答えた。健太は掲示を貼り終えると、美咲に声をかけ、入口の案内を交代した。","q":"本を整理する人、掲示を貼る人、最後に入口で案内する人をそれぞれ答え、健太の役割が途中でどう変わったか説明しなさい。","answer":"本を整理するのは遥、掲示を貼るのは健太、最後に入口で案内するのも健太。健太は掲示を貼る役割から入口で案内する役割へ変わった。","guide":["【人物を整理】遥・美咲・健太の最初の仕事をそれぞれ書こう。","【会話の主体】「私がやる」と言ったのは誰か確認しよう。","【時間順】「貼り終えると」の後に健太が何をしたか探そう。","【答案確認】三つの役割と健太の変化をすべて答えたか確かめよう。"],"retry":"人物ごとの最初の役割と最後の役割を表にし、健太の変化を一文で説明しよう。","explain":"会話の「私」は発言者の遥を指す。掲示を貼ったのは健太で、その後は美咲と交代して入口の案内をした。時点ごとに人物と役割を対応させる。"},{"id":"p39","skill":"主語・主体","level":3,"stage":"combined","passage":"放課後、遥は図書室の机に原稿を置き、先に教室へ戻った。美咲が机の上の原稿を見つけたとき、廊下から遥の「原稿を忘れていないかな」という声が聞こえた。美咲は原稿を持って廊下へ走り、遥に手渡した。","q":"原稿を見つけた人と、廊下で原稿を受け取った人をそれぞれ答えなさい。また、原稿が渡るまでの行動の順序を説明しなさい。","answer":"見つけたのは美咲、受け取ったのは遥。遥が原稿を机に置いて教室へ戻り、美咲が見つけて追いかけ、遥に渡した。","guide":["【主体の追跡】原稿を置いた人・見つけた人・受け取った人を区別する。","「先に教室へ戻った」の主語を確認しよう。","原稿を中心に、置く→見つける→渡すの順に人物を並べよう。"],"retry":"原稿を置いたのは誰か。本文の表現を根拠に答えなさい。","explain":"行動の主体は一つの文だけでなく、前後の文で入れ替わる。物の移動に沿って人物を追う。"},{"id":"p40","skill":"指示語","level":2,"stage":"single","passage":"健太は、分からないところをそのままにせず先生に質問した。この行動によって、間違いの原因に気づくことができた。","q":"「この行動」が指す内容は何か。","answer":"分からないところをそのままにせず先生に質問したこと。","guide":["【この問題の焦点】前文の内容全体を指す","指示語を前の内容に置き換える。","答えの根拠になる本文の部分を書き出そう。"],"retry":"根拠と答えの関係が分かるように書き直しなさい。","explain":"②単一技能：指示語を前の内容に置き換える。"},{"id":"p41","skill":"指示語","level":3,"stage":"combined","passage":"健太は授業中に理解できなかった式をノートに書き留めた。帰宅後、まずその式を教科書の例題と比べて、どこから計算が違ったかを調べた。次に、途中式を一行ずつ書き直した。この二つの作業によって、符号を取り違えた箇所を見つけた。","q":"「この二つの作業」が指す内容を、順序が分かるように二つ答えなさい。","answer":"ノートの式を教科書の例題と比べて誤りの始まりを調べることと、途中式を一行ずつ書き直すこと。","guide":["「この二つの作業」の直前にある行動を探す。","「まず」「次に」の後の動作をそれぞれ整理する。","二つの動作を順番に書き、結果の「符号を取り違えた」は作業そのものに含めない。"],"retry":"「まず」と「次に」に線を引き、二つの作業を別々に書き直しなさい。","explain":"「この二つ」は直前の「まず」と「次に」で示された二つの行動をまとめている。誤りを発見したことは作業の結果であり、指示内容とは区別する。"},{"id":"p42","skill":"指示語","level":3,"stage":"combined","passage":"図書委員は、最初は人気の本だけを入口に並べていた。しかし、貸出記録を調べると、借りる人がいつも同じ生徒に偏っていた。そこで短い本や写真の多い本も紹介するカードを作った。すると、これまで図書室を利用しなかった生徒も本を借りるようになった。委員はこの変化を見て、紹介の仕方をさらに工夫しようと考えた。","q":"「この変化」とは、何がきっかけで、誰の行動がどのように変わったことですか。以前の状態と比べて説明しなさい。","answer":"短い本や写真の多い本を紹介するカードを作ったことをきっかけに、以前は図書室を利用しなかった生徒も本を借りるようになったこと。","guide":["【指示語の位置】「この変化」の直前の結果を探そう。","【変化前】以前はどのような生徒が借りていたか確認しよう。","【きっかけ】委員が新しく行った工夫を探そう。","【答案確認】きっかけ・以前・以後の三つが入っているか確かめよう。"],"retry":"「この変化」を具体的な表現に置き換え、何が変わったかを前後で比較しよう。","explain":"「この変化」は直前の「利用しなかった生徒も借りるようになった」を受ける。変化の内容を正確に説明するには、紹介カードというきっかけと、以前との違いを合わせて示す。"},{"id":"p43","skill":"接続関係","level":2,"stage":"single","passage":"便利な道具は時間を節約できる。一方で、使い方を考えなければ時間を無駄にすることもある。","q":"「一方で」は前後をどのような関係で結んでいるか。","answer":"利点と、それとは別の注意点を対比している。","guide":["【この問題の焦点】条件・補足・対比を判断","接続表現の前後の方向を比べる。","答えの根拠になる本文の部分を書き出そう。"],"retry":"根拠と答えの関係が分かるように書き直しなさい。","explain":"②単一技能：接続表現の前後の方向を比べる。"},{"id":"p44","skill":"接続関係","level":3,"stage":"combined","passage":"図書室は放課後、誰でも利用できる。ただし、試験期間中は席数に限りがあるため、利用時間を一時間以内とする。なお、貸し出しの手続きは通常どおり行う。利用希望者が多い場合は整理券を配る。そのため、席を確保したい生徒は受付で整理券を受け取る必要がある。","q":"「ただし」「なお」「そのため」がそれぞれどの説明を受け、何を付け加えているか説明しなさい。","answer":"「ただし」は通常の利用案内に試験期間中の時間制限を加え、「なお」は貸し出し手続きが変わらないことを補足し、「そのため」は整理券を配るという対応から受付で受け取る必要があるという帰結を示す。","guide":["【本文を分けて読む】出来事・条件・結果を順に見つけよう。","【根拠を対応させる】設問が求める要素ごとに、本文の該当箇所に印を付けよう。","【答案を組み立てる】複数の根拠を関係が分かるようにつなぎ、本文にない断定を避けよう。"],"retry":"本文から根拠となる箇所を二つ以上選び、どの表現が答案のどの部分に対応するか示した上で、もう一度答えなさい。","explain":"本文の複数箇所を対応させる。設問で要求された要素を漏らさず、事実と解釈、条件と結果の違いを保って説明する。模範解答は一例。"},{"id":"p45","skill":"接続関係","level":3,"stage":"combined","passage":"班は発表の練習回数を増やした。その結果、声が聞き取りやすくなった。しかし、説明の順序が分かりにくいという指摘は残った。そこで、話す順序を入れ替え、冒頭に結論を示した。すると、聞き手から「内容の流れが分かった」と言われた。","q":"「その結果」「しかし」「そこで」が示す関係を、発表の改善過程に沿って説明しなさい。","answer":"「その結果」は練習回数を増やしたことで声が改善した結果を示し、「しかし」は声の改善後も順序の課題が残った逆接を示し、「そこで」はその課題を受けて説明の順序を変更した対応を示す。","guide":["【本文を分けて読む】出来事・条件・結果を順に見つけよう。","【根拠を対応させる】設問が求める要素ごとに、本文の該当箇所に印を付けよう。","【答案を組み立てる】複数の根拠を関係が分かるようにつなぎ、本文にない断定を避けよう。"],"retry":"本文から根拠となる箇所を二つ以上選び、どの表現が答案のどの部分に対応するか示した上で、もう一度答えなさい。","explain":"本文の複数箇所を対応させる。設問で要求された要素を漏らさず、事実と解釈、条件と結果の違いを保って説明する。模範解答は一例。"},{"id":"p46","skill":"因果関係","level":3,"stage":"combined","passage":"美咲の発表練習を聞いた遥は、「数字だけでは、何が変わったか分からない」と助言した。美咲は資料に前年の数字がないことに気づき、比較できる表を一枚追加した。次の練習では、聞き手から変化が分かりやすいと言われた。","q":"遥の助言から聞き手の反応が変わるまでを、資料の変更内容を含めて説明しなさい。","answer":"遥の助言で前年の数字がないと気づいた美咲が、比較できる表を加えたため、聞き手に変化が伝わりやすくなった。","guide":["遥が指摘した不足を見つけよう。","美咲が追加した資料と、聞き手の反応をそれぞれ探そう。","助言→気づき→工夫→結果の順につなごう。"],"retry":"比較できる表を追加したことがなぜ役立ったのか、本文の言葉を使って説明しなさい。","explain":"単に「助言で改善した」とせず、比較用の表を追加したことが聞き手の理解につながる因果を示します。"},{"id":"p47","skill":"因果関係","level":3,"stage":"combined","passage":"発表前、資料の数字だけでは伝わりにくいと気づいた健太は、数値を棒グラフに直した。さらに、グラフの変化を一言で説明した。聞き手から質問が減り、発表後には内容が分かりやすかったと言われた。","q":"発表が伝わりやすくなった理由を、健太の二つの工夫と聞き手の反応を関連づけて説明しなさい。","answer":"数値を棒グラフに直し、変化を言葉でも説明したため、聞き手の質問が減り、内容が分かりやすくなったから。","guide":["【工夫①】数字の見せ方をどう変えたか探そう。","【工夫②】グラフに加えて何を説明したか探そう。","【反応】質問の数と発表後の評価を確認しよう。","【答案確認】二つの工夫と聞き手の反応を因果関係で結ぼう。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"棒グラフへの変更と変化の言語化という二つの工夫が、質問の減少と分かりやすいという評価につながった。設問は聞き手の反応まで要求している。"},{"id":"p48","skill":"事実・推測","level":2,"stage":"single","passage":"健太は答案を受け取ると、点数を見てしばらく黙っていた。","q":"本文に書かれた事実と、そこから推測できることを一つずつ書きなさい。","answer":"事実：点数を見てしばらく黙っていた。推測：結果について何らかの思いを抱いている。","guide":["【この問題の焦点】事実と心情推測を分ける","事実と推測を分ける。","答えの根拠になる本文の部分を書き出そう。"],"retry":"根拠と答えの関係が分かるように書き直しなさい。","explain":"②単一技能：事実と推測を分ける。"},{"id":"p49","skill":"事実・推測","level":3,"stage":"combined","passage":"健太は答案を受け取ると、点数を見てしばらく黙っていた。隣の友人が「何点だった」と尋ねると、答案を裏返して「あとで話す」と答えた。一方、帰宅後には間違えた問題に印を付け、翌日、先生に解き方を質問した。","q":"健太の行動から確実に言えることを二つ挙げ、そこから推測できる気持ちを述べなさい。また、断定できないことを一つ説明しなさい。","answer":"答案を裏返して点数をすぐには話さなかったことと、翌日先生に解き方を質問したことは事実である。点数を見られたくなかった可能性はあるが、恥ずかしかったとまでは断定できない。","guide":["【本文を分けて読む】出来事・条件・結果を順に見つけよう。","【根拠を対応させる】設問が求める要素ごとに、本文の該当箇所に印を付けよう。","【答案を組み立てる】複数の根拠を関係が分かるようにつなぎ、本文にない断定を避けよう。"],"retry":"本文から根拠となる箇所を二つ以上選び、どの表現が答案のどの部分に対応するか示した上で、もう一度答えなさい。","explain":"本文の複数箇所を対応させる。設問で要求された要素を漏らさず、事実と解釈、条件と結果の違いを保って説明する。模範解答は一例。"},{"id":"p50","skill":"事実・推測","level":3,"stage":"combined","passage":"試合後、彩は「悔しくない」と言った。しかし、誰もいない体育館で、失敗した場面を何度も練習していた。翌朝も一番早く来ていた。","q":"事実として書かれている行動と、そこから推測できる彩の思いを区別して説明しなさい。","answer":"失敗した場面を繰り返し練習し翌朝も早く来たのは事実で、悔しさを感じて次は成功したいと思っていると推測できる。","guide":["【読む場所】本文に直接書かれた行動・発言だけを「事実」として抜き出す。","【関係の整理】推測には必ず対応する事実を結びつけ、本文にない断定を避ける。","【答案】設問「事実として書かれている行動と、そこから推測できる彩の思いを区別して説明しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p51","skill":"心情","level":3,"stage":"combined","passage":"発表の前、美咲は原稿の端を何度も折り、友人から声をかけられても小さくうなずくだけだった。発表の途中で一度言葉に詰まったが、友人がうなずくのを見て話し続けた。発表後、美咲は大きく息を吐き、「途中で止まらなくてよかった」と笑った。","q":"発表前と発表後の美咲の気持ちを、それぞれの行動や発言を根拠に説明し、途中で話し続けられたきっかけも答えなさい。","answer":"発表前は原稿を何度も折るほど緊張していたが、発表後は息を吐いて笑うほど安心していた。途中で友人がうなずくのを見たことが、話し続けるきっかけになった。","guide":["【前後の根拠】発表前と発表後の動作をそれぞれ一つ探そう。","【気持ちの推測】各動作から考えられる気持ちを、断定しすぎず言葉にしよう。","【途中の出来事】言葉に詰まった直後に何を見たか探そう。","【答案確認】前の気持ち・後の気持ち・きっかけを含めよう。"],"retry":"本文の「行動」「気持ちの推測」「きっかけ」を別々に書き、最後に一文にまとめよう。","explain":"原稿を折る動作は緊張を、発表後に息を吐いて笑う様子は安心を示す根拠となる。友人のうなずきが途中の行動を支えた点も本文に明示されている。"},{"id":"p52","skill":"心情","level":3,"stage":"combined","passage":"美咲は発表前、原稿の端を何度も折っていた。発表が終わると、深く息を吐き、仲間に小さくうなずいた。","q":"発表の前後で美咲の気持ちはどう変化したと考えられるか。動作を二つ根拠に説明しなさい。","answer":"原稿を何度も折るほど緊張していたが、発表後には息を吐いて仲間にうなずくほど安心した。","guide":["【発表前】原稿の端を折る動作からどんな気持ちが考えられるか。","【発表後】息を吐き、うなずいた行動からどんな気持ちが考えられるか。","【根拠と推測】本文に書かれた動作と、そこから推測する感情を区別しよう。","【答案確認】前後の動作を二つ示して変化を説明したか。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p53","skill":"心情変化","level":1,"stage":"basic","passage":"健太は最初、質問するのをためらっていた。先生が丁寧に答えるのを見て、最後には自分から手を挙げた。","q":"健太の気持ちの変化を説明しなさい。","answer":"質問することへのためらいから、自分から質問しようとする気持ちへ。","guide":["【この問題の焦点】変化前後を見つける","読み方の型：変化前と変化後を対にする。","本文の根拠に線を引いてから答えよう。"],"retry":"同じ読み方の型を使って、もう一度答えなさい。","explain":"①読み方確認：変化前と変化後を対にする。"},{"id":"p54","skill":"心情変化","level":3,"stage":"combined","passage":"班の話し合いで、健太はメモを握ったまま発言をためらっていた。美咲が「途中でもいいから聞かせて」と声をかけると、健太はメモを読みながら意見を話した。美咲が「その案のここがいいね」と応じると、健太は顔を上げ、最後には自分から別の案も提案した。","q":"健太の行動が二段階で変わったことを、二つのきっかけと対応させて説明しなさい。気持ちは本文から推測できる範囲で述べなさい。","answer":"美咲に発言を促されて、ためらっていた健太はメモを読みながら意見を話した。さらに案を認められると、自分から別の案も提案するようになった。","guide":["【変化の段階】発言前・発言後・提案時の行動を分ける。","一度目のきっかけは美咲のどの言葉か。","二度目のきっかけは美咲のどの反応か。","「安心した」と断定せず、本文の行動で変化を説明しよう。"],"retry":"健太が自分から別の案を出す直前、美咲は何と言ったか。","explain":"心情は直接書かれていないため断定しない。二つの働きかけと、それぞれに続く行動を対応させる。"},{"id":"p55","skill":"きっかけ","level":1,"stage":"basic","passage":"美咲は練習をやめようとしていたが、遥から「昨日より声が出ているよ」と言われ、もう一度続けることにした。","q":"美咲が練習を続けることにしたきっかけは何か。","answer":"遥から昨日より声が出ていると言われたこと。","guide":["【この問題の焦点】直前の出来事を特定","読み方の型：変化直前の出来事を探す。","本文の根拠に線を引いてから答えよう。"],"retry":"同じ読み方の型を使って、もう一度答えなさい。","explain":"①読み方確認：変化直前の出来事を探す。"},{"id":"p56","skill":"きっかけ","level":3,"stage":"combined","passage":"練習で何度も失敗した彩は、参加をやめようとしていた。先輩が自分の失敗談を話し、「最初からできた人はいない」と言ったので、彩は翌日も練習に来た。","q":"彩が練習を続けたきっかけと、それによって考えがどう変わったかを説明しなさい。","answer":"先輩の失敗談と励ましを聞き、失敗しても練習を続ければよいと考え直したから。","guide":["【読む場所】変化する前と後の様子をそれぞれ見つける。","【関係の整理】二つの間に起きた出来事を特定し、変化につながる理由を説明する。","【答案】設問「彩が練習を続けたきっかけと、それによって考えがどう変わったかを説明しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p57","skill":"きっかけ","level":3,"stage":"combined","passage":"地域の清掃活動に乗り気でなかった健太は、通学路のごみを拾う小学生を見かけた。翌週、健太は友人を誘って活動に参加し、毎月続けることにした。","q":"健太が活動を始めた直接のきっかけと、継続するまでの変化を整理しなさい。","answer":"小学生がごみを拾う姿を見たことがきっかけで、参加するだけでなく自分から友人を誘い、継続を決めた。","guide":["【読む場所】変化する前と後の様子をそれぞれ見つける。","【関係の整理】二つの間に起きた出来事を特定し、変化につながる理由を説明する。","【答案】設問「健太が活動を始めた直接のきっかけと、継続するまでの変化を整理しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p58","skill":"人物像","level":1,"stage":"basic","passage":"遥は自分の作業が終わると、何も言われなくても遅れている班の手伝いを始めた。","q":"遥の人物像を、行動を根拠に説明しなさい。","answer":"周囲の状況を見て自分から協力できる人物。","guide":["【この問題の焦点】行動から性質を言い換える","読み方の型：行動から共通する性質をまとめる。","本文の根拠に線を引いてから答えよう。"],"retry":"同じ読み方の型を使って、もう一度答えなさい。","explain":"①読み方確認：行動から共通する性質をまとめる。"},{"id":"p59","skill":"人物像","level":3,"stage":"combined","passage":"班の発表準備が遅れていた。彩は自分の担当を終えると、困っている友人に「どこで止まっているの」と尋ねた。友人が資料の順序に迷っていると分かると、彩は「一緒に並べ直そう」と提案し、自分の作業を見直す時間を削って資料を直した。","q":"彩はどのような人物と考えられるか。相手の状況の確かめ方と、自分の時間の使い方という二つの行動を根拠に説明しなさい。","answer":"相手が困っている点を確かめた上で、自分の時間を使って一緒に解決しようとする、周囲に配慮し協力できる人物。","guide":["【人物像】評価を先に決めず、行動を二つ取り出す。","彩は何を尋ね、友人の何を知ったか。","彩は自分の時間をどう使ったか。","二つの行動に共通する性質を表す言葉を選ぼう。"],"retry":"彩が友人に最初に尋ねた言葉を抜き出しなさい。","explain":"人物像の評価語は、本文に書かれた複数の行動と対応させる。"},{"id":"p60","skill":"人物像","level":3,"stage":"combined","passage":"健太は大会で失敗した後、自分の練習記録を読み返し、足りない点を書き出した。翌日からは仲間にも意見を求めて練習方法を変えた。","q":"健太の人物像を、失敗への向き合い方と他者との関わり方から説明しなさい。","answer":"失敗を振り返って改善点を探し、他者の意見も取り入れて努力する人物。","guide":["【読む場所】人物の特徴を示す異なる行動を二つ探す。","【関係の整理】行動の共通点から人物像を述べ、性格だけの断定にならないようにする。","【答案】設問「健太の人物像を、失敗への向き合い方と他者との関わり方から説明しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p61","skill":"会話文","level":1,"stage":"basic","passage":"「別に気にしてないよ」と美咲は言ったが、その後も何度も掲示板を振り返った。","q":"美咲の発言と行動から、本心をどう考えられるか。","answer":"気にしていないと言いながら、実際には結果を気にしている。","guide":["【この問題の焦点】発言の意味を取る","読み方の型：会話と地の文を照合する。","本文の根拠に線を引いてから答えよう。"],"retry":"同じ読み方の型を使って、もう一度答えなさい。","explain":"①読み方確認：会話と地の文を照合する。"},{"id":"p62","skill":"会話文","level":3,"stage":"combined","passage":"「一人で大丈夫」と言った美咲は、重い段ボールを持ち上げようとして何度も手を止めた。遥が「半分持つよ」と言うと、美咲は少し笑って箱の片側を渡した。","q":"美咲の最初の発言と、その後の行動にはどのような違いがありますか。本文の行動を根拠に説明しなさい。","answer":"最初は「一人で大丈夫」と言ったが、重い箱を持ち上げるのに苦労し、遥が手伝いを申し出ると箱の片側を渡して助けを受け入れた。","guide":["【読む場所】発言の前後にある動作・呼びかけから話し手と聞き手を確定する。","【関係の整理】発言の表面の意味と、その場面での意図を分けて整理する。","【答案】設問「美咲の最初の発言と、その後の行動に違いがあるのはなぜか。本文の行動を根拠に説明しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p63","skill":"会話文","level":3,"stage":"combined","passage":"「今日はもう練習しない」と健太は言った。しかし帰り際、使った道具を片づけながら明日の練習予定を何度も確かめた。","q":"健太の言葉と行動を対比し、言葉だけでは分からない気持ちを説明しなさい。","answer":"練習しないと言いながら予定を確認しており、練習への関心や続けたい気持ちが残っている。","guide":["【読む場所】発言の前後にある動作・呼びかけから話し手と聞き手を確定する。","【関係の整理】発言の表面の意味と、その場面での意図を分けて整理する。","【答案】設問「健太の言葉と行動を対比し、言葉だけでは分からない気持ちを説明しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p64","skill":"具体と抽象","level":3,"stage":"combined","passage":"地域の祭りでは、昔の人々が豊作を願った踊りが今も受け継がれている。また、地元の料理には、保存のために工夫された昔の暮らしの知恵が残っている。祭りも料理も、形は違うが、地域の歴史や暮らしを今に伝えている。","q":"祭りと料理の例に共通する役割を、それぞれの具体的な内容を根拠にして説明しなさい。","answer":"祭りは昔の豊作への願いを、料理は保存の知恵を受け継ぐことで、どちらも地域の歴史や暮らしを今に伝える役割を持つ。","guide":["祭りに残るものと料理に残るものを別々に抜き出そう。","二つをまとめた最後の一文に注目しよう。","それぞれの具体例と共通する役割をつなげて書こう。"],"retry":"祭りと料理のどちらにも「受け継ぐ」という働きがあることを、本文の例を使って説明しなさい。","explain":"具体例を二つ挙げたうえで、「歴史や暮らしを伝える」という共通の抽象的な役割にまとめます。"},{"id":"p65","skill":"具体と抽象","level":3,"stage":"combined","passage":"町の図書館では、絵本の読み聞かせ会や、地域の歴史を調べる講座を開いている。年齢も目的も異なる人々が集まり、学んだことを互いに話している。","q":"読み聞かせ会と歴史講座に共通する図書館の役割を、具体例から抽象化して説明しなさい。","answer":"年齢や目的の異なる人々に学びと交流の機会を提供する役割。","guide":["【読む場所】具体例に共通する特徴を二つ以上拾う。","【関係の整理】共通点を抽象的な言葉にまとめ、元の具体例に当てはまるか戻って確認する。","【答案】設問「読み聞かせ会と歴史講座に共通する図書館の役割を、具体例から抽象化して説明しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p66","skill":"人物関係","level":1,"stage":"basic","passage":"健太は遥を競争相手だと思っていた。しかし、遥が自分の練習方法を教えてくれたことで、一緒に高め合える相手だと考えるようになった。","q":"健太は最初、遥をどのような相手だと思っていましたか。","answer":"競争相手。","guide":["「しかし」より前の文を読もう。","健太が遥を何だと思っていたか探そう。"],"retry":"最後に健太は遥をどのような相手だと考えるようになりましたか。","explain":"関係の変化を考える前に、最初の二人の関係を確認します。"},{"id":"p67","skill":"人物関係","level":3,"stage":"combined","passage":"美咲はいつも遥に準備を手伝ってもらい、「助けてもらってばかりで申し訳ない」と話していた。遥が「私も前は先輩に助けられたよ」と言った翌日、遥が資料作りに困っているのを見た美咲は「今度は私が手伝う」と申し出た。二人は相談しながら資料を仕上げた。","q":"美咲と遥の関係がどのように変わったか、最初の状態・変化のきっかけ・最後の行動を含めて説明しなさい。","answer":"最初は美咲が遥に助けられることが多かったが、遥も以前は助けられていたと聞き、美咲も自分から手伝い、互いに協力する関係になった。","guide":["【関係の変化】最初に助ける側と助けられる側を特定する。","遥が過去の経験を話した後、美咲は何を申し出たか。","最後の二人の行動を根拠に、関係を一文でまとめよう。"],"retry":"最後に二人は何を一緒にしたか。本文から答えなさい。","explain":"関係の変化は、発言だけでなく最後の共同作業を根拠に説明する。"},{"id":"p68","skill":"人物関係","level":3,"stage":"combined","passage":"健太と彩は発表の構成について意見が合わず、準備中はほとんど話さなかった。発表直前、健太が資料の数字の誤りを見つけ、彩に伝えた。彩はすぐに数字を直し、健太も発表用の説明を書き換えた。発表後、彩は「気づいてくれて助かった」と言い、健太は「すぐ直してくれてありがとう」と答えた。","q":"二人の関係が変わったことを、最初の対立・共同で行った修正・発表後の発言を根拠に説明しなさい。","answer":"初めは意見が合わず話さなかったが、健太が誤りを発見し彩が修正、健太も説明を書き換える中で協力し、発表後は互いの行動に感謝を伝える関係になった。","guide":["【人物関係】準備中と発表後の言動を対比する。","誤りに気づいた人、数字を直した人、説明を直した人を分ける。","最後の互いの発言が何を示すか、根拠とともにまとめよう。"],"retry":"発表直前、健太と彩がそれぞれ行った修正を答えなさい。","explain":"「仲良くなった」と抽象化するだけでなく、協力した内容と互いの感謝を根拠にする。"},{"id":"p69","skill":"表現効果","level":1,"stage":"basic","passage":"教室に入る前、健太には扉がいつもより重く感じられた。","q":"この表現から健太のどのような状態が伝わるか。","answer":"教室に入ることへの緊張やためらいが強い状態。","guide":["【この問題の焦点】描写と心情を結ぶ","読み方の型：物理的描写を心理状態に戻す。","本文の根拠に線を引いてから答えよう。"],"retry":"同じ読み方の型を使って、もう一度答えなさい。","explain":"①読み方確認：物理的描写を心理状態に戻す。"},{"id":"p70","skill":"表現効果","level":3,"stage":"combined","passage":"健太は発表の順番を待っていた。名前を呼ばれるまで、手元の原稿を何度も持ち直した。教室では友人たちが話していたが、健太の耳には時計の秒針の音だけが大きく響いていた。","q":"「秒針の音だけが大きく響いていた」という表現は、健太のどのような心理を強調しているか。本文の行動も根拠に答えなさい。","answer":"原稿を何度も持ち直すほど緊張し、発表の順番が来るまでの時間を強く意識している心理。","guide":["発表を待つ間の健太の動作を探そう。","周囲の話し声より秒針の音が目立つことの効果を考えよう。","動作と音の描写を組み合わせて心理を説明しよう。"],"retry":"「秒針の音だけ」という限定によって、健太の意識がどこに集中していると分かるか説明しなさい。","explain":"原稿を持ち直す動作と秒針の音への意識が重なり、発表前の緊張が強調されています。"},{"id":"p71","skill":"表現効果","level":3,"stage":"combined","passage":"美咲は失敗を先生に伝えるのが怖く、朝からうつむいて歩いていた。放課後、思い切って先生に失敗を話すと、先生は「次にどうするか考えよう」と言った。帰り道、美咲には朝まで灰色に見えていた空が、少し明るく感じられた。","q":"空の見え方の変化には、どのような心情の変化が表れているか。きっかけとなった出来事と、朝・帰り道の描写を根拠に説明しなさい。","answer":"失敗を伝えるのが怖く重苦しい気持ちだった美咲が、先生に話して次の対応を一緒に考えてもらい、気持ちが少し軽くなったことを表している。","guide":["【表現と心情】朝と帰り道の空の見え方を対比する。","空の見え方が変わる間に、どんな会話があったか確認する。","空が実際に変わったと断定せず、美咲の感じ方として説明しよう。"],"retry":"先生は美咲に何と言ったか。本文から抜き出しなさい。","explain":"風景の描写を人物の感じ方として読み、間に起きた出来事と結びつける。"},{"id":"p72","skill":"文章全体","level":1,"stage":"basic","passage":"美咲は失敗を隠そうとしていたが、友人に打ち明けたことで解決方法が見つかった。最後には「次は早めに相談する」と言った。","q":"文章の最後に、美咲は次にどうすると言っていますか。","answer":"早めに相談する。","guide":["文章の最後の発言を探そう。","「次は」に続く言葉を取り出そう。"],"retry":"美咲が最後に考えを変えた理由を本文から答えなさい。","explain":"文章全体を読む第一歩として、結末に示された主人公の考えを確かめます。"},{"id":"p73","skill":"文章全体","level":2,"stage":"single","passage":"彩は苦手な発表を避けてきた。ある日、班員が練習につき合ってくれたため、一度だけ挑戦した。失敗もあったが、彩は次の発表にも立候補した。","q":"彩の変化を「最初の姿」「変化のきっかけ」「最後の姿」の順に整理しなさい。","answer":"発表を避けていた彩が、班員の支えで挑戦し、失敗しても次の発表に自ら立候補するようになった。","guide":["【読む場所】文章の初め・中・終わりで話題や考えがどう動くか整理する。","【関係の整理】設問に関わる中心的な変化・対比を選び、部分的な出来事だけで答えない。","【答案】設問「彩の変化を「最初の姿」「変化のきっかけ」「最後の姿」の順に整理しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p74","skill":"文章全体","level":3,"stage":"combined","passage":"町の川は以前、ごみが目立っていた。住民が清掃を始めると、参加者が増え、学校でも川の生き物を調べる活動が始まった。今では川を守ることが町の共通の目標になっている。","q":"文章全体を、問題・取り組み・結果の三つに分けてまとめなさい。","answer":"ごみの多い川を住民が清掃し、参加や学習が広がった結果、川の保全が町全体の目標になった。","guide":["【読む場所】文章の初め・中・終わりで話題や考えがどう動くか整理する。","【関係の整理】設問に関わる中心的な変化・対比を選び、部分的な出来事だけで答えない。","【答案】設問「文章全体を、問題・取り組み・結果の三つに分けてまとめなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p75","skill":"設問分析","level":3,"stage":"combined","passage":"【設問】傍線部の理由を、前の段落の内容を踏まえ、「経験」という語を使って五十字以内で説明しなさい。","q":"示された設問について、①何を答えるか、②参照する範囲、③必ず使う語、④字数制限をそれぞれ答えなさい。","answer":"①傍線部の理由　②前の段落　③「経験」　④五十字以内","guide":["「何を説明しなさい」とあるかを探そう。","「どこの内容を踏まえ」とあるかを確認しよう。","指定された語と字数を別々に書き出そう。"],"retry":"この設問で「前の段落」を読まずに答えると、どの条件を満たさなくなるか答えなさい。","explain":"設問を内容・参照範囲・指定語・字数の四条件に分解します。本文がないため、傍線部の理由そのものは答えません。"},{"id":"p76","skill":"設問分析","level":3,"stage":"combined","passage":"【設問】筆者が地域の行事を続けるべきだと考える理由を、第二段落の内容に触れ、「交流」という語を用いて六十字以内で説明しなさい。","q":"この設問で答案に必ず入れるべき条件を、内容・参照箇所・指定語・字数に分けて整理しなさい。","answer":"内容は行事を続ける理由、参照箇所は第二段落、指定語は「交流」、字数は六十字以内。","guide":["【読む場所】「誰が」「なぜ」「どのように」などの条件に印を付ける。","【関係の整理】答えに必要な要素を分け、設問が求めない情報を入れない。","【答案】設問「この設問で答案に必ず入れるべき条件を、内容・参照箇所・指定語・字数に分けて整理しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p77","skill":"選択肢照合","level":1,"stage":"basic","passage":"本文：健太は少し迷った後、参加することにした。 選択肢：健太は迷うことなく、すぐ参加を決めた。","q":"選択肢のどこが本文と異なるか。","answer":"「少し迷った」に対し「迷うことなく、すぐ」としており、過程が異なる。","guide":["【この問題の焦点】本文と一項目ずつ照合","読み方の型：主体・時点・程度・因果を部品ごとに照合する。","本文の根拠に線を引いてから答えよう。"],"retry":"同じ読み方の型を使って、もう一度答えなさい。","explain":"①読み方確認：主体・時点・程度・因果を部品ごとに照合する。"},{"id":"p78","skill":"抜き出し","level":3,"stage":"combined","passage":"朝の校庭には霜が残っていた。昼になると日差しが強まり、霜は溶けたが、日陰の水たまりには薄い氷が残っていた。夕方には冷たい風が吹き、再び気温が下がった。","q":"昼の校庭で、朝から変わったことを表す部分と、変わらず残っていたことを表す部分を、それぞれ本文からそのまま抜き出しなさい。","answer":"変わったこと：「霜は溶けた」／残っていたこと：「日陰の水たまりには薄い氷が残っていた」","guide":["設問の「昼」と「朝から変わったこと」「残っていたこと」を確認する。","「昼になると」以降から、変化を表す語句と残存を表す語句を別々に探す。","本文の表現を変えずに抜き出し、二つの欄に分ける。"],"retry":"昼の場面に線を引き、「変化」「継続」の二つを混同せず、本文どおりに抜き出し直しなさい。","explain":"「霜は溶けた」は朝からの変化、「日陰の水たまりには薄い氷が残っていた」は昼にも残る状態を示す。どちらも昼の描写から抜き出す。"},{"id":"p79","skill":"抜き出し","level":3,"stage":"combined","passage":"朝、校庭の土は湿っており、霜が残っていた。昼には日差しが強まり、校庭の土が乾いたが、日陰の花壇には霜が残っていた。放課後には冷たい風が吹き始めた。","q":"朝と昼を比べて、変わったことと変わらなかったことを表す部分を、それぞれ本文から抜き出しなさい。","answer":"校庭の土が乾いた／日陰の花壇には霜が残っていた","guide":["朝の状態を確認する。","昼の状態から変化を示す箇所を探す。","同じ昼の状態から継続を示す箇所を探し、二つを区別してそのまま書く。"],"retry":"本文中の根拠を二か所以上示して、設問にもう一度答えなさい。","explain":"本文の一か所だけで決めず、異なる箇所の情報を対応させる。昼の状態から変化を示す箇所を探す。／同じ昼の状態から継続を示す箇所を探し、二つを区別してそのまま書く。"},{"id":"p80","skill":"記述","level":1,"stage":"basic","passage":"美咲は発表を断るつもりだったが、班員が準備を手伝ってくれると知り、自分も挑戦しようと考えた。","q":"美咲が発表に挑戦しようと考えた理由を説明しなさい。","answer":"班員が準備を手伝ってくれると知り、自分も挑戦しようと思ったから。","guide":["【この問題の焦点】本文の根拠を一文にする","読み方の型：原因となる事実と人物の判断をつなぐ。","本文の根拠に線を引いてから答えよう。"],"retry":"同じ読み方の型を使って、もう一度答えなさい。","explain":"①読み方確認：原因となる事実と人物の判断をつなぐ。"},{"id":"p81","skill":"記述","level":2,"stage":"single","passage":"彩は実行委員を断ろうとしていた。だが、先輩が「一人で抱えずに相談していい」と伝え、友人も役割を分担すると約束したため、引き受けることにした。","q":"彩が実行委員を引き受けた理由を、二人の働きかけを含めて説明しなさい。","answer":"先輩に相談してよいと言われ、友人も役割分担を約束したため、一人で抱え込まずにできると思ったから。","guide":["【読む場所】設問が求める理由・変化・根拠などを答案の部品に分ける。","【関係の整理】本文の異なる根拠をつなぎ、問いの形に合わせた一文にまとめる。","【答案】設問「彩が実行委員を引き受けた理由を、二人の働きかけを含めて説明しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p82","skill":"要約","level":1,"stage":"basic","passage":"読書は知らない考え方に触れる機会になる。異なる時代の作品からも、外国の作品からも、自分とは違う見方を知ることができる。","q":"文章を一文で要約しなさい。","answer":"読書によって、自分とは異なるさまざまな考え方に触れられる。","guide":["【この問題の焦点】不要な具体例を削る","読み方の型：具体をまとめて中心内容を残す。","本文の根拠に線を引いてから答えよう。"],"retry":"同じ読み方の型を使って、もう一度答えなさい。","explain":"①読み方確認：具体をまとめて中心内容を残す。"},{"id":"p83","skill":"要約","level":2,"stage":"single","passage":"人は異なる意見に出会うと、自分の考えを見直すことがある。話し合いは勝ち負けを決める場ではなく、相手の理由を聞き、自分の見方を広げる機会である。","q":"本文の中心的な主張を、具体的な説明をまとめて一文で要約しなさい。","answer":"話し合いは意見の勝敗を決めるのではなく、互いの理由を聞いて自分の見方を広げる機会である。","guide":["【読む場所】具体例と筆者の中心的な考えを分けて読む。","【関係の整理】主張と理由の骨組みを残し、例示や繰り返しを削って一文にする。","【答案】設問「本文の中心的な主張を、具体的な説明をまとめて一文で要約しなさい。」で必要な要素を確かめ、本文の言葉を使って答えをまとめる。"],"retry":"本文のどの言葉や行動を根拠にしたか示し、別の言い方でも答えを作りましょう。","explain":"本文の根拠を確認し、設問が求める関係を整理すると、解答例のようにまとめられます。"},{"id":"p084","skill":"主語・主体","level":1,"stage":"basic","passage":"沙耶は急いで教室へ戻った。机の上の資料を手に取ると、廊下にいた優斗へ渡した。沙耶が「先生に届けてくれる？」と頼むと、優斗はうなずいた。","q":"「うなずいた」のは誰ですか。","answer":"優斗","guide":["【この問題の焦点】一文内の主語を特定","① 動作・発言を表す言葉に線を引く。","② 直前に出た人物を候補にする。","③ 「だれが＋その動作」の形で補って、文脈が続くか確かめる。","④ 主語だけを答える。"],"retry":"「うなずいた」のは誰ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「だれが＋その動作」の形で補って、文脈が続くか確かめる。"},{"id":"p085","skill":"主語・主体","level":2,"stage":"single","passage":"「先に始めていて」と真琴が言うと、陸は窓を閉め、机を前へ運んだ。そのあと黒板の日付を書き直した。","q":"「黒板の日付を書き直した」のは誰ですか。","answer":"陸","guide":["【この問題の焦点】省略された主語を動作の連続から補う","① 動作・発言を表す言葉に線を引く。","② 直前に出た人物を候補にする。","③ 「だれが＋その動作」の形で補って、文脈が続くか確かめる。","④ 主語だけを答える。"],"retry":"「黒板の日付を書き直した」のは誰ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「だれが＋その動作」の形で補って、文脈が続くか確かめる。"},{"id":"p086","skill":"指示語","level":1,"stage":"basic","passage":"地域の人に昔の写真を借り、現在の同じ場所でも写真を撮った。この二つを比べることで、町の変化が分かりやすくなった。","q":"「この二つ」が指すものを二つ書きなさい。","answer":"地域の人に借りた昔の写真と、現在の同じ場所で撮った写真。","guide":["【この問題の焦点】直前の語句を指す","① 指示語を丸で囲む。","② 直前の一語だけでなく、前の文・出来事まで候補にする。","③ 候補を指示語の位置に置き換えて意味が通るか確かめる。","④ 必要な範囲を過不足なく答える。"],"retry":"「この二つ」が指すものを二つ書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"候補を指示語の位置に置き換えて意味が通るか確かめる。"},{"id":"p087","skill":"指示語","level":2,"stage":"single","passage":"発表では結論だけでなく、そこに至るまでに調べた資料や考えた順序も示した。そうすることで、聞き手は結論の理由を追いやすくなる。","q":"「そうする」が指す内容を書きなさい。","answer":"結論だけでなく、調べた資料や考えた順序も示すこと。","guide":["【この問題の焦点】前文の内容全体を指す","① 指示語を丸で囲む。","② 直前の一語だけでなく、前の文・出来事まで候補にする。","③ 候補を指示語の位置に置き換えて意味が通るか確かめる。","④ 必要な範囲を過不足なく答える。"],"retry":"「そうする」が指す内容を書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"候補を指示語の位置に置き換えて意味が通るか確かめる。"},{"id":"p088","skill":"接続関係","level":1,"stage":"basic","passage":"この道は駅までの距離が短い。ただし、朝は車が多いため、必ず早く着けるとは限らない。","q":"「ただし」は前の内容にどのような情報を加えていますか。","answer":"前の利点がいつでも成り立つわけではないという条件・制限。","guide":["【この問題の焦点】基本的な順接・逆接","① 接続語の前と後を短く区切る。","② 前後をそれぞれ一言で要約する。","③ 逆接・因果・追加・対比・条件など、関係を決める。","④ 接続語の名前だけでなく、前後がどうつながるか答える。"],"retry":"「ただし」は前の内容にどのような情報を加えていますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"逆接・因果・追加・対比・条件など、関係を決める。"},{"id":"p089","skill":"接続関係","level":2,"stage":"single","passage":"観察を毎日続けた。そのため、小さな変化にも気づくことができた。","q":"「そのため」の前後の関係を説明しなさい。","answer":"毎日観察を続けたことが原因となり、小さな変化に気づけたという因果関係。","guide":["【この問題の焦点】条件・補足・対比を判断","① 接続語の前と後を短く区切る。","② 前後をそれぞれ一言で要約する。","③ 逆接・因果・追加・対比・条件など、関係を決める。","④ 接続語の名前だけでなく、前後がどうつながるか答える。"],"retry":"「そのため」の前後の関係を説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"逆接・因果・追加・対比・条件など、関係を決める。"},{"id":"p090","skill":"因果関係","level":1,"stage":"basic","passage":"図を先に見てから説明文を読んだ。図に出てきた言葉の意味が分かっていたので、文章の内容を追いやすかった。","q":"文章の内容を追いやすかったのはなぜですか。","answer":"先に図を見て、文章に出る言葉の意味を理解していたから。","guide":["【この問題の焦点】直接の原因と結果","① 結果に当たる部分を先に見つける。","② 「なぜ？」と前へ戻って直接の原因を探す。","③ 必要なら原因→途中の変化→結果の順に並べる。","④ 原因と結果が飛ばない一文にする。"],"retry":"文章の内容を追いやすかったのはなぜですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"必要なら原因→途中の変化→結果の順に並べる。"},{"id":"p091","skill":"因果関係","level":2,"stage":"single","passage":"雨で校庭が使えなかったため、練習場所を体育館に変えた。その結果、予定していた長距離走はできず、短い区間の動きを確認した。","q":"練習内容が変わった原因を、途中の出来事も含めて説明しなさい。","answer":"雨で校庭が使えず体育館へ場所を変えたため、長距離走ができなくなったから。","guide":["【この問題の焦点】原因→途中→結果","① 結果に当たる部分を先に見つける。","② 「なぜ？」と前へ戻って直接の原因を探す。","③ 必要なら原因→途中の変化→結果の順に並べる。","④ 原因と結果が飛ばない一文にする。"],"retry":"練習内容が変わった原因を、途中の出来事も含めて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"必要なら原因→途中の変化→結果の順に並べる。"},{"id":"p092","skill":"事実・推測","level":1,"stage":"basic","passage":"発表後、陽菜は原稿を折りたたみ、「思ったより話せた」と言った。席へ戻る途中、何度も友達の方を見て笑った。","q":"本文から確実に分かる事実を二つ書きなさい。","answer":"陽菜が「思ったより話せた」と言ったこと、友達の方を何度も見て笑ったこと。","guide":["【この問題の焦点】本文に書かれた事実を取る","① 本文にそのまま書かれた行動・発言・状態に線を引く。","② 気持ち・理由・予定など、本文にない言葉を分ける。","③ 「本文に直接あるか」で事実か推測か判定する。","④ 推測なら、根拠となる事実も示す。"],"retry":"本文から確実に分かる事実を二つ書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「本文に直接あるか」で事実か推測か判定する。"},{"id":"p093","skill":"事実・推測","level":2,"stage":"single","passage":"拓海は提出箱の前で立ち止まり、答案をもう一度見直してから入れた。","q":"「拓海は自信がなかった」と断定できますか。本文を根拠に答えなさい。","answer":"断定できない。答案を見直した事実はあるが、それだけで自信がなかったとは決められない。","guide":["【この問題の焦点】事実と心情推測を分ける","① 本文にそのまま書かれた行動・発言・状態に線を引く。","② 気持ち・理由・予定など、本文にない言葉を分ける。","③ 「本文に直接あるか」で事実か推測か判定する。","④ 推測なら、根拠となる事実も示す。"],"retry":"「拓海は自信がなかった」と断定できますか。本文を根拠に答えなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「本文に直接あるか」で事実か推測か判定する。"},{"id":"p094","skill":"心情","level":1,"stage":"basic","passage":"結果発表の紙に自分の番号を見つけると、玲奈は一度目を閉じ、それから隣の母を見て笑った。","q":"玲奈が自分の番号を見つけたあと、母に向けてした行動は何ですか。","answer":"母を見て笑った。","guide":["番号を見つけた後の行動を探そう。","「母」を含む部分に線を引こう。"],"retry":"玲奈が番号を見つけた後にした行動を二つ答えなさい。","explain":"Level 1では心情を断定する前に、心情を考える手がかりとなる行動を正確に取り出します。"},{"id":"p095","skill":"心情","level":2,"stage":"single","passage":"直樹は完成した模型を見つめたあと、少しずれた屋根を指で直そうとして、手を止めた。「これも僕ららしいか」と言った。","q":"直樹は最後に模型をどのように受け止めていますか。","answer":"不完全な部分も含めて、自分たちが作ったものとして肯定的に受け入れている。","guide":["【この問題の焦点】状況と行動を組み合わせる","① 心情が問われる人物と場面を確認する。","② 行動・表情・発言・状況から根拠を二つまで拾う。","③ 根拠から言える範囲で心情語を選ぶ。","④ 「～ことから、～気持ち」の形で答える。"],"retry":"直樹は最後に模型をどのように受け止めていますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠から言える範囲で心情語を選ぶ。"},{"id":"p096","skill":"心情変化","level":1,"stage":"basic","passage":"転校初日、紗季は休み時間も席を立てなかった。帰りの会の後、同じ本を読んでいた杏に声をかけられ、翌朝は自分から「おはよう」と言った。","q":"紗季の気持ちの変化を「～から～へ」の形で書きなさい。","answer":"新しい環境で人に話しかけにくい不安な気持ちから、自分から関わってみようとする前向きな気持ちへ。","guide":["【この問題の焦点】変化前後を見つける","① 変化前の行動・発言を探す。","② 変化後の行動・発言を探す。","③ 間にある出来事や気づきを確認する。","④ 「～から、～へ変化した」の形にする。"],"retry":"紗季の気持ちの変化を「～から～へ」の形で書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"間にある出来事や気づきを確認する。"},{"id":"p097","skill":"心情変化","level":2,"stage":"single","passage":"航は自分の案が選ばれず、話し合いの間ずっと黙っていた。しかし完成したポスターを見ると、「この組み合わせの方が見やすいね」と言った。","q":"航の気持ちはどのように変化したと考えられますか。","answer":"自分の案が選ばれず不満・残念に感じる気持ちから、別の案のよさを認め納得する気持ちへ変化した。","guide":["【この問題の焦点】きっかけを含めて整理","① 変化前の行動・発言を探す。","② 変化後の行動・発言を探す。","③ 間にある出来事や気づきを確認する。","④ 「～から、～へ変化した」の形にする。"],"retry":"航の気持ちはどのように変化したと考えられますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"間にある出来事や気づきを確認する。"},{"id":"p098","skill":"きっかけ","level":1,"stage":"basic","passage":"何度練習しても記録が伸びず、優は走るのをやめようかと思った。先輩から以前の記録表を見せられ、少しずつ速くなっていることに気づくと、もう一週間続けることにした。","q":"優が練習を続けようと考え直したきっかけは何ですか。","answer":"以前の記録表を見て、自分が少しずつ速くなっていることに気づいたこと。","guide":["【この問題の焦点】直前の出来事を特定","① 考え・行動が変わった箇所を見つける。","② その直前へ戻る。","③ 変化を生んだ言葉・出来事・気づきを一つに絞る。","④ 必要なら「～に気づいたこと」まで含める。"],"retry":"優が練習を続けようと考え直したきっかけは何ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"変化を生んだ言葉・出来事・気づきを一つに絞る。"},{"id":"p099","skill":"きっかけ","level":2,"stage":"single","passage":"班の意見を自分で決めようとしていた葵は、友人に「私たちは何を考えればいいの？」と言われた。その後、葵は最初に全員へ案を尋ねるようになった。","q":"葵の行動が変わったきっかけを書きなさい。","answer":"友人から「私たちは何を考えればいいの？」と言われ、自分が一人で決めすぎていたことに気づいたこと。","guide":["【この問題の焦点】言葉と気づきを区別","① 考え・行動が変わった箇所を見つける。","② その直前へ戻る。","③ 変化を生んだ言葉・出来事・気づきを一つに絞る。","④ 必要なら「～に気づいたこと」まで含める。"],"retry":"葵の行動が変わったきっかけを書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"変化を生んだ言葉・出来事・気づきを一つに絞る。"},{"id":"p100","skill":"人物像","level":1,"stage":"basic","passage":"健は係の仕事が終わったあとも、翌日使う道具が足りるか一つずつ数えた。誰かに頼まれたわけではなかった。","q":"健はどのような人物だと考えられますか。根拠とともに書きなさい。","answer":"頼まれていなくても必要な確認をすることから、責任感があり先を考えて行動する人物。","guide":["【この問題の焦点】行動から性質を言い換える","① 人物の具体的な行動・発言に線を引く。","② その行動を「どんな考え方・性質か」に言い換える。","③ 一場面だけから言い過ぎていないか確かめる。","④ 根拠＋人物像で答える。"],"retry":"健はどのような人物だと考えられますか。根拠とともに書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一場面だけから言い過ぎていないか確かめる。"},{"id":"p101","skill":"人物像","level":2,"stage":"single","passage":"美月は話し合いで反対意見を聞くと、すぐ言い返さず「どの部分が気になった？」と尋ねた。","q":"美月の人物像を説明しなさい。","answer":"反対意見にも理由を尋ねて理解しようとする、相手の考えを丁寧に聞ける人物。","guide":["【この問題の焦点】発言と行動を合わせる","① 人物の具体的な行動・発言に線を引く。","② その行動を「どんな考え方・性質か」に言い換える。","③ 一場面だけから言い過ぎていないか確かめる。","④ 根拠＋人物像で答える。"],"retry":"美月の人物像を説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一場面だけから言い過ぎていないか確かめる。"},{"id":"p102","skill":"会話文","level":1,"stage":"basic","passage":"「私がやった方が早いよ」と言う千尋に、颯太は「早く終わることだけが目的だったっけ」と返した。その後、千尋は作業を三人に分けた。","q":"颯太は千尋に何を問いかけましたか。本文からそのまま抜き出しなさい。","answer":"早く終わることだけが目的だったっけ","guide":["颯太の発言を示すかぎ括弧を探そう。","発言をそのまま写そう。"],"retry":"颯太の問いかけの後、千尋はどう行動しましたか。","explain":"会話文の基礎では、誰の発言かを確かめて、指定された発言を正確に取り出します。"},{"id":"p103","skill":"会話文","level":2,"stage":"single","passage":"失敗を謝る陸に、先生は「次に同じ場面が来たら、どうする？」と尋ねた。陸は少し考え、「先に確認します」と答えた。","q":"先生が直接注意せず質問したことには、どのような効果がありますか。","answer":"陸自身に失敗の原因と次の行動を考えさせ、改善策を自分の言葉で決めさせる効果。","guide":["【この問題の焦点】相手への働きを読む","① 発言した人と相手を確認する。","② 発言そのものの意味を短くする。","③ 発言の後、相手の行動・考えがどう変わったかを見る。","④ 「この言葉が相手に何をさせたか」で答える。"],"retry":"先生が直接注意せず質問したことには、どのような効果がありますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"発言の後、相手の行動・考えがどう変わったかを見る。"},{"id":"p104","skill":"具体と抽象","level":1,"stage":"basic","passage":"自転車でも楽器でも、最初は一つ一つの動きを意識する。しかし練習を重ねると、細かな動きを毎回考えなくてもできるようになる。技能の習得には、このような変化がある。","q":"本文では、自転車と楽器は何の例として挙げられていますか。","answer":"練習によって、細かな動きを意識しなくてもできるようになるという技能習得の変化。","guide":["「自転車でも楽器でも」の後を読もう。","最後の文で二つの例をまとめる言葉を探そう。"],"retry":"自転車と楽器の例に共通する変化を一文で説明しなさい。","explain":"二つの具体例は、最後の文にある「技能の習得」を説明しています。"},{"id":"p105","skill":"具体と抽象","level":2,"stage":"single","passage":"雨の日に傘を貸す、落とし物を届ける、道を尋ねられて案内する。これらはどれも、相手が今何に困っているかを考えて行う助けである。","q":"三つの例をまとめて表す一文を書きなさい。","answer":"相手が困っていることを考え、その状況に必要な助けをする行動。","guide":["【この問題の焦点】例と一般論を対応","① 具体例を一つずつ短い言葉にする。","② 複数の例に共通する部分を探す。","③ 人名・物名など細部を外して一段上の言葉にする。","④ 本文の抽象的な文と対応するか確かめる。"],"retry":"三つの例をまとめて表す一文を書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"人名・物名など細部を外して一段上の言葉にする。"},{"id":"p106","skill":"人物関係","level":1,"stage":"basic","passage":"初め、陸は何でも先輩の指示を待っていた。文化祭が近づくと、先輩は「次はどうする？」と陸に尋ねるようになり、陸も自分から案を出すようになった。","q":"陸と先輩の関係はどのように変化しましたか。","answer":"先輩が一方的に指示し陸が従う関係から、陸も考えを出し一緒に進める関係へ変化した。","guide":["【この問題の焦点】二人の役割を確認","① 二人それぞれの最初の行動を確認する。","② 後半の二人の行動も確認する。","③ 「指示する／従う」など関係を表す言葉に置き換える。","④ 「～関係から、～関係へ」でまとめる。"],"retry":"陸と先輩の関係はどのように変化しましたか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「指示する／従う」など関係を表す言葉に置き換える。"},{"id":"p107","skill":"人物関係","level":2,"stage":"single","passage":"真帆はいつも妹の忘れ物を届けていた。ある日、妹に「自分で確認したいから、今日は持ってこなくていい」と言われ、それからは出発前に声をかけるだけにした。","q":"真帆と妹の関係の変化を説明しなさい。","answer":"真帆が妹の失敗を代わりに補う関係から、妹が自分で確認できるよう見守る関係へ変化した。","guide":["【この問題の焦点】前後の関係変化を読む","① 二人それぞれの最初の行動を確認する。","② 後半の二人の行動も確認する。","③ 「指示する／従う」など関係を表す言葉に置き換える。","④ 「～関係から、～関係へ」でまとめる。"],"retry":"真帆と妹の関係の変化を説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「指示する／従う」など関係を表す言葉に置き換える。"},{"id":"p108","skill":"表現効果","level":1,"stage":"basic","passage":"教室を出るとき、翔は消しかけの黒板を振り返った。そこには、文化祭までの日数を数えた小さな線が一本だけ残っていた。","q":"最後の文に残っていたものは何ですか。","answer":"文化祭までの日数を数えた小さな線が一本。","guide":["最後の文を読もう。","「残っていた」の主語となるものを探そう。"],"retry":"最後に残った線は何を数えたものでしたか。","explain":"表現効果を考える前に、何が描かれているかを本文に即して確かめます。"},{"id":"p109","skill":"表現効果","level":2,"stage":"single","passage":"発表前の朝は重く感じた楽器のケースが、演奏を無事に終えた帰り道では不思議と軽く感じられた。","q":"同じケースの感じ方を変えて描くことで、何を表していますか。","answer":"物の重さ自体ではなく、演奏を終えた人物の緊張が解け、気持ちが軽くなった変化を表している。","guide":["【この問題の焦点】対比・反復などの効果","① 特徴的な物・音・動作・対比に線を引く。","② その前後の人物の心情や場面を確認する。","③ その表現がなくても伝わる事実と、表現によって強まる印象を分ける。","④ 「～を印象づける／表す」と答える。"],"retry":"同じケースの感じ方を変えて描くことで、何を表していますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"その表現がなくても伝わる事実と、表現によって強まる印象を分ける。"},{"id":"p110","skill":"文章全体","level":1,"stage":"basic","passage":"失敗をなくすには注意することが大切だ。しかし、注意だけでは同じ失敗を防げないこともある。失敗した条件を記録し、起きやすい場面を知れば、事前に方法を変えられる。失敗を振り返る目的は、自分を責めることではなく、次の行動を変えることにある。","q":"筆者が最も伝えたいことを一文でまとめなさい。","answer":"失敗は注意するだけでなく、起きた条件を振り返り、次の行動を変えるために生かすことが大切だ。","guide":["【この問題の焦点】中心文を見つける","① 各文・段落を一言ずつにする。","② 具体例と筆者の考えを分ける。","③ 繰り返される考えと最後の結論を結ぶ。","④ 具体例を削り、文章全体を包む一文にする。"],"retry":"筆者が最も伝えたいことを一文でまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"繰り返される考えと最後の結論を結ぶ。"},{"id":"p111","skill":"文章全体","level":2,"stage":"single","passage":"便利な道具は作業時間を短くする。一方、使えば必ずよい結果になるわけではない。目的に合う道具を選び、結果を確かめながら使う必要がある。道具の価値は、機能の多さだけでなく、使い方によって決まる。","q":"文章全体の主張をまとめなさい。","answer":"便利さや機能だけで道具を評価せず、目的に合わせて選び結果を確かめて使うことが重要である。","guide":["【この問題の焦点】具体例と主張を分ける","① 各文・段落を一言ずつにする。","② 具体例と筆者の考えを分ける。","③ 繰り返される考えと最後の結論を結ぶ。","④ 具体例を削り、文章全体を包む一文にする。"],"retry":"文章全体の主張をまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"繰り返される考えと最後の結論を結ぶ。"},{"id":"p112","skill":"設問分析","level":1,"stage":"basic","passage":"本文中の二つの行動を比べ、主人公の考えがどのように変化したか、理由を含めて八十字以内で説明しなさい。","q":"この設問で答えに必ず入れるべき要素を三つ挙げなさい。","answer":"変化前の考え、変化後の考え、変化した理由。","guide":["【この問題の焦点】何を答えるか確認","① 何について答える問題か丸で囲む。","② 「理由・変化・効果」など答え方を示す語を確認する。","③ 範囲・字数・抜き出しなどの条件を拾う。","④ 必要な答案部品を先に箇条書きする。"],"retry":"この設問で答えに必ず入れるべき要素を三つ挙げなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"範囲・字数・抜き出しなどの条件を拾う。"},{"id":"p113","skill":"設問分析","level":2,"stage":"single","passage":"傍線部の表現が文章全体で果たす役割を、前後の内容に触れながら説明しなさい。","q":"この設問では、本文のどこを確認する必要がありますか。","answer":"傍線部そのもの、直前と直後の内容、文章全体の主張や流れ。","guide":["【この問題の焦点】条件・範囲・字数を分解","① 何について答える問題か丸で囲む。","② 「理由・変化・効果」など答え方を示す語を確認する。","③ 範囲・字数・抜き出しなどの条件を拾う。","④ 必要な答案部品を先に箇条書きする。"],"retry":"この設問では、本文のどこを確認する必要がありますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"範囲・字数・抜き出しなどの条件を拾う。"},{"id":"p114","skill":"選択肢照合","level":1,"stage":"basic","passage":"美紀は発表を断ろうとしていたが、友人の「一緒に練習しよう」という言葉を聞き、翌日から放課後に練習した。","q":"本文に最も合うものを選びなさい。\nア 美紀は最初から発表を楽しみにしていた。\nイ 友人は美紀の代わりに発表した。\nウ 美紀は友人の言葉をきっかけに発表へ向けて行動した。\nエ 美紀は練習しても発表を断った。","answer":"ウ","guide":["【この問題の焦点】本文と一項目ずつ照合","① 選択肢を一つずつ短く区切る。","② 本文の対応箇所を探す。","③ 一部だけ合う選択肢や「必ず・すべて」など強すぎる表現を確認する。","④ 全要素が本文と一致するものを選ぶ。"],"retry":"本文に最も合うものを選びなさい。\nア 美紀は最初から発表を楽しみにしていた。\nイ 友人は美紀の代わりに発表した。\nウ 美紀は友人の言葉をきっかけに発表へ向けて行動した。\nエ 美紀は練習しても発表を断った。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一部だけ合う選択肢や「必ず・すべて」など強すぎる表現を確認する。"},{"id":"p115","skill":"選択肢照合","level":2,"stage":"single","passage":"便利な方法でも、目的が違えば適切とは限らない。方法を選ぶ前に、何を達成したいかを確かめる必要がある。","q":"筆者の考えに最も合うものを選びなさい。\nア 最も速い方法を常に選ぶべきだ。\nイ 方法の良し悪しは目的との関係で判断する必要がある。\nウ 便利な方法は使わない方がよい。\nエ 目的より方法を先に決めるべきだ。","answer":"イ","guide":["【この問題の焦点】一部一致の誤答を除く","① 選択肢を一つずつ短く区切る。","② 本文の対応箇所を探す。","③ 一部だけ合う選択肢や「必ず・すべて」など強すぎる表現を確認する。","④ 全要素が本文と一致するものを選ぶ。"],"retry":"筆者の考えに最も合うものを選びなさい。\nア 最も速い方法を常に選ぶべきだ。\nイ 方法の良し悪しは目的との関係で判断する必要がある。\nウ 便利な方法は使わない方がよい。\nエ 目的より方法を先に決めるべきだ。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一部だけ合う選択肢や「必ず・すべて」など強すぎる表現を確認する。"},{"id":"p116","skill":"抜き出し","level":1,"stage":"basic","passage":"話し合いでは、意見の違いをなくす必要はない。大切なのは、なぜ違うのかを確かめることだ。理由を聞くと、同じ言葉を別の意味で使っていたと分かる場合もある。","q":"意見が違うときに大切なことを表す部分を、十五字以内で抜き出しなさい。","answer":"なぜ違うのかを確かめること","guide":["【この問題の焦点】同じ意味の箇所を探す","① 設問が求める意味を自分の言葉で短くする。","② 指定された段落・範囲から同じ意味の部分を探す。","③ 字数・個数・文末などの条件を確認する。","④ 本文を変えず、指定どおり抜き出す。"],"retry":"意見が違うときに大切なことを表す部分を、十五字以内で抜き出しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"字数・個数・文末などの条件を確認する。"},{"id":"p117","skill":"抜き出し","level":2,"stage":"single","passage":"新しい知識を覚えるだけでは、使えるようになったとは言えない。自分の知っていることと結びつけ、どの場面で使えるかを考えることで、知識は活用しやすくなる。","q":"知識を活用しやすくするために必要なことを表す部分を、本文から二つ抜き出しなさい。","answer":"自分の知っていることと結びつけ／どの場面で使えるかを考える","guide":["【この問題の焦点】範囲・字数条件を満たす","① 設問が求める意味を自分の言葉で短くする。","② 指定された段落・範囲から同じ意味の部分を探す。","③ 字数・個数・文末などの条件を確認する。","④ 本文を変えず、指定どおり抜き出す。"],"retry":"知識を活用しやすくするために必要なことを表す部分を、本文から二つ抜き出しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"字数・個数・文末などの条件を確認する。"},{"id":"p118","skill":"記述","level":1,"stage":"basic","passage":"班で調べた資料は多かったが、発表時間は五分しかなかった。そこで、結論に直接関係する資料を三つ選び、残りは質問されたときに示すことにした。","q":"班が資料を三つに絞った理由を、四十字以内で説明しなさい。","answer":"限られた発表時間で、結論に必要な情報を分かりやすく伝えるため。","guide":["【この問題の焦点】本文の根拠を一文にする","① 設問が求めるものを「理由・変化・効果」などに分類する。","② 本文から根拠となる部分を拾う。","③ 根拠をそのまま写さず、問いに答える関係に組み替える。","④ 字数内で、主語や因果が分かる文にする。"],"retry":"班が資料を三つに絞った理由を、四十字以内で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠をそのまま写さず、問いに答える関係に組み替える。"},{"id":"p119","skill":"記述","level":2,"stage":"single","passage":"奈々は練習で毎回同じ箇所を間違えた。そこで答えだけを直すのではなく、途中の計算を一行ずつ見比べ、符号を変える場所を誤っていると気づいた。","q":"奈々の学習方法のよい点を、本文を根拠に六十字以内で説明しなさい。","answer":"答えの正誤だけで終わらず、途中の過程を比較して間違いが生じる具体的な場所を見つけた点。","guide":["【この問題の焦点】理由・変化など指定関係で書く","① 設問が求めるものを「理由・変化・効果」などに分類する。","② 本文から根拠となる部分を拾う。","③ 根拠をそのまま写さず、問いに答える関係に組み替える。","④ 字数内で、主語や因果が分かる文にする。"],"retry":"奈々の学習方法のよい点を、本文を根拠に六十字以内で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠をそのまま写さず、問いに答える関係に組み替える。"},{"id":"p120","skill":"要約","level":1,"stage":"basic","passage":"人に説明すると、自分では分かっていると思っていた部分で言葉に詰まることがある。そこは理解が曖昧な場所である。説明は相手に伝えるだけでなく、自分の理解を確かめる方法にもなる。","q":"五十字以内で要約しなさい。","answer":"人に説明することは、相手に伝えるだけでなく、自分の理解が曖昧な部分を見つける方法にもなる。","guide":["【この問題の焦点】不要な具体例を削る","① 各文・段落の中心だけを短くする。","② 具体例・繰り返しを削る。","③ 主張と理由、対比、因果など文章の骨組みを残す。","④ 元の意味を変えず指定字数に収める。"],"retry":"五十字以内で要約しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"主張と理由、対比、因果など文章の骨組みを残す。"},{"id":"p121","skill":"要約","level":2,"stage":"single","passage":"予定は行動の順序を決めるのに役立つ。しかし予定外の出来事が起きたとき、最初の計画にこだわると目的を達成しにくくなることもある。計画は守ること自体が目的ではなく、目的に合わせて修正するための土台である。","q":"六十字以内で要約しなさい。","answer":"計画は行動の土台として役立つが、守ること自体を目的にせず、状況と本来の目的に応じて修正する必要がある。","guide":["【この問題の焦点】主張と理由を残す","① 各文・段落の中心だけを短くする。","② 具体例・繰り返しを削る。","③ 主張と理由、対比、因果など文章の骨組みを残す。","④ 元の意味を変えず指定字数に収める。"],"retry":"六十字以内で要約しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"主張と理由、対比、因果など文章の骨組みを残す。"},{"id":"p122","skill":"主語・主体","level":2,"stage":"single","passage":"資料を読み終えた彩乃は、向かいの健太に渡した。受け取るとすぐ、重要だと思う部分に線を引き始めた。","q":"「線を引き始めた」のは誰ですか。","answer":"健太","guide":["【この問題の焦点】省略された主語を動作の連続から補う","① 動作・発言を表す言葉に線を引く。","② 直前に出た人物を候補にする。","③ 「だれが＋その動作」の形で補って、文脈が続くか確かめる。","④ 主語だけを答える。"],"retry":"「線を引き始めた」のは誰ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「だれが＋その動作」の形で補って、文脈が続くか確かめる。"},{"id":"p123","skill":"主語・主体","level":3,"stage":"combined","passage":"先生が「準備できた人から始めて」と言った。真帆は鉛筆を置いたまま問題用紙を見ていた。隣の亮がページをめくると、真帆は名前を書き、続いて問題を解き始めた。廊下では先生が別の生徒に声をかけていた。","q":"「名前を書いた」「問題を解き始めた」の主体をそれぞれ答え、主体を判断できる本文のつながりを説明しなさい。","answer":"どちらも真帆。亮がページをめくった後、「真帆は名前を書き」と明示され、その後の「続いて」も真帆の動作をつないでいる。","guide":["【この問題の焦点】本文の離れた情報を結びつける","設問で求められている要素を二つ以上に分けて確認しよう。","本文からそれぞれの根拠に線を引き、順序・対比・因果の関係を整理しよう。","根拠同士をつないで説明し、本文にない断定を加えていないか確かめよう。"],"retry":"本文中の根拠を二か所以上挙げ、それらの関係が分かるようにもう一度答えなさい。","explain":"本文の一か所だけではなく、複数の情報を対応づけることが必要です。解答例と本文の根拠を照合し、関係を説明できているか確認します。"},{"id":"p124","skill":"指示語","level":2,"stage":"single","passage":"町では空き地に花を植え、商店の前にも同じ花の鉢を置いた。こうした取り組みを続けた結果、通り全体にまとまりが生まれた。","q":"「こうした取り組み」が指す内容を書きなさい。","answer":"空き地に花を植え、商店の前にも同じ花の鉢を置く取り組み。","guide":["【この問題の焦点】前文の内容全体を指す","① 指示語を丸で囲む。","② 直前の一語だけでなく、前の文・出来事まで候補にする。","③ 候補を指示語の位置に置き換えて意味が通るか確かめる。","④ 必要な範囲を過不足なく答える。"],"retry":"「こうした取り組み」が指す内容を書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"候補を指示語の位置に置き換えて意味が通るか確かめる。"},{"id":"p125","skill":"指示語","level":3,"stage":"combined","passage":"調べた情報をすべて発表に入れると、何が重要なのか伝わりにくくなる。発表の目的に合う情報だけを選ぶ必要がある。この判断をしないまま資料を増やすと、聞き手は要点をつかめない。","q":"「この判断」が指す内容を、判断の基準と行動の両方を含めて説明しなさい。","answer":"発表の目的に合っているかを基準に、調べた情報の中から使う情報を選ぶこと。","guide":["「この判断」の直前の文を確認する。","何を基準に、何を選ぶ判断なのかを分けて考える。","基準と行動の両方が入るように説明する。"],"retry":"「基準」と「選ぶもの」を本文から探し、「この判断」を具体的な言葉に置き換えなさい。","explain":"「この判断」は、直前の「発表の目的に合う情報だけを選ぶ」ことを指す。単に「情報を選ぶ」だけでは判断基準が抜ける。"},{"id":"p126","skill":"接続関係","level":2,"stage":"single","passage":"練習時間を増やせば、できることは増える。とはいえ、同じ間違いを繰り返すだけなら、時間を増やすだけでは十分ではない。","q":"「とはいえ」は前後をどのようにつないでいますか。","answer":"前の内容を認めながら、それだけでは十分でないという制限を加えている。","guide":["【この問題の焦点】条件・補足・対比を判断","① 接続語の前と後を短く区切る。","② 前後をそれぞれ一言で要約する。","③ 逆接・因果・追加・対比・条件など、関係を決める。","④ 接続語の名前だけでなく、前後がどうつながるか答える。"],"retry":"「とはいえ」は前後をどのようにつないでいますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"逆接・因果・追加・対比・条件など、関係を決める。"},{"id":"p127","skill":"接続関係","level":3,"stage":"combined","passage":"観察結果は予想と違っていた。班の多くは実験が失敗したと考えた。しかし、先生は「むしろ、その違いが大事な発見につながるかもしれない」と言った。そこで班は条件を一つずつ確かめ直し、予想していなかった温度の影響に気づいた。","q":"「しかし」と「むしろ」はそれぞれ何を対比・強調していますか。班と先生の考え方の違いを踏まえて説明しなさい。","answer":"「しかし」は予想と違う結果を失敗と考える班と、発見の手がかりと考える先生を対比し、「むしろ」は予想外の違いにこそ価値があることを強調している。","guide":["班が観察結果をどう評価したかを押さえる。","先生の発言が班の評価とどう異なるかを整理する。","「しかし」の対比と「むしろ」の積極的な評価を分けて説明する。"],"retry":"「失敗」と「発見の手がかり」を対比させ、二つの接続語の役割を別々に書き直しなさい。","explain":"「しかし」は前後の評価の対立を示し、「むしろ」は否定的に見られた違いを積極的な価値として捉え直す働きをする。"},{"id":"p128","skill":"因果関係","level":2,"stage":"single","passage":"班員ごとに別々の資料を読んでいたため、同じ言葉を違う意味で使っていることに気づかなかった。そこで最初に用語の意味を確認すると、話し合いが進み始めた。","q":"話し合いが進まなかった原因と、進み始めた理由をそれぞれ書きなさい。","answer":"進まなかった原因は用語の意味を共有していなかったこと。進み始めた理由は最初にその意味を確認したこと。","guide":["【この問題の焦点】原因→途中→結果","① 結果に当たる部分を先に見つける。","② 「なぜ？」と前へ戻って直接の原因を探す。","③ 必要なら原因→途中の変化→結果の順に並べる。","④ 原因と結果が飛ばない一文にする。"],"retry":"話し合いが進まなかった原因と、進み始めた理由をそれぞれ書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"必要なら原因→途中の変化→結果の順に並べる。"},{"id":"p129","skill":"因果関係","level":3,"stage":"combined","passage":"同じ種類の植物を二鉢用意し、水の量と温度をそろえた。一方だけを棚の奥へ移すと、その鉢の葉は窓の方向へ傾いた。窓際に置いた鉢には目立った変化がなかった。","q":"葉が傾いた原因として考えられることを、二鉢の条件と結果の違いを根拠に説明しなさい。","answer":"水の量と温度をそろえた二鉢のうち、棚の奥に移した鉢だけ葉が窓の方向へ傾いたため、置き場所による光の当たり方の違いが原因と考えられる。","guide":["【この問題の焦点】本文の離れた情報を結びつける","設問で求められている要素を二つ以上に分けて確認しよう。","本文からそれぞれの根拠に線を引き、順序・対比・因果の関係を整理しよう。","根拠同士をつないで説明し、本文にない断定を加えていないか確かめよう。"],"retry":"本文中の根拠を二か所以上挙げ、それらの関係が分かるようにもう一度答えなさい。","explain":"本文の一か所だけではなく、複数の情報を対応づけることが必要です。解答例と本文の根拠を照合し、関係を説明できているか確認します。"},{"id":"p130","skill":"事実・推測","level":2,"stage":"single","passage":"昼休み、海斗は弁当を半分残し、午後の試合予定表を三度確認した。友人が話しかけると「大丈夫」と笑った。","q":"「海斗は試合を前に緊張していた」は事実ですか、推測ですか。根拠も書きなさい。","answer":"推測。弁当を半分残し予定表を三度確認した事実から考えられるが、緊張しているとは直接書かれていない。","guide":["【この問題の焦点】事実と心情推測を分ける","① 本文にそのまま書かれた行動・発言・状態に線を引く。","② 気持ち・理由・予定など、本文にない言葉を分ける。","③ 「本文に直接あるか」で事実か推測か判定する。","④ 推測なら、根拠となる事実も示す。"],"retry":"「海斗は試合を前に緊張していた」は事実ですか、推測ですか。根拠も書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「本文に直接あるか」で事実か推測か判定する。"},{"id":"p131","skill":"事実・推測","level":3,"stage":"combined","passage":"放課後、教室の窓が開いており、机の上にあった紙が床に散らばっていた。窓のそばのカーテンは揺れていた。一方、昼休みには生徒が机を動かしていた。紙が落ちた瞬間を見た人はいない。","q":"紙が床に落ちた原因として「風」と「人が机を動かしたこと」の二つが考えられる。本文で確かめられる事実と、断定できないことを分けて説明しなさい。","answer":"窓が開きカーテンが揺れていたこと、昼休みに生徒が机を動かしたことは事実だが、紙が落ちた瞬間の記述はなく、どちらが原因か断定できない。","guide":["観察された事実を二つ以上抜き出す。","二つの原因候補をそれぞれ事実と対応させる。","どの情報が欠けているため原因を断定できないか示す。"],"retry":"本文中の根拠を二か所以上示して、設問にもう一度答えなさい。","explain":"本文の一か所だけで決めず、異なる箇所の情報を対応させる。二つの原因候補をそれぞれ事実と対応させる。／どの情報が欠けているため原因を断定できないか示す。"},{"id":"p132","skill":"心情","level":2,"stage":"single","passage":"表彰式が終わると、奏は賞状を筒に入れず、何度も開いて名前を確かめた。","q":"奏の心情を、行動を根拠に説明しなさい。","answer":"賞状を何度も開いて名前を確かめていることから、受賞したことがうれしく、まだ実感しきれないほど喜んでいる。","guide":["【この問題の焦点】状況と行動を組み合わせる","① 心情が問われる人物と場面を確認する。","② 行動・表情・発言・状況から根拠を二つまで拾う。","③ 根拠から言える範囲で心情語を選ぶ。","④ 「～ことから、～気持ち」の形で答える。"],"retry":"奏の心情を、行動を根拠に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠から言える範囲で心情語を選ぶ。"},{"id":"p133","skill":"心情","level":3,"stage":"combined","passage":"友人が先に帰った教室で、梨花は二人分用意していた紙コップの一つをしばらく見てから、棚へ戻した。","q":"梨花の心情として考えられるものを、根拠とともに書きなさい。","answer":"友人のために用意した紙コップを見てから戻していることから、一緒に過ごせなくなったことを残念・寂しく感じている。","guide":["【この問題の焦点】複数の感情が混じる場面を読む","① 心情が問われる人物と場面を確認する。","② 行動・表情・発言・状況から根拠を二つまで拾う。","③ 根拠から言える範囲で心情語を選ぶ。","④ 「～ことから、～気持ち」の形で答える。"],"retry":"梨花の心情として考えられるものを、根拠とともに書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠から言える範囲で心情語を選ぶ。"},{"id":"p134","skill":"心情変化","level":2,"stage":"single","passage":"初めは「僕には関係ない」と言っていた翔が、地域の人から昔の写真を見せてもらった後、自分から追加の質問を書き始めた。","q":"翔の気持ちの変化と、その変化が分かる行動を書きなさい。","answer":"地域調査に無関心な気持ちから関心を持つ気持ちへ変化し、自分から追加の質問を書き始めた。","guide":["【この問題の焦点】きっかけを含めて整理","① 変化前の行動・発言を探す。","② 変化後の行動・発言を探す。","③ 間にある出来事や気づきを確認する。","④ 「～から、～へ変化した」の形にする。"],"retry":"翔の気持ちの変化と、その変化が分かる行動を書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"間にある出来事や気づきを確認する。"},{"id":"p135","skill":"心情変化","level":3,"stage":"combined","passage":"美緒は自分の絵を展示することを嫌がっていた。展示後、知らない生徒から「この空の色が好き」と言われ、片づけのときには作品を少し離れて眺めていた。","q":"美緒の作品に対する気持ちの変化を説明しなさい。","answer":"人に見せることを嫌がる否定的・不安な気持ちから、他者の言葉を受けて自分の作品を見直そうとする気持ちへ変化した。","guide":["【この問題の焦点】段階的な変化を追う","① 変化前の行動・発言を探す。","② 変化後の行動・発言を探す。","③ 間にある出来事や気づきを確認する。","④ 「～から、～へ変化した」の形にする。"],"retry":"美緒の作品に対する気持ちの変化を説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"間にある出来事や気づきを確認する。"},{"id":"p136","skill":"きっかけ","level":2,"stage":"single","passage":"悠真は何度も説明しても伝わらないのは相手のせいだと思っていた。妹に「その言葉の意味が分からない」と言われ、自分が専門用語を説明せず使っていたことに気づいた。","q":"悠真が説明の仕方を見直すきっかけは何ですか。","answer":"妹から言葉の意味が分からないと言われ、自分が専門用語を説明せず使っていたと気づいたこと。","guide":["【この問題の焦点】言葉と気づきを区別","① 考え・行動が変わった箇所を見つける。","② その直前へ戻る。","③ 変化を生んだ言葉・出来事・気づきを一つに絞る。","④ 必要なら「～に気づいたこと」まで含める。"],"retry":"悠真が説明の仕方を見直すきっかけは何ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"変化を生んだ言葉・出来事・気づきを一つに絞る。"},{"id":"p137","skill":"きっかけ","level":3,"stage":"combined","passage":"遥は発表資料を完成させたつもりだった。友人から「この数字は何と比べれば多いの？」と聞かれたが、その場では答えられなかった。そこで前年の数字を調べて加えた。発表練習では「増えた割合も示すと分かりやすい」と助言され、今度は割合も計算して書き加えた。","q":"遥が資料を二度直したそれぞれのきっかけと、直した内容を対応させて説明しなさい。","answer":"最初は友人から比較対象を尋ねられて答えられず、前年の数字を加えた。次は練習で割合を示すよう助言され、増えた割合を書き加えた。","guide":["資料が変更された箇所を二つ探す。","それぞれの変更の直前にある質問・助言を探す。","「きっかけ→変更内容」を一組ずつ対応させて答える。"],"retry":"二つの修正について「きっかけ／変更内容」の表を作り、順番を保って説明し直しなさい。","explain":"最初の修正は比較対象が分からないという質問、二度目は割合を示すという助言がきっかけ。質問と助言を混同しない。"},{"id":"p138","skill":"人物像","level":2,"stage":"single","passage":"紗良は自分の案が採用されたあとも、反対していた人に「気になるところがあれば言って」と声をかけ、修正点をメモした。","q":"紗良はどのような人物ですか。","answer":"自分の案が選ばれても他者の意見を聞き、よりよくしようとする柔軟で協力的な人物。","guide":["【この問題の焦点】発言と行動を合わせる","① 人物の具体的な行動・発言に線を引く。","② その行動を「どんな考え方・性質か」に言い換える。","③ 一場面だけから言い過ぎていないか確かめる。","④ 根拠＋人物像で答える。"],"retry":"紗良はどのような人物ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一場面だけから言い過ぎていないか確かめる。"},{"id":"p139","skill":"人物像","level":3,"stage":"combined","passage":"遼は係の失敗を先生に報告するとき、「みんなが確認しなかった」ではなく、「僕が確認する時間を決めていませんでした」と説明した。","q":"遼の人物像を、発言を根拠に説明しなさい。","answer":"失敗を他人のせいにせず、自分の行動の問題として振り返る責任感のある人物。","guide":["【この問題の焦点】複数場面から一貫した人物像を作る","① 人物の具体的な行動・発言に線を引く。","② その行動を「どんな考え方・性質か」に言い換える。","③ 一場面だけから言い過ぎていないか確かめる。","④ 根拠＋人物像で答える。"],"retry":"遼の人物像を、発言を根拠に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一場面だけから言い過ぎていないか確かめる。"},{"id":"p140","skill":"会話文","level":2,"stage":"single","passage":"「この案でいい人？」と聞く班長に、結衣は「反対の人の理由も聞かなくていい？」と言った。その後、班長は反対意見を尋ねた。","q":"結衣の発言は話し合いにどのような働きをしていますか。","answer":"多数決だけで決めず、反対意見の理由も検討する方向へ話し合いを変える働き。","guide":["【この問題の焦点】相手への働きを読む","① 発言した人と相手を確認する。","② 発言そのものの意味を短くする。","③ 発言の後、相手の行動・考えがどう変わったかを見る。","④ 「この言葉が相手に何をさせたか」で答える。"],"retry":"結衣の発言は話し合いにどのような働きをしていますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"発言の後、相手の行動・考えがどう変わったかを見る。"},{"id":"p141","skill":"会話文","level":3,"stage":"combined","passage":"弟は「次は間違えないようにする」と言った。兄は「どこで間違えやすいか分かってる？」と聞いた。弟は前のノートを開き、計算の途中で符号を変え忘れた箇所に印を付けた。兄は「そこを確かめる方法も決めよう」と続けた。","q":"兄の二つの問いかけは、弟の学習の仕方をどのように変えようとしているか。弟の行動と結び付けて説明しなさい。","answer":"漠然と気を付けるだけでなく、過去の誤りの箇所を特定し、次に確認する方法まで具体化させようとしている。","guide":["兄の最初の質問と弟の行動を対応させる。","兄の次の言葉が何を付け加えたか考える。","「誤りの特定」と「確認方法」の二段階で説明する。"],"retry":"本文中の根拠を二か所以上示して、設問にもう一度答えなさい。","explain":"本文の一か所だけで決めず、異なる箇所の情報を対応させる。兄の次の言葉が何を付け加えたか考える。／「誤りの特定」と「確認方法」の二段階で説明する。"},{"id":"p142","skill":"具体と抽象","level":2,"stage":"single","passage":"地図を回して進行方向に合わせる人もいれば、北を上にしたまま読む人もいる。メモを文章で残す人も、図で残す人もいる。情報の扱い方には、人によって使いやすい形がある。","q":"前の二つの例は、最後の文のどの内容を具体的に示していますか。","answer":"情報の扱い方には、人によって使いやすい形があること。","guide":["【この問題の焦点】例と一般論を対応","① 具体例を一つずつ短い言葉にする。","② 複数の例に共通する部分を探す。","③ 人名・物名など細部を外して一段上の言葉にする。","④ 本文の抽象的な文と対応するか確かめる。"],"retry":"前の二つの例は、最後の文のどの内容を具体的に示していますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"人名・物名など細部を外して一段上の言葉にする。"},{"id":"p143","skill":"具体と抽象","level":3,"stage":"combined","passage":"失敗した問題に印を付ける、原因を一言書く、翌日にもう一度解く。こうした工夫は、間違いを次の学習に利用する方法である。","q":"三つの具体例を一つの抽象的な表現にまとめなさい。","answer":"間違いを記録・分析・再挑戦して、次の学習に生かす工夫。","guide":["【この問題の焦点】複数例を一段上の概念にする","① 具体例を一つずつ短い言葉にする。","② 複数の例に共通する部分を探す。","③ 人名・物名など細部を外して一段上の言葉にする。","④ 本文の抽象的な文と対応するか確かめる。"],"retry":"三つの具体例を一つの抽象的な表現にまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"人名・物名など細部を外して一段上の言葉にする。"},{"id":"p144","skill":"人物関係","level":2,"stage":"single","passage":"以前、咲は分からないことがあるたびに姉に答えを聞いていた。最近、姉は答えを言わず「どこまで分かった？」と聞き、咲も自分の考えを説明するようになった。","q":"咲と姉の関係はどう変化しましたか。","answer":"姉が答えを与え咲が受け取る関係から、姉の問いを手がかりに咲自身が考える関係へ変化した。","guide":["【この問題の焦点】前後の関係変化を読む","① 二人それぞれの最初の行動を確認する。","② 後半の二人の行動も確認する。","③ 「指示する／従う」など関係を表す言葉に置き換える。","④ 「～関係から、～関係へ」でまとめる。"],"retry":"咲と姉の関係はどう変化しましたか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「指示する／従う」など関係を表す言葉に置き換える。"},{"id":"p145","skill":"人物関係","level":3,"stage":"combined","passage":"部長の圭は一年生に細かく指示していたが、後半は「今日は何を進める？」と尋ねるようになった。一年生も自分たちで役割を決めた。","q":"圭と一年生の関係の変化を説明しなさい。","answer":"圭が一方的に指示する関係から、一年生も判断し役割を決める自立的・協力的な関係へ変化した。","guide":["【この問題の焦点】相互作用から関係を説明","① 二人それぞれの最初の行動を確認する。","② 後半の二人の行動も確認する。","③ 「指示する／従う」など関係を表す言葉に置き換える。","④ 「～関係から、～関係へ」でまとめる。"],"retry":"圭と一年生の関係の変化を説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「指示する／従う」など関係を表す言葉に置き換える。"},{"id":"p146","skill":"表現効果","level":2,"stage":"single","passage":"発表前、時計の秒針の音だけがやけに大きく聞こえた。名前を呼ばれた瞬間、その音は聞こえなくなった。","q":"秒針の音の描写にはどのような効果がありますか。","answer":"発表を待つ人物が時間を強く意識するほど緊張していたことと、呼ばれた瞬間に意識が発表へ集中したことを表す。","guide":["【この問題の焦点】対比・反復などの効果","① 特徴的な物・音・動作・対比に線を引く。","② その前後の人物の心情や場面を確認する。","③ その表現がなくても伝わる事実と、表現によって強まる印象を分ける。","④ 「～を印象づける／表す」と答える。"],"retry":"秒針の音の描写にはどのような効果がありますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"その表現がなくても伝わる事実と、表現によって強まる印象を分ける。"},{"id":"p147","skill":"表現効果","level":3,"stage":"combined","passage":"祖父の店を出るとき、健はいつも鳴る戸の鈴をゆっくり鳴らした。","q":"「ゆっくり鳴らした」という描写から、どのような効果が生まれていますか。","answer":"戸の鈴をゆっくり鳴らす動作によって、店を離れることへのためらいや名残惜しさを感じさせる効果。","guide":["「いつも鳴る」と「ゆっくり鳴らした」に印をつけよう。","普段と異なる鳴らし方から、どのような気持ちが伝わるか考えよう。","本文にない過去の出来事を決めつけず、描写の効果を説明しよう。"],"retry":"「ゆっくり鳴らした」という描写から、どのような効果が生まれていますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「ゆっくり」という動作の描写から、店を離れる際の気持ちを読み取る。本文に書かれていない「記憶を確かめた」などの事情までは断定しない。"},{"id":"p148","skill":"文章全体","level":2,"stage":"single","passage":"質問することは、知らないことを相手に聞くだけではない。自分がどこまで分かり、どこから分からないかを確かめる行為でもある。よい質問を作ろうとすると、自分の理解の境界が見えてくる。","q":"この文章の中心的な考えをまとめなさい。","answer":"質問することには、答えを得るだけでなく、自分の理解できている範囲と分からない範囲を明確にする働きがある。","guide":["【この問題の焦点】具体例と主張を分ける","① 各文・段落を一言ずつにする。","② 具体例と筆者の考えを分ける。","③ 繰り返される考えと最後の結論を結ぶ。","④ 具体例を削り、文章全体を包む一文にする。"],"retry":"この文章の中心的な考えをまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"繰り返される考えと最後の結論を結ぶ。"},{"id":"p149","skill":"文章全体","level":3,"stage":"combined","passage":"二つの町の地図を比べると、駅の数が違うと分かる。しかし、数の違いだけでは交通の便利さは決められない。駅までの距離や列車の本数も調べる必要がある。比較は違いを見つけて終わりではない。違いが生活にどんな意味をもつか、別の条件も確かめて考えることで理解が深まる。","q":"筆者が駅の数の例を挙げた理由を説明したうえで、文章全体の主張をまとめなさい。","answer":"駅の数だけでは便利さを判断できない例を通して、比較では表面的な違いだけでなく、ほかの条件や違いの意味まで確かめることが大切だと述べている。","guide":["具体例で何を比べているか確認する。","数だけで判断できない理由を探す。","具体例の役割と最後の一般的な主張を結び付ける。"],"retry":"本文中の根拠を二か所以上示して、設問にもう一度答えなさい。","explain":"本文の一か所だけで決めず、異なる箇所の情報を対応させる。数だけで判断できない理由を探す。／具体例の役割と最後の一般的な主張を結び付ける。"},{"id":"p150","skill":"設問分析","level":2,"stage":"single","passage":"「本文中の言葉を使って、主人公が考えを変えた理由を五十字以内で説明しなさい。」","q":"この設問の条件を三つに分けなさい。","answer":"本文中の言葉を使うこと、考えを変えた理由を書くこと、五十字以内にすること。","guide":["【この問題の焦点】条件・範囲・字数を分解","① 何について答える問題か丸で囲む。","② 「理由・変化・効果」など答え方を示す語を確認する。","③ 範囲・字数・抜き出しなどの条件を拾う。","④ 必要な答案部品を先に箇条書きする。"],"retry":"この設問の条件を三つに分けなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"範囲・字数・抜き出しなどの条件を拾う。"},{"id":"p151","skill":"設問分析","level":3,"stage":"combined","passage":"「傍線部と同じ内容を表す一文を、第三段落から抜き出し、最初の五字を書きなさい。」","q":"答える前に確認すべき条件を整理しなさい。","answer":"傍線部と同じ内容であること、第三段落から探すこと、一文を特定すること、その最初の五字だけを書くこと。","guide":["【この問題の焦点】必要な答案部品を整理","① 何について答える問題か丸で囲む。","② 「理由・変化・効果」など答え方を示す語を確認する。","③ 範囲・字数・抜き出しなどの条件を拾う。","④ 必要な答案部品を先に箇条書きする。"],"retry":"答える前に確認すべき条件を整理しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"範囲・字数・抜き出しなどの条件を拾う。"},{"id":"p152","skill":"選択肢照合","level":2,"stage":"single","passage":"新しい方法は便利だが、慣れている方法より必ず優れているわけではない。目的や使う場面によって選ぶ必要がある。","q":"本文と一致するものを選びなさい。\nア 新しい方法は常に最もよい。\nイ 慣れた方法は変えるべきではない。\nウ 方法は新しさではなく目的や場面も考えて選ぶ。\nエ 便利な方法ほど使い方を考える必要はない。","answer":"ウ","guide":["【この問題の焦点】一部一致の誤答を除く","① 選択肢を一つずつ短く区切る。","② 本文の対応箇所を探す。","③ 一部だけ合う選択肢や「必ず・すべて」など強すぎる表現を確認する。","④ 全要素が本文と一致するものを選ぶ。"],"retry":"本文と一致するものを選びなさい。\nア 新しい方法は常に最もよい。\nイ 慣れた方法は変えるべきではない。\nウ 方法は新しさではなく目的や場面も考えて選ぶ。\nエ 便利な方法ほど使い方を考える必要はない。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一部だけ合う選択肢や「必ず・すべて」など強すぎる表現を確認する。"},{"id":"p153","skill":"選択肢照合","level":3,"stage":"combined","passage":"健太は練習試合で失敗した場面だけを記録していた。ある日、成功した場面も書き加えると、成功したときは仲間に声をかけてから動いていたことに気づいた。ただし、声かけだけが成功の原因かどうかは、相手の動きなども調べなければ分からない。","q":"本文と合うものを一つ選び、ほかの選択肢のうち一つが誤っている理由も説明しなさい。\nア　声かけが成功の唯一の原因だと確定した。\nイ　成功と失敗の記録を比べて違いに気づいたが、原因の断定には追加の確認が必要である。\nウ　失敗した場面の記録をすべて捨てた。\nエ　相手の動きは成功に関係しないと分かった。","answer":"イ。例えばアは、声かけ以外の条件をまだ確かめておらず、唯一の原因とは断定できないため誤り。","guide":["まず記録した場面の種類がどう変わったか整理しよう。","比較から気づいたことと、まだ確かめていないことを分けよう。","各選択肢の「唯一」「すべて」「関係しない」のような断定表現を本文と照合しよう。"],"retry":"声かけ以外に確かめるべき条件を本文から一つ挙げ、原因を断定できない理由を書きなさい。","explain":"比較によって差に気づくことと、原因を確定することは異なる。正しい選択肢の選定に加え、誤答の根拠を本文から説明する。"},{"id":"p154","skill":"抜き出し","level":2,"stage":"single","passage":"説明を分かりやすくするには、情報を増やせばよいとは限らない。相手がすでに知っていることを考え、必要な情報を選ぶことが重要である。","q":"分かりやすい説明のために重要なことを、二十五字以内で抜き出しなさい。","answer":"必要な情報を選ぶこと","guide":["【この問題の焦点】範囲・字数条件を満たす","① 設問が求める意味を自分の言葉で短くする。","② 指定された段落・範囲から同じ意味の部分を探す。","③ 字数・個数・文末などの条件を確認する。","④ 本文を変えず、指定どおり抜き出す。"],"retry":"分かりやすい説明のために重要なことを、二十五字以内で抜き出しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"字数・個数・文末などの条件を確認する。"},{"id":"p155","skill":"抜き出し","level":3,"stage":"combined","passage":"自分と違う意見を読むとき、すぐに賛成か反対かを決めるのではなく、まずその意見がどのような理由から出てきたのかを確かめたい。理由を知ると、意見の違いが生まれた場所が見えることがある。","q":"意見の違いを理解するため、最初にすべきことを表す部分を抜き出しなさい。","answer":"その意見がどのような理由から出てきたのかを確かめたい","guide":["【この問題の焦点】複数候補から最適箇所を選ぶ","① 設問が求める意味を自分の言葉で短くする。","② 指定された段落・範囲から同じ意味の部分を探す。","③ 字数・個数・文末などの条件を確認する。","④ 本文を変えず、指定どおり抜き出す。"],"retry":"意見の違いを理解するため、最初にすべきことを表す部分を抜き出しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"字数・個数・文末などの条件を確認する。"},{"id":"p156","skill":"記述","level":2,"stage":"single","passage":"同じ説明を聞いても、初めて学ぶ人とすでに知識がある人では、分かりにくい場所が異なる。発表者は、聞き手が何を知っているかを考えて説明を組み立てた。","q":"発表者が聞き手の知識を考える必要がある理由を五十字以内で説明しなさい。","answer":"聞き手の知識によって必要な説明や分かりにくい部分が異なるため、相手に合う情報を選ぶ必要があるから。","guide":["【この問題の焦点】理由・変化など指定関係で書く","① 設問が求めるものを「理由・変化・効果」などに分類する。","② 本文から根拠となる部分を拾う。","③ 根拠をそのまま写さず、問いに答える関係に組み替える。","④ 字数内で、主語や因果が分かる文にする。"],"retry":"発表者が聞き手の知識を考える必要がある理由を五十字以内で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠をそのまま写さず、問いに答える関係に組み替える。"},{"id":"p157","skill":"記述","level":3,"stage":"combined","passage":"同じ道具を使った二回の実験で、二回目だけ予想と異なる結果が出た。班は失敗として捨てず、記録を比べた。材料の量と測定時刻は同じだったが、二回目は室温が高かった。ただし、温度以外の見落としがないか、次の実験で確かめることにした。","q":"班が予想外の結果を捨てなかった理由と、原因について現時点で言える範囲を、二回の実験の比較を根拠に六十字以内で説明しなさい。","answer":"予想と異なる結果も原因を探る手がかりになるから。室温の違いが原因の可能性はあるが、まだ断定できない。","guide":["二回で共通する条件と異なる条件を分けよう。","異なる条件が原因の候補になる理由を考えよう。","「原因と確定した」と書かず、再実験の必要性まで六十字以内でまとめよう。"],"retry":"二回の実験で共通していた条件を二つ挙げ、室温についてまだ断定できない理由を書きなさい。","explain":"条件比較から原因の候補は示せるが、検証前に断定はできない。理由と判断の限界を含める。"},{"id":"p158","skill":"要約","level":2,"stage":"single","passage":"便利な機能が増えると、できることも増える。しかし選択肢が多すぎると、どれを使えばよいか迷うこともある。機能の多さと使いやすさは同じではない。","q":"五十字以内で要約しなさい。本文の根拠と設問条件を確認して答えなさい。","answer":"機能が多いとできることは増えるが、選択に迷うこともあり、機能の多さがそのまま使いやすさとは限らない。","guide":["【この問題の焦点】主張と理由を残す","① 各文・段落の中心だけを短くする。","② 具体例・繰り返しを削る。","③ 主張と理由、対比、因果など文章の骨組みを残す。","④ 元の意味を変えず指定字数に収める。"],"retry":"五十字以内で要約しなさい。","explain":"主張と理由、対比、因果など文章の骨組みを残す。"},{"id":"p159","skill":"要約","level":3,"stage":"combined","passage":"記憶だけに頼ると、以前の自分との違いを正確に比べにくい。短い記録でも残しておけば、後から変化を確かめられる。記録は成長を実感する手がかりにもなる。","q":"五十字以内で要約しなさい。本文の根拠と設問条件を確認して答えなさい。","answer":"短い記録を残せば、記憶だけでは分かりにくい過去との違いを比べ、自分の成長を確かめられる。","guide":["【この問題の焦点】対比・因果など骨組みを圧縮","① 各文・段落の中心だけを短くする。","② 具体例・繰り返しを削る。","③ 主張と理由、対比、因果など文章の骨組みを残す。","④ 元の意味を変えず指定字数に収める。"],"retry":"五十字以内で要約しなさい。","explain":"主張と理由、対比、因果など文章の骨組みを残す。"},{"id":"p160","skill":"主語・主体","level":2,"stage":"single","passage":"彩は資料を読んで健に渡した。受け取ると、重要な部分に線を引いた。","q":"線を引いたのは誰ですか。","answer":"健","guide":["【この問題の焦点】省略された主語を動作の連続から補う","① 動作・発言を表す言葉に線を引く。","② 直前に出た人物を候補にする。","③ 「だれが＋その動作」の形で補って、文脈が続くか確かめる。","④ 主語だけを答える。"],"retry":"線を引いたのは誰ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「だれが＋その動作」の形で補って、文脈が続くか確かめる。"},{"id":"p161","skill":"主語・主体","level":3,"stage":"combined","passage":"先生に呼ばれた和也を見て、翔は箱を置いた。和也は「僕が運ぶよ」と言ったが、翔は「重いから二人で持とう」と返した。二人は箱の両端を持ち上げ、教室まで運んだ。","q":"箱を運ぶ場面で、①最初に箱を置いた人物、②運ぶと申し出た人物、③最後に箱を持ち上げた人物を、それぞれ答えなさい。","answer":"①翔　②和也　③翔と和也","guide":["発言の前後で人物の動作を順に整理する。","「僕が運ぶよ」の発言者を確認する。","最後の「二人」が誰を指すか文脈から補う。"],"retry":"本文中の根拠を二か所以上示して、設問にもう一度答えなさい。","explain":"本文の一か所だけで決めず、異なる箇所の情報を対応させる。「僕が運ぶよ」の発言者を確認する。／最後の「二人」が誰を指すか文脈から補う。"},{"id":"p162","skill":"指示語","level":2,"stage":"single","passage":"聞き手の知識を確かめ、詳しく説明する部分を決める。この作業で発表の重点が明確になる。","q":"「この作業」が指す内容を書きなさい。","answer":"聞き手の知識を確かめ、詳しく説明する部分を決めること。","guide":["【この問題の焦点】前文の内容全体を指す","① 指示語を丸で囲む。","② 直前の一語だけでなく、前の文・出来事まで候補にする。","③ 候補を指示語の位置に置き換えて意味が通るか確かめる。","④ 必要な範囲を過不足なく答える。"],"retry":"「この作業」が指す内容を書きなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"候補を指示語の位置に置き換えて意味が通るか確かめる。"},{"id":"p163","skill":"指示語","level":3,"stage":"combined","passage":"朝、駅前の通りでは通勤する人が多く、夕方は買い物袋を持つ人が増えた。店の営業時間は朝も夕方も同じだった。調査班はこの違いを営業時間だけでは説明できないと考えた。","q":"「この違い」が指す内容を、朝と夕方の二つの様子を対比して説明しなさい。","answer":"朝は通勤する人が多いのに対し、夕方は買い物袋を持つ人が増えるという、人の通り方の違い。","guide":["【この問題の焦点】本文の離れた情報を結びつける","設問で求められている要素を二つ以上に分けて確認しよう。","本文からそれぞれの根拠に線を引き、順序・対比・因果の関係を整理しよう。","根拠同士をつないで説明し、本文にない断定を加えていないか確かめよう。"],"retry":"本文中の根拠を二か所以上挙げ、それらの関係が分かるようにもう一度答えなさい。","explain":"本文の一か所だけではなく、複数の情報を対応づけることが必要です。解答例と本文の根拠を照合し、関係を説明できているか確認します。"},{"id":"p164","skill":"接続関係","level":2,"stage":"single","passage":"数字にすると変化を比べやすい。一方で、数字にならない様子もある。","q":"「一方で」はどのような関係を示しますか。","answer":"数字の利点と、数字では捉えられない面を対比する関係。","guide":["【この問題の焦点】条件・補足・対比を判断","① 接続語の前と後を短く区切る。","② 前後をそれぞれ一言で要約する。","③ 逆接・因果・追加・対比・条件など、関係を決める。","④ 接続語の名前だけでなく、前後がどうつながるか答える。"],"retry":"「一方で」はどのような関係を示しますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"逆接・因果・追加・対比・条件など、関係を決める。"},{"id":"p165","skill":"接続関係","level":3,"stage":"combined","passage":"一度で理解できなくてもよい。なぜなら、読み返すと初めは気づかなかった文同士の関係が見えることがあるからだ。したがって、分からない箇所には印を付け、後で読み直すことが大切だ。","q":"「なぜなら」と「したがって」が結ぶ内容をそれぞれ説明しなさい。","answer":"「なぜなら」は一度で理解できなくてもよい理由として、読み返しによる発見を示す。「したがって」はその理由を受け、印を付けて読み直すという行動上の結論を導く。","guide":["【この問題の焦点】本文の離れた情報を結びつける","設問で求められている要素を二つ以上に分けて確認しよう。","本文からそれぞれの根拠に線を引き、順序・対比・因果の関係を整理しよう。","根拠同士をつないで説明し、本文にない断定を加えていないか確かめよう。"],"retry":"本文中の根拠を二か所以上挙げ、それらの関係が分かるようにもう一度答えなさい。","explain":"本文の一か所だけではなく、複数の情報を対応づけることが必要です。解答例と本文の根拠を照合し、関係を説明できているか確認します。"},{"id":"p166","skill":"因果関係","level":2,"stage":"single","passage":"説明書を読まず組み立て、部品を逆向きに付けた。そのため途中で動かなくなり、最初から確認した。","q":"最初から確認することになった原因を説明しなさい。","answer":"説明書を読まず部品を逆向きに付け、途中で動かなくなったから。","guide":["【この問題の焦点】原因→途中→結果","① 結果に当たる部分を先に見つける。","② 「なぜ？」と前へ戻って直接の原因を探す。","③ 必要なら原因→途中の変化→結果の順に並べる。","④ 原因と結果が飛ばない一文にする。"],"retry":"最初から確認することになった原因を説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"必要なら原因→途中の変化→結果の順に並べる。"},{"id":"p167","skill":"因果関係","level":3,"stage":"combined","passage":"同じ種類の豆を二つの鉢に植えた。最初は片方を窓辺に置き、水も多く与えたところ、その鉢だけよく育った。しかし、光と水のどちらが影響したかは分からなかった。そこで次は水の量と土をそろえ、一方だけ窓辺に置いた。窓辺の鉢の方がよく育った。","q":"最初の実験では原因を一つに絞れなかった理由と、次の実験で光の影響を考えやすくなった理由を、条件の違いに着目して説明しなさい。","answer":"最初は光の当たり方と水の量が両方違ったため原因を特定できなかったが、次は水と土をそろえて置き場所だけを変えたため、育ち方の違いと光の関係を調べやすくなった。","guide":["最初と次の実験で、違っていた条件をそれぞれ列挙する。","最初の実験で、結果の原因となり得る条件はいくつあったか考える。","次の実験でそろえた条件と変えた条件を分ける。","「最初は～ため、次は～ため」と対比して答える。"],"retry":"本文をもう一度読み、根拠となる表現に線を引きなさい。次に、根拠を二つ以上使うか、複数の条件を比較して、設問に答え直しなさい。","explain":"【根拠】同じ種類の豆を二つの鉢に植えた。最初は片方を窓辺に置き、水も多く与えたところ、その鉢だけよく育った。しかし、光と水のどちらが影響したかは分からなかった。そこで次は水の量と土をそろえ、一方だけ窓辺に置いた。窓辺の鉢の方がよく育った。\n【解き方】最初と次の実験で、違っていた条件をそれぞれ列挙する。 → 最初の実験で、結果の原因となり得る条件はいくつあったか考える。 → 次の実験でそろえた条件と変えた条件を分ける。 → 「最初は～ため、次は～ため」と対比して答える。\n【模範解答】最初は光の当たり方と水の量が両方違ったため原因を特定できなかったが、次は水と土をそろえて置き場所だけを変えたため、育ち方の違いと光の関係を調べやすくなった。"},{"id":"p168","skill":"因果関係","level":3,"stage":"combined","passage":"発表資料に文字を詰め込みすぎたため、聞き手は画面を読むことに集中した。話し手が重要な説明をしても顔を上げる人は少なく、質問では説明済みの内容を尋ねる人が続いた。","q":"資料の作り方が聞き手の理解に影響した過程を、二つの出来事をつないで説明しなさい。","answer":"資料の文字が多く聞き手が読むことに集中したため、話し手の説明を十分に聞けず、説明済みの内容を質問する人が続いた。","guide":["【この問題の焦点】本文の離れた情報を結びつける","設問で求められている要素を二つ以上に分けて確認しよう。","本文からそれぞれの根拠に線を引き、順序・対比・因果の関係を整理しよう。","根拠同士をつないで説明し、本文にない断定を加えていないか確かめよう。"],"retry":"本文中の根拠を二か所以上挙げ、それらの関係が分かるようにもう一度答えなさい。","explain":"本文の一か所だけではなく、複数の情報を対応づけることが必要です。解答例と本文の根拠を照合し、関係を説明できているか確認します。"},{"id":"p169","skill":"事実・推測","level":2,"stage":"single","passage":"机には開いたノートと温かい飲み物が残っていた。教室には誰もいない。","q":"「持ち主はすぐ戻る」と断定できますか。","answer":"断定できない。物の状態は事実だが、持ち主の予定は書かれていない。","guide":["【この問題の焦点】事実と心情推測を分ける","① 本文にそのまま書かれた行動・発言・状態に線を引く。","② 気持ち・理由・予定など、本文にない言葉を分ける。","③ 「本文に直接あるか」で事実か推測か判定する。","④ 推測なら、根拠となる事実も示す。"],"retry":"「持ち主はすぐ戻る」と断定できますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「本文に直接あるか」で事実か推測か判定する。"},{"id":"p170","skill":"事実・推測","level":3,"stage":"combined","passage":"麻衣は結果を見て何も言わず、紙を折ってかばんに入れた。帰り道、友人に「結果はどうだった」と聞かれたが、「家で話す」と答えた。翌日、麻衣は先生に次の課題を尋ねた。","q":"本文から確実に言える行動を二つ挙げたうえで、麻衣の気持ちについて考えられることと、断定できないことを区別しなさい。","answer":"事実は結果の紙を折ってかばんに入れたことと、翌日先生に次の課題を尋ねたこと。次に向けて取り組もうとしている可能性はあるが、結果に満足したかどうかは断定できない。","guide":["【この問題の焦点】本文の離れた情報を結びつける","設問で求められている要素を二つ以上に分けて確認しよう。","本文からそれぞれの根拠に線を引き、順序・対比・因果の関係を整理しよう。","根拠同士をつないで説明し、本文にない断定を加えていないか確かめよう。"],"retry":"本文中の根拠を二か所以上挙げ、それらの関係が分かるようにもう一度答えなさい。","explain":"本文の一か所だけではなく、複数の情報を対応づけることが必要です。解答例と本文の根拠を照合し、関係を説明できているか確認します。"},{"id":"p171","skill":"事実・推測","level":3,"stage":"combined","passage":"商店街の菓子店の前に長い列ができていた。入口には「本日最終日」と書かれ、隣には「午後から限定商品を販売」とも掲示されていた。並んでいた人のうち一人は「昨日も買った」と話したが、ほかの人が並ぶ理由は書かれていない。","q":"列ができた原因を「閉店の最終日だから」と断定できるか。本文で確かめられる事実を二つ以上挙げ、ほかに考えられる可能性にも触れて説明しなさい。","answer":"断定できない。最終日の掲示と午後からの限定販売の掲示、列ができたことは事実だが、限定商品が目当ての人も考えられ、並んだ人々の理由は本文から確定できない。","guide":["本文に直接書かれた掲示と人々の様子を別々に抜き出す。","列の原因として考えられる説明を二つ挙げる。","どちらの原因を支持する発言・情報があるか確認する。","事実と推測を分け、断定できない理由を答える。"],"retry":"本文をもう一度読み、根拠となる表現に線を引きなさい。次に、根拠を二つ以上使うか、複数の条件を比較して、設問に答え直しなさい。","explain":"【根拠】商店街の菓子店の前に長い列ができていた。入口には「本日最終日」と書かれ、隣には「午後から限定商品を販売」とも掲示されていた。並んでいた人のうち一人は「昨日も買った」と話したが、ほかの人が並ぶ理由は書かれていない。\n【解き方】本文に直接書かれた掲示と人々の様子を別々に抜き出す。 → 列の原因として考えられる説明を二つ挙げる。 → どちらの原因を支持する発言・情報があるか確認する。 → 事実と推測を分け、断定できない理由を答える。\n【模範解答】断定できない。最終日の掲示と午後からの限定販売の掲示、列ができたことは事実だが、限定商品が目当ての人も考えられ、並んだ人々の理由は本文から確定できない。"},{"id":"p172","skill":"心情","level":2,"stage":"single","passage":"最後に抜かれた駿は唇をかんだ。ゴール後はすぐ自分のタイムを書き写した。","q":"駿の心情を行動を根拠に説明しなさい。","answer":"悔しさを感じながらも、結果を受け止め次につなげようとしている。","guide":["【この問題の焦点】状況と行動を組み合わせる","① 心情が問われる人物と場面を確認する。","② 行動・表情・発言・状況から根拠を二つまで拾う。","③ 根拠から言える範囲で心情語を選ぶ。","④ 「～ことから、～気持ち」の形で答える。"],"retry":"駿の心情を行動を根拠に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠から言える範囲で心情語を選ぶ。"},{"id":"p173","skill":"心情","level":3,"stage":"combined","passage":"引っ越し前日、茜は空の本棚を何度も開け、「こんなに広かったんだ」と笑った。母が「寂しい？」と尋ねると、茜は「少し。でも新しい部屋にも本棚を置きたい」と答えた。最後に、棚板に残った小さな傷を指でなぞった。","q":"茜の気持ちを、母への返事と最後の行動の両方を根拠にして説明しなさい。","answer":"新しい生活を楽しみにする気持ちがある一方、使い慣れた本棚との別れを寂しく、名残惜しく感じている。","guide":["母への返事に表れた二つの気持ちを確認する。","傷をなぞる行動が何を示すか考える。","期待と名残惜しさを両方含めて説明する。"],"retry":"本文中の根拠を二か所以上示して、設問にもう一度答えなさい。","explain":"本文の一か所だけで決めず、異なる箇所の情報を対応させる。傷をなぞる行動が何を示すか考える。／期待と名残惜しさを両方含めて説明する。"},{"id":"p174","skill":"心情変化","level":2,"stage":"single","passage":"古い時計を「新しい方が便利」と言った蓮は、父も子どものころ使ったと聞き、帰りには自分で時計を包んだ。","q":"蓮の気持ちはどう変化しましたか。","answer":"古く不便な物と見る気持ちから、家族の記憶がつながる大切な物と見る気持ちへ。","guide":["【この問題の焦点】きっかけを含めて整理","① 変化前の行動・発言を探す。","② 変化後の行動・発言を探す。","③ 間にある出来事や気づきを確認する。","④ 「～から、～へ変化した」の形にする。"],"retry":"蓮の気持ちはどう変化しましたか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"間にある出来事や気づきを確認する。"},{"id":"p175","skill":"心情変化","level":3,"stage":"combined","passage":"発表順が最後だと知った優奈は、肩を落として「待つのは苦手」とつぶやいた。前の班の発表を聞くうちに、説明の順番を工夫すると伝わりやすいことに気づき、自分の原稿の順序を直した。発表直前には「最後だから気づけたこともあるね」と友人に話した。","q":"優奈の気持ちは、発表順を知ったときから発表直前までにどう変化したか。途中の行動と言葉をそれぞれ根拠にして説明しなさい。","answer":"最初は最後まで待つことを負担に感じていたが、前の班から学んで原稿を直し、「最後だから気づけたこともある」と話すようになり、待ち時間を役立てられたと捉えるようになった。","guide":["最初の「肩を落とした」「待つのは苦手」から気持ちを読み取ろう。","前の班を聞いた後、原稿に何をしたか確認しよう。","最後の発言を根拠に、待ち時間の捉え方がどう変わったか説明しよう。"],"retry":"最後の発言を使わず、原稿を直した行動から推測できる変化と、まだ断定できないことを分けて書きなさい。","explain":"心情は行動だけで断定せず、初めと終わりの発言、途中の行動を結びつけて変化を説明する。"},{"id":"p176","skill":"きっかけ","level":2,"stage":"single","passage":"海斗は写真を年代順に並べていたが、祖母に「場所ごとに見ると変化が分かる」と言われ、並べ方を変えた。","q":"海斗が並べ方を変えたきっかけは何ですか。","answer":"祖母から場所ごとに見ると変化が分かると言われたこと。","guide":["【この問題の焦点】言葉と気づきを区別","① 考え・行動が変わった箇所を見つける。","② その直前へ戻る。","③ 変化を生んだ言葉・出来事・気づきを一つに絞る。","④ 必要なら「～に気づいたこと」まで含める。"],"retry":"海斗が並べ方を変えたきっかけは何ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"変化を生んだ言葉・出来事・気づきを一つに絞る。"},{"id":"p177","skill":"きっかけ","level":3,"stage":"combined","passage":"理沙は班の発表に昨年の調査結果を使うと決め、意見を変えるつもりはなかった。友人は新しい調査結果を示したが、理沙は初め「数字が違うだけだ」と取り合わなかった。ところが調査方法を比べると、昨年は一つの学年だけ、新しい調査では全学年を対象にしていた。理沙は「これなら学校全体の様子を考えられる」と言い、資料を差し替えた。","q":"理沙が資料を差し替えた決定的なきっかけを、最初の反応と調査対象の違いを踏まえて説明しなさい。","answer":"最初は新しい数字だけでは納得しなかったが、新しい調査が昨年の一学年だけの調査と異なり全学年を対象にしていると分かり、学校全体を説明するのに適していると気づいたこと。","guide":["理沙の最初の反応を確認する。","二つの調査の「新しさ」以外の違いを探す。","理沙がその違いをどう評価したか、発言に線を引く。","最初の判断→新しい気づき→行動の変化の順に答える。"],"retry":"本文をもう一度読み、根拠となる表現に線を引きなさい。次に、根拠を二つ以上使うか、複数の条件を比較して、設問に答え直しなさい。","explain":"【根拠】理沙は班の発表に昨年の調査結果を使うと決め、意見を変えるつもりはなかった。友人は新しい調査結果を示したが、理沙は初め「数字が違うだけだ」と取り合わなかった。ところが調査方法を比べると、昨年は一つの学年だけ、新しい調査では全学年を対象にしていた。理沙は「これなら学校全体の様子を考えられる」と言い、資料を差し替えた。\n【解き方】理沙の最初の反応を確認する。 → 二つの調査の「新しさ」以外の違いを探す。 → 理沙がその違いをどう評価したか、発言に線を引く。 → 最初の判断→新しい気づき→行動の変化の順に答える。\n【模範解答】最初は新しい数字だけでは納得しなかったが、新しい調査が昨年の一学年だけの調査と異なり全学年を対象にしていると分かり、学校全体を説明するのに適していると気づいたこと。"},{"id":"p178","skill":"人物像","level":2,"stage":"single","passage":"颯は試合に出ない日も仲間のボールを拾い、気づいた点をノートに書いて渡した。","q":"颯はどのような人物ですか。","answer":"自分が出場しなくても仲間のために行動する協力的な人物。","guide":["【この問題の焦点】発言と行動を合わせる","① 人物の具体的な行動・発言に線を引く。","② その行動を「どんな考え方・性質か」に言い換える。","③ 一場面だけから言い過ぎていないか確かめる。","④ 根拠＋人物像で答える。"],"retry":"颯はどのような人物ですか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一場面だけから言い過ぎていないか確かめる。"},{"id":"p179","skill":"人物像","level":3,"stage":"combined","passage":"玲は図書委員として本を紹介するとき、読んでいない本については内容を決めつけず、紹介文を確認した。後日、友人から貸出期間を尋ねられると、曖昧な記憶で答えず、規則表を開いて確かめた。一方、質問した友人を待たせたことには「調べるのに時間がかかってごめんね」と伝えた。","q":"玲の人物像を、二つの場面に共通する行動と、友人への接し方を根拠に説明しなさい。","answer":"本の紹介でも貸出期間でも曖昧なまま答えず資料を確認する慎重で正確さを大切にする人物であり、待たせた友人に謝るなど相手への配慮もできる人物。","guide":["本の紹介と貸出期間の場面で、玲がしなかったこと・したことを並べる。","二つの行動に共通する性質を一つの言葉にする。","友人への言葉から、別の性質も読み取る。","具体的な根拠を含め、言い過ぎず人物像をまとめる。"],"retry":"本文をもう一度読み、根拠となる表現に線を引きなさい。次に、根拠を二つ以上使うか、複数の条件を比較して、設問に答え直しなさい。","explain":"【根拠】玲は図書委員として本を紹介するとき、読んでいない本については内容を決めつけず、紹介文を確認した。後日、友人から貸出期間を尋ねられると、曖昧な記憶で答えず、規則表を開いて確かめた。一方、質問した友人を待たせたことには「調べるのに時間がかかってごめんね」と伝えた。\n【解き方】本の紹介と貸出期間の場面で、玲がしなかったこと・したことを並べる。 → 二つの行動に共通する性質を一つの言葉にする。 → 友人への言葉から、別の性質も読み取る。 → 具体的な根拠を含め、言い過ぎず人物像をまとめる。\n【模範解答】本の紹介でも貸出期間でも曖昧なまま答えず資料を確認する慎重で正確さを大切にする人物であり、待たせた友人に謝るなど相手への配慮もできる人物。"},{"id":"p180","skill":"会話文","level":2,"stage":"single","passage":"「みんな同じ意見だから決まり」と言う拓に、凛は「まだ話していない人がいるよ」と言った。","q":"凛の発言の役割を説明しなさい。","answer":"発言していない人の意見も確認してから決める必要に気づかせる役割。","guide":["【この問題の焦点】相手への働きを読む","① 発言した人と相手を確認する。","② 発言そのものの意味を短くする。","③ 発言の後、相手の行動・考えがどう変わったかを見る。","④ 「この言葉が相手に何をさせたか」で答える。"],"retry":"凛の発言の役割を説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"発言の後、相手の行動・考えがどう変わったかを見る。"},{"id":"p181","skill":"会話文","level":3,"stage":"combined","passage":"弟は「次は間違えないようにする」と言い、前のテストを閉じた。兄は「どこで間違えたか覚えている？」と尋ねた。弟が「計算の最後」と答えると、兄は「途中の式も見直してみよう」と促した。弟は式を追い、最初の符号の誤りを見つけた。","q":"兄の二つの働きかけによって、弟は誤りの捉え方をどう変えたか。最初の答えと最後に見つけたことを対比して説明しなさい。","answer":"誤りを計算の最後にあると漠然と考えていたが、途中の式をたどることで、最初の符号の誤りが原因だと具体的に捉え直した。","guide":["弟が最初に考えた誤りの場所を確認する。","兄がどこを見直すよう促したか探す。","最初の理解と最後の発見を対比する。"],"retry":"本文中の根拠を二か所以上示して、設問にもう一度答えなさい。","explain":"本文の一か所だけで決めず、異なる箇所の情報を対応させる。兄がどこを見直すよう促したか探す。／最初の理解と最後の発見を対比する。"},{"id":"p182","skill":"具体と抽象","level":2,"stage":"single","passage":"図書館の分類、店の売り場、写真のアルバム。これらは数の多いものを探しやすくする工夫である。","q":"三つの例の共通点をまとめなさい。","answer":"多くのものを一定の基準で分け、必要なものを探しやすくする工夫。","guide":["【この問題の焦点】例と一般論を対応","① 具体例を一つずつ短い言葉にする。","② 複数の例に共通する部分を探す。","③ 人名・物名など細部を外して一段上の言葉にする。","④ 本文の抽象的な文と対応するか確かめる。"],"retry":"三つの例の共通点をまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"人名・物名など細部を外して一段上の言葉にする。"},{"id":"p183","skill":"具体と抽象","level":3,"stage":"combined","passage":"文章を覚えるために音読する人がいる。内容の関係を整理するために図にする人もいる。また、理解を確かめるために誰かに説明する人もいる。学び方は一つではなく、目的に応じて選べる。","q":"三つの具体例が示す共通点をまとめ、最後の一文がどのように一般化しているか説明しなさい。","answer":"音読・図解・説明はいずれも学習の目的に合わせて方法を工夫する例であり、最後の文は目的に応じて学び方を選べるという一般的な考えにまとめている。","guide":["【この問題の焦点】本文の離れた情報を結びつける","設問で求められている要素を二つ以上に分けて確認しよう。","本文からそれぞれの根拠に線を引き、順序・対比・因果の関係を整理しよう。","根拠同士をつないで説明し、本文にない断定を加えていないか確かめよう。"],"retry":"本文中の根拠を二か所以上挙げ、それらの関係が分かるようにもう一度答えなさい。","explain":"本文の一か所だけではなく、複数の情報を対応づけることが必要です。解答例と本文の根拠を照合し、関係を説明できているか確認します。"},{"id":"p184","skill":"人物関係","level":2,"stage":"single","passage":"母は以前、忘れ物を学校へ届けた。今は「必要な物は？」と尋ね、悠が自分で確認するのを待つ。","q":"母と悠の関係はどう変化しましたか。","answer":"母が不足を補う関係から、悠が自分で確認できるよう見守る関係へ。","guide":["【この問題の焦点】前後の関係変化を読む","① 二人それぞれの最初の行動を確認する。","② 後半の二人の行動も確認する。","③ 「指示する／従う」など関係を表す言葉に置き換える。","④ 「～関係から、～関係へ」でまとめる。"],"retry":"母と悠の関係はどう変化しましたか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"「指示する／従う」など関係を表す言葉に置き換える。"},{"id":"p185","skill":"人物関係","level":3,"stage":"combined","passage":"一年生の杏は先輩の動きをまねることから練習を始めた。二年生では後輩に同じ方法を教えたが、うまくいかない後輩もいた。三年生になると「私と同じでなくていい」と伝え、後輩自身に練習方法を考えさせた。","q":"杏の後輩への関わり方は二年生から三年生でどう変わったか。一年生の経験とも関連づけて説明しなさい。","answer":"一年生のとき先輩をまねて学んだ杏は、二年生では自分の方法を後輩に教えていたが、三年生では後輩に合う方法を自分で考えさせる関わり方に変わった。","guide":["【この問題の焦点】本文の離れた情報を結びつける","設問で求められている要素を二つ以上に分けて確認しよう。","本文からそれぞれの根拠に線を引き、順序・対比・因果の関係を整理しよう。","根拠同士をつないで説明し、本文にない断定を加えていないか確かめよう。"],"retry":"本文中の根拠を二か所以上挙げ、それらの関係が分かるようにもう一度答えなさい。","explain":"本文の一か所だけではなく、複数の情報を対応づけることが必要です。解答例と本文の根拠を照合し、関係を説明できているか確認します。"},{"id":"p186","skill":"表現効果","level":2,"stage":"single","passage":"閉会後の体育館には、さっきまでの拍手が嘘のように、椅子を重ねる音だけが響いた。","q":"この対比にはどのような効果がありますか。","answer":"行事中のにぎわいと終了後の静けさを対比し、終わった実感や余韻を強める。","guide":["【この問題の焦点】対比・反復などの効果","① 特徴的な物・音・動作・対比に線を引く。","② その前後の人物の心情や場面を確認する。","③ その表現がなくても伝わる事実と、表現によって強まる印象を分ける。","④ 「～を印象づける／表す」と答える。"],"retry":"この対比にはどのような効果がありますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"その表現がなくても伝わる事実と、表現によって強まる印象を分ける。"},{"id":"p187","skill":"表現効果","level":3,"stage":"combined","passage":"健太は先生に出した相談の返事を待っていた。スマートフォンの画面を何度も確かめるが、通知は来ない。窓の外では、交差点の信号が赤から青、青から赤へ二度変わった。それでも健太は席を立たなかった。","q":"信号が二度変わる描写は、時間の経過と健太の心情をどのように印象づけているか。","answer":"返事が来ないまま長い時間が過ぎていることを示し、何度も通知を確かめて待ち続ける健太の落ち着かなさを印象づける。","guide":["信号が変わる回数から、どのような時間の経過が感じられるか考えよう。","健太が繰り返している行動を探そう。","時間の長さと心情への効果を一文につなげよう。"],"retry":"信号の描写を削ると、待ち時間についてどのような印象が弱まるか説明しなさい。","explain":"信号の変化だけで心理を断定せず、「画面を何度も確かめる」という行動と合わせて落ち着かなさを読み取ります。"},{"id":"p188","skill":"文章全体","level":2,"stage":"single","passage":"要約は文章を短くするだけではない。重要でない部分を削っても、主張と理由の関係が残らなければ内容は変わる。まず文章の骨組みをつかむ必要がある。","q":"文章全体の主張をまとめなさい。本文の根拠と設問条件を確認して答えなさい。","answer":"要約では単に短くするのではなく、主張と理由の関係という文章の骨組みを保つことが重要である。","guide":["【この問題の焦点】具体例と主張を分ける","① 各文・段落を一言ずつにする。","② 具体例と筆者の考えを分ける。","③ 繰り返される考えと最後の結論を結ぶ。","④ 具体例を削り、文章全体を包む一文にする。"],"retry":"文章全体の主張をまとめなさい。","explain":"繰り返される考えと最後の結論を結ぶ。"},{"id":"p189","skill":"文章全体","level":3,"stage":"combined","passage":"旅行者向けの地図には駅や観光地が詳しく載るが、山道の危険な場所は省かれることがある。登山者向けの地図では反対に、標高や登山道が重視され、店の情報は少ない。同じ地域を描いていても、載せる情報は同じではない。地図は現実をそのまま小さくしたものではなく、使う目的に合わせて情報を選び、整理したものなのである。","q":"筆者が旅行者向けと登山者向けの地図を対比した目的を説明し、その具体例から導かれる文章全体の主張をまとめなさい。","answer":"同じ地域でも地図の用途によって重視する情報が異なることを示し、地図は現実の単なる縮小ではなく、目的に合わせて情報を選択・整理したものだと伝えるため。","guide":["二つの地図に多く載る情報をそれぞれ整理する。","同じ地域なのに情報が違う理由を考える。","最後の文で筆者が具体例をどう一般化しているか探す。","具体例の役割と筆者の主張を結んで答える。"],"retry":"本文をもう一度読み、根拠となる表現に線を引きなさい。次に、根拠を二つ以上使うか、複数の条件を比較して、設問に答え直しなさい。","explain":"【根拠】旅行者向けの地図には駅や観光地が詳しく載るが、山道の危険な場所は省かれることがある。登山者向けの地図では反対に、標高や登山道が重視され、店の情報は少ない。同じ地域を描いていても、載せる情報は同じではない。地図は現実をそのまま小さくしたものではなく、使う目的に合わせて情報を選び、整理したものなのである。\n【解き方】二つの地図に多く載る情報をそれぞれ整理する。 → 同じ地域なのに情報が違う理由を考える。 → 最後の文で筆者が具体例をどう一般化しているか探す。 → 具体例の役割と筆者の主張を結んで答える。\n【模範解答】同じ地域でも地図の用途によって重視する情報が異なることを示し、地図は現実の単なる縮小ではなく、目的に合わせて情報を選択・整理したものだと伝えるため。"},{"id":"p190","skill":"設問分析","level":2,"stage":"single","passage":"主人公の心情が変化したきっかけを、変化後の行動にも触れて七十字以内で説明しなさい。","q":"答案に必要な要素を整理しなさい。","answer":"心情変化のきっかけ、変化後の行動、七十字以内という条件。","guide":["【この問題の焦点】条件・範囲・字数を分解","① 何について答える問題か丸で囲む。","② 「理由・変化・効果」など答え方を示す語を確認する。","③ 範囲・字数・抜き出しなどの条件を拾う。","④ 必要な答案部品を先に箇条書きする。"],"retry":"答案に必要な要素を整理しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"範囲・字数・抜き出しなどの条件を拾う。"},{"id":"p191","skill":"設問分析","level":3,"stage":"combined","passage":"第二段落と第四段落に共通する考えを、それぞれの具体例を用いずに説明しなさい。","q":"示された設問について、①参照する段落、②書くべき内容、③避けるべき書き方をそれぞれ答えなさい。","answer":"①第二段落と第四段落　②両段落に共通する考え　③それぞれの具体例をそのまま用いる書き方","guide":["段落を表す数字に印をつけよう。","「共通する考え」が何を要求しているか確認しよう。","「用いずに」という禁止条件を抜き出そう。"],"retry":"具体例だけを並べた答案では、設問のどの条件を満たさないか答えなさい。","explain":"二段落の共通点を抽象化することが求められ、具体例の列挙では条件を満たせません。"},{"id":"p192","skill":"選択肢照合","level":2,"stage":"single","passage":"予想どおりの結果だけに注目すると違う変化を見落とす。予想は見る方向を決める助けだが、結果を決めつけるものではない。","q":"最も合うものを選びなさい。\nア 予想は立てない方がよい。\nイ 違う結果は記録しない。\nウ 予想を手がかりにしつつ異なる結果にも注意する。\nエ 結果は必ず予想と一致する。","answer":"ウ","guide":["【この問題の焦点】一部一致の誤答を除く","① 選択肢を一つずつ短く区切る。","② 本文の対応箇所を探す。","③ 一部だけ合う選択肢や「必ず・すべて」など強すぎる表現を確認する。","④ 全要素が本文と一致するものを選ぶ。"],"retry":"最も合うものを選びなさい。\nア 予想は立てない方がよい。\nイ 違う結果は記録しない。\nウ 予想を手がかりにしつつ異なる結果にも注意する。\nエ 結果は必ず予想と一致する。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一部だけ合う選択肢や「必ず・すべて」など強すぎる表現を確認する。"},{"id":"p193","skill":"選択肢照合","level":3,"stage":"combined","passage":"学級会では全員が校庭の使用時間を延ばす案に賛成した。しかし、運動部の生徒は練習時間を確保したいからで、図書委員の生徒は昼休みの混雑を減らしたいからだった。翌月、校庭を使える時間帯が朝だけに変更されると、運動部は賛成を続けたが、図書委員は混雑が減らないとして反対した。","q":"次のうち本文に最も合うものを選び、そう判断できる二つの時点の根拠を書きなさい。\nア　同じ案に賛成する人は、その理由も同じである。\nイ　最初の賛否が同じでも、理由の違いによって条件変更後の判断が分かれることがある。\nウ　一度賛成した人は、条件が変わっても反対しない。\nエ　理由の違いは、条件が変わった後の判断には影響しない。","answer":"イ。最初は運動部も図書委員も賛成したが理由が異なり、朝だけの使用に変わると運動部は賛成、図書委員は反対に分かれたから。","guide":["最初に両者が同じ判断をしたことを確認しよう。","それぞれが賛成した理由を別々に書こう。","条件変更後の賛否を比較し、選択肢の一般化が本文に合うか確かめよう。"],"retry":"条件が変わる前後で、図書委員の判断が変わった理由を説明しなさい。","explain":"最初の結論、理由、条件変更後の結論の三点を対応させる。結論だけでなく理由まで比較する技能を問う。"},{"id":"p194","skill":"抜き出し","level":2,"stage":"single","passage":"情報を集める前に、何を知りたいのかを決めておくとよい。目的がはっきりすれば、必要な資料と不要な資料を区別しやすい。","q":"最初にすべきことを本文から抜き出しなさい。","answer":"何を知りたいのかを決めておく","guide":["【この問題の焦点】範囲・字数条件を満たす","① 設問が求める意味を自分の言葉で短くする。","② 指定された段落・範囲から同じ意味の部分を探す。","③ 字数・個数・文末などの条件を確認する。","④ 本文を変えず、指定どおり抜き出す。"],"retry":"最初にすべきことを本文から抜き出しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"字数・個数・文末などの条件を確認する。"},{"id":"p195","skill":"抜き出し","level":3,"stage":"combined","passage":"相手の意見を理解するには、結論だけでなく、その結論に至った理由をたどる必要がある。さらに、自分と異なる前提に立っていないかを確かめると、意見の違いがどこから生まれたか分かる。","q":"相手の意見を理解するために必要な二つの行動を表す部分を、それぞれ本文から抜き出しなさい。","answer":"その結論に至った理由をたどる／自分と異なる前提に立っていないかを確かめる","guide":["「結論だけでなく」の後にある行動を探す。","「さらに」の後に付け加えられた行動を探す。","二つを混ぜずに本文の表現どおり抜き出す。"],"retry":"本文中の根拠を二か所以上示して、設問にもう一度答えなさい。","explain":"本文の一か所だけで決めず、異なる箇所の情報を対応させる。「さらに」の後に付け加えられた行動を探す。／二つを混ぜずに本文の表現どおり抜き出す。"},{"id":"p196","skill":"抜き出し","level":3,"stage":"combined","passage":"説明を分かりやすくするには、情報を多く集めるだけでは十分ではない。詳しい人に説明するときは基本事項を省けるが、初めて聞く人には前提から伝える必要がある。だからこそ、説明する相手が知っていることを考え、必要な情報を選ぶことが重要だ。","q":"説明相手によって伝える内容を変えるために、まず確認すべきことを表す部分を本文から十五字以内で抜き出しなさい。","answer":"説明する相手が知っていること","guide":["「まず確認すべきこと」と「その後にすること」を分ける。","本文の「だからこそ」以降を見て、情報を選ぶ前提となる部分を探す。","抜き出す箇所の始まりと終わりを決める。","本文と一字ずつ照合し、十五字以内か数える。"],"retry":"本文をもう一度読み、根拠となる表現に線を引きなさい。次に、根拠を二つ以上使うか、複数の条件を比較して、設問に答え直しなさい。","explain":"【根拠】説明を分かりやすくするには、情報を多く集めるだけでは十分ではない。詳しい人に説明するときは基本事項を省けるが、初めて聞く人には前提から伝える必要がある。だからこそ、説明する相手が知っていることを考え、必要な情報を選ぶことが重要だ。\n【解き方】「まず確認すべきこと」と「その後にすること」を分ける。 → 本文の「だからこそ」以降を見て、情報を選ぶ前提となる部分を探す。 → 抜き出す箇所の始まりと終わりを決める。 → 本文と一字ずつ照合し、十五字以内か数える。\n【模範解答】説明する相手が知っていること"},{"id":"p197","skill":"記述","level":2,"stage":"single","passage":"アンケートで図書館利用者は増えたが、回答者数も前年より多かった。担当者は人数だけでなく割合でも比べた。","q":"割合でも比べる理由を六十字以内で説明しなさい。","answer":"回答者数が年によって違い、人数だけでは利用状況の増減を公平に比較できないから。","guide":["【この問題の焦点】理由・変化など指定関係で書く","① 設問が求めるものを「理由・変化・効果」などに分類する。","② 本文から根拠となる部分を拾う。","③ 根拠をそのまま写さず、問いに答える関係に組み替える。","④ 字数内で、主語や因果が分かる文にする。"],"retry":"割合でも比べる理由を六十字以内で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠をそのまま写さず、問いに答える関係に組み替える。"},{"id":"p198","skill":"記述","level":3,"stage":"combined","passage":"昔の写真には人が多く写っていた。健は「昔の方がにぎわっていた」と書こうとしたが、撮影日が祭りの日だと知り直した。","q":"健が表現を直した理由を説明しなさい。","answer":"特別な祭りの日の写真だけでは、普段も昔の方がにぎわっていたとは判断できないから。","guide":["【この問題の焦点】複数根拠を組み合わせる","① 設問が求めるものを「理由・変化・効果」などに分類する。","② 本文から根拠となる部分を拾う。","③ 根拠をそのまま写さず、問いに答える関係に組み替える。","④ 字数内で、主語や因果が分かる文にする。"],"retry":"健が表現を直した理由を説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"根拠をそのまま写さず、問いに答える関係に組み替える。"},{"id":"p199","skill":"要約","level":2,"stage":"single","passage":"同じ出来事でも注目する場所が違えば異なる記録になる。複数の記録を比べるときは、内容だけでなく何に注目して作られたかも考える必要がある。","q":"六十字以内で要約しなさい。本文の根拠と設問条件を確認して答えなさい。","answer":"記録は注目点で内容が変わるため、比べる際は何に注目して作られたかも考える必要がある。","guide":["【この問題の焦点】主張と理由を残す","① 各文・段落の中心だけを短くする。","② 具体例・繰り返しを削る。","③ 主張と理由、対比、因果など文章の骨組みを残す。","④ 元の意味を変えず指定字数に収める。"],"retry":"六十字以内で要約しなさい。","explain":"主張と理由、対比、因果など文章の骨組みを残す。"},{"id":"p200","skill":"要約","level":3,"stage":"combined","passage":"調べ物をするとき、全体像をつかむために速く読むことは役立つ。一方、実験の手順を確認するときには、一文を読み飛ばすだけで結果が変わることがある。また、筆者の主張を確かめるときは、結論だけでなく理由に戻って読む必要がある。読む速さは一つに決めるものではない。","q":"速く読む場合と立ち止まって読む場合の具体例を一つずつ示し、筆者の主張を六十字以内で要約しなさい。","answer":"全体像をつかむときは速く読み、実験の手順を確かめるときは丁寧に読むなど、目的に応じて読み方を変えるべきだ。","guide":["速く読むことが役立つ目的を探そう。","丁寧に読む必要がある場面を一つ選ぼう。","二つの例を対比させ、最後に筆者の主張を六十字以内でまとめよう。"],"retry":"「筆者の主張」だけを一文で書いた後、本文の例を二つ加えて六十字以内に整えなさい。","explain":"具体例を一つずつ含めるという条件を満たしたうえで、目的に応じた読み方の切り替えを要約する。"},{"id":"p201","skill":"主語・主体","level":4,"stage":"exam","passage":"文化祭の記録をまとめることになり、由衣は写真を選び、陸は説明文を書くことになった。翌日、由衣が選んだ写真を机に並べると、陸は一枚ずつ撮影場所を尋ねた。答えを聞き終えると、前年の記録も取り出し、違いを書き込み始めた。最後に「これなら変化が伝わる」と言って、二枚の写真を入れ替えた。","q":"「二枚の写真を入れ替えた」のは誰ですか。途中の動作も根拠に答えなさい。","answer":"陸。撮影場所を尋ね、前年の記録との違いを書き込んでいた人物が、その流れで写真を入れ替えているから。","guide":["【この問題の焦点】主語の省略が続く箇所で動作の主体を追跡する。","① 動作を表す語を順に丸で囲み、各動作の直前・直後の人物名を探す。","② 主語が省略された箇所は、会話の話者と動作の連続性を照合する。","③ 設問で指定された動作ごとに主体を対応させ、混同していないか確かめる。","④ 動作ごとの主体と、その判断の根拠を確かめる。"],"retry":"「二枚の写真を入れ替えた」のは誰ですか。途中の動作も根拠に答えなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"段落内で人物が切り替わっても、動作の連続から主体を追跡する。"},{"id":"p202","skill":"指示語","level":4,"stage":"exam","passage":"町の公園では、ベンチを増やしただけでは利用者が増えなかった。そこで住民に聞き取りをすると、夏は日陰が少なく長く過ごしにくいという声が多かった。木の近くへベンチを移し、簡単な日よけも設けると、昼間の利用者が増えた。この変化は、設備の数より、使う人がどのように過ごすかを考える必要を示している。","q":"「この変化」が指す内容を、前後の内容が分かるように説明しなさい。","answer":"ベンチを増やすだけでは利用者が増えなかったが、日陰を考えてベンチを移し日よけを設けると昼間の利用者が増えたこと。","guide":["【この問題の焦点】「この変化」が指す前後の状態をまとめる。","① 設問にある指示語を本文で見つけ、その前後の文を区切る。","② 候補となる内容を複数拾い、指示語がまとめている範囲を確かめる。","③ 指示語を具体的な表現に置き換え、文意が通るか検証する。","④ 指示内容に含める出来事と、前後の変化が欠けていないか確かめる。"],"retry":"「この変化」が指す内容を、前後の内容が分かるように説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数文にまたがる出来事をまとめて指示内容に置き換える。"},{"id":"p203","skill":"接続関係","level":4,"stage":"exam","passage":"記録を残せば、あとで自分の変化を確かめられる。しかし、記録しただけで学習が改善するわけではない。どこで間違え、なぜ間違えたかを見直して初めて、次に注意する点が見えてくる。つまり、記録は保存するためだけでなく、次の行動を決める材料として使うことに意味がある。","q":"「しかし」と「つまり」が、文章の展開でそれぞれどのような役割をしていますか。","answer":"「しかし」は記録するだけでは不十分だと前の内容を限定し、「つまり」は見直した内容をまとめ、記録を次の行動に生かすという筆者の考えを示している。","guide":["【この問題の焦点】逆接と要約の接続語の役割を区別する。","① 接続語の前後をそれぞれ短い文に言い換える。","② 前後が逆接・理由・補足・言い換えのどの関係か、内容から判断する。","③ 接続語の働きと前後の具体的内容を分けて説明する。","④ 各接続語の働きと、文章全体の論理の流れを対応させる。"],"retry":"「しかし」と「つまり」が、文章の展開でそれぞれどのような役割をしていますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の接続語が文章全体の論理展開で果たす役割を捉える。"},{"id":"p204","skill":"因果関係","level":4,"stage":"exam","passage":"班では発表時間が足りないことを問題にしていた。最初は話す速さを上げたが、聞き手から「内容を追えない」と言われた。そこで資料を見直すと、同じ内容を文章と図の両方で説明している部分が多いと分かった。重複を削ると、話す速さを変えなくても時間内に収まり、質問の時間まで取れるようになった。","q":"質問の時間まで取れるようになった理由を、途中の過程を含めて説明しなさい。","answer":"資料を見直して文章と図で重複していた説明を見つけ、それを削ったことで、話す速さを上げずに発表を短くできたから。","guide":["【この問題の焦点】原因と結果の間の改善過程を説明する。","① 結果を表す部分を先に探し、そこに至る出来事をさかのぼる。","② 直接の原因と、その間にある行動・工夫・条件を区別する。","③ 原因→途中の変化→結果の順に矢印で結び、飛躍がないか確かめる。","④ 原因・途中の過程・結果を区別し、飛躍がないか確かめる。"],"retry":"質問の時間まで取れるようになった理由を、途中の過程を含めて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"離れた原因と結果の間にある過程を補って因果を説明する。"},{"id":"p205","skill":"事実・推測","level":4,"stage":"exam","passage":"雨が上がったあと、校庭には水たまりが残っていた。健太は窓から外を見て、体育着の袋を机の横に置いたまま図書室へ向かった。五時間目は体育の予定だったが、変更の放送はまだ流れていない。","q":"「五時間目の体育は中止になった」と言えますか。本文の事実を二つ以上使って説明しなさい。","answer":"言えない。雨上がりで校庭に水たまりがあり、健太が体育着を置いて図書室へ向かったことは事実だが、体育変更の放送はなく、中止とは確定していない。","guide":["【この問題の焦点】事実と未確定の判断を分ける。","① 本文で実際に起きたこと・観察されたことに線を引く。","② 人物の予想や判断を別に囲み、事実と混ぜない。","③ 設問の断定が本文の情報だけで可能か、不明な点を明示する。","④ 直接書かれた事実と推測を分け、断定しすぎていないか確かめる。"],"retry":"「五時間目の体育は中止になった」と言えますか。本文の事実を二つ以上使って説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の事実を根拠にしつつ、本文から断定できる範囲を越えない。"},{"id":"p206","skill":"心情","level":4,"stage":"exam","passage":"発表を終えた美月は、席に戻ると原稿の端を折り始めた。友人に「よかったよ」と言われても「途中で言葉が出なかった」と答えた。しかし先生が「質問への答え方は自分の言葉だった」と話すと、折っていた手を止め、原稿の余白にその言葉を書き込んだ。","q":"最後の美月の心情を、前半との違いと二つの行動を根拠に説明しなさい。","answer":"初めは「言葉が出なかった」と失敗を気にして原稿の端を折っていたが、先生の言葉を聞いて手を止め、その言葉を余白に書き込んだことから、できた点にも目を向け、前向きに振り返ろうとしている。","guide":["【この問題の焦点】二つの行動の変化から、最後の心情を説明する。","① 気持ちが問われる場面の発言・行動・描写を拾う。","② 同じ人物の前後の行動を比べ、気持ちを直接表す語がなくても推測する。","③ 感情の名称だけで終えず、そのように判断した本文の根拠を添える。","④ 気持ちの説明が行動・発言などの根拠と結びついているか確かめる。"],"retry":"最後の美月の心情を、前半との違いと二つの行動を根拠に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"前後の異なる行動を統合して、直接書かれない心情を説明する。"},{"id":"p207","skill":"心情変化","level":4,"stage":"exam","passage":"直樹は地域清掃の係を「決められたからやるだけ」と考えていた。作業中、通りかかった人に「毎朝ここを通るけれど、今日は気持ちがいいね」と声をかけられた。その後、直樹は予定の場所を終えても、風でごみが集まっていた角まで掃いた。翌週の係決めでは、自分から同じ場所を選んだ。","q":"直樹の心情の変化を、きっかけと二つの行動を使って説明しなさい。","answer":"初めは清掃を決められたから行う義務と考えていたが、通行人から清掃後の様子を肯定的に評価されたことをきっかけに意味を感じ、予定外の角まで掃き、翌週も自分から同じ場所を選ぶほど、進んで取り組む気持ちへ変化した。","guide":["【この問題の焦点】きっかけと二つの行動を結んで心情変化を説明する。","① 変化前の言動と変化後の言動をそれぞれ抜き出す。","② 間に起きた出来事・相手の言葉を変化のきっかけとして確認する。","③ 初めの気持ち→きっかけ→変化後の気持ちの順でまとめる。","④ 変化前・きっかけ・変化後の三つがそろっているか確かめる。"],"retry":"直樹の心情の変化を、きっかけと二つの行動を使って説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数場面の行動ときっかけを統合して変化を説明する。"},{"id":"p208","skill":"きっかけ","level":4,"stage":"exam","passage":"奈央は説明文を短くするため、例を次々に削っていた。友人に読んでもらうと「言いたいことは分かるけれど、なぜそう言えるのか分からない」と言われた。奈央は削除前の文章を見直し、主張を支える例だけを一つ戻した。すると友人は「これなら理由が分かる」と言った。","q":"奈央が例を一つ戻す判断をした直接のきっかけと、そこで気づいたことを答えなさい。","answer":"友人から理由が分からないと言われたことが直接のきっかけで、短くするために例をすべて削ると主張の根拠まで失われると気づいたこと。","guide":["【この問題の焦点】出来事そのものと、そこから生じた気づきを分けて捉える。","① 人物の考え・行動が変わる前と後を比べる。","② その間に起きた出来事と、人物がそこから気づいたことを分ける。","③ 単なる出来事の紹介ではなく、変化とのつながりを説明する。","④ 直接のきっかけと、その後の判断や行動を混同していないか確かめる。"],"retry":"奈央が例を一つ戻す判断をした直接のきっかけと、そこで気づいたことを答えなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"出来事そのものと、そこから生じた気づきを分けて捉える。"},{"id":"p209","skill":"人物像","level":4,"stage":"exam","passage":"係長の拓海は、作業が遅れている班を見てもすぐ手を出さなかった。「どこで止まった？」と尋ね、班員が原因を説明すると、「では次に何を確かめる？」ともう一度聞いた。班員が方法を決めて動き始めると、拓海は別の班へ向かった。終了後、自分の記録には「答えを言わなくても進めた」と書いた。","q":"拓海の人物像を、複数の行動を根拠に説明しなさい。","answer":"作業が遅れている班にもすぐに手を出さず、原因や次に確かめることを問いかけ、班員が自分で動き始めると別の班へ向かったことから、答えを与えず相手の自立を支えようとする人物。","guide":["【この問題の焦点】異なる場面の行動に共通する人物の姿勢を捉える。","① 同じ人物の異なる場面での言動を二つ以上拾う。","② 一回限りの行動と、複数場面に共通する姿勢を区別する。","③ 人物の特徴を抽象語で示し、具体的な行動を根拠として添える。","④ 性格を表す言葉だけでなく、複数の行動を根拠に示したか確かめる。"],"retry":"拓海の人物像を、複数の行動を根拠に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の行動に共通する考え方から、一面的でない人物像を作る。"},{"id":"p210","skill":"会話文","level":4,"stage":"exam","passage":"班でポスターを作るとき、翔が「文字をもっと増やそう」と言った。優希は「このポスターを三秒だけ見たら、何が一番残る？」と尋ねた。翔は少し離れてポスターを見たあと、「題名より説明の方が目立ってる」と言い、説明文を短くした。","q":"優希の発言は、翔の考えにどのような働きをしましたか。発言後の行動も含めて説明しなさい。","answer":"優希の問いかけは、文字数を増やすことだけを考えていた翔に、短時間で何が伝わるかを考えさせた。その結果、翔は少し離れてポスターを見直し、説明文を短くした。","guide":["【この問題の焦点】問いかけが相手の見方と行動を変える過程を追う。","① 発言の話者と相手を整理し、発言順に番号を付ける。","② 問いかけ・提案・反論が何に対するものか前の発言と結ぶ。","③ 会話後の行動や考えの変化を確認し、発言の役割を説明する。","④ 発言の意図と、発言後の行動・反応を区別して説明したか確かめる。"],"retry":"優希の発言は、翔の考えにどのような働きをしましたか。発言後の行動も含めて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"発言の意図と、その発言が相手の判断を変えた過程を結びつける。"},{"id":"p211","skill":"具体と抽象","level":4,"stage":"exam","passage":"駅では出口ごとに色を変えた案内があり、病院では診療科ごとに床の線が分けられている。図書館では本棚に分類番号が大きく表示されている。方法は異なるが、どれも利用者が大量の情報を一度に読まなくても、目的の場所へ進めるようにしている。","q":"三つの具体例に共通する考えを、一段抽象的な言葉でまとめなさい。","answer":"情報を分類し、色や線、番号などの目印を使うことで、利用者が必要な情報や場所を見つけやすくする工夫。","guide":["【この問題の焦点】離れた複数の具体例を共通する抽象概念へまとめる。","① 本文中の具体的な例や行動を複数探す。","② 各例に共通する性質を、例にない言葉で短くまとめる。","③ まとめた抽象的な表現がすべての例に当てはまるか確認する。","④ 具体例の列挙で終わらず、共通する上位の考えを示したか確かめる。"],"retry":"三つの具体例に共通する考えを、一段抽象的な言葉でまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"離れた複数の具体例を共通する抽象概念へまとめる。"},{"id":"p212","skill":"人物関係","level":4,"stage":"exam","passage":"一年生のころ、陸は分からない問題があると先輩の航に解き方を尋ね、航は手順を最初から説明していた。二年生になると、航は「どこまでは分かる？」と尋ねるようになり、陸も自分の考えを話してから質問するようになった。三年生になった陸は、後輩に同じ問いかけをしている。","q":"陸と航の関係がどのように変化し、その経験が陸にどう受け継がれたか説明しなさい。","answer":"航が答えを教え陸が受け取る関係から、陸自身が考えるのを航が支える関係へ変わり、その学び方を陸も後輩への支援に用いるようになった。","guide":["【この問題の焦点】複数時点の関係変化と、その影響まで統合する。","① 登場人物ごとに発言・行動を分けて記録する。","② 人物間の関係が変わった前後と、その間の出来事を整理する。","③ 一方の行動が他方に与えた影響までつないで説明する。","④ 人物間の関係を、変化前後の行動とともに説明したか確かめる。"],"retry":"陸と航の関係がどのように変化し、その経験が陸にどう受け継がれたか説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数時点の関係変化と、その影響まで統合する。"},{"id":"p213","skill":"表現効果","level":4,"stage":"exam","passage":"卒業式のあと、教室では机を動かす音や笑い声が続いていた。最後の荷物を持って廊下へ出た真琴が振り返ると、黒板の端に消し残された日付だけがあった。真琴は戻って消そうとしたが、手を止め、そのまま扉を閉めた。","q":"「消し残された日付」の描写は、この場面でどのような効果をもっていますか。","answer":"日常が終わったあとの教室に最後の一日の痕跡を残すことで、真琴の卒業への名残惜しさや、時間が一区切りつく感覚を印象づけている。","guide":["【この問題の焦点】一つの描写を人物の心情と場面全体の意味の両方へ結びつける。","① 問われた描写をそのまま確認し、文字どおりの内容を捉える。","② 比喩・反復・情景などの表現が強調する印象を考える。","③ その印象を人物の心情や場面の意味と結びつけて答える。","④ 描写そのものと読者に与える印象を結び、本文にない事実を断定していないか確かめる。"],"retry":"「消し残された日付」の描写は、この場面でどのような効果をもっていますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一つの描写を人物の心情と場面全体の意味の両方へ結びつける。"},{"id":"p214","skill":"文章全体","level":4,"stage":"exam","passage":"便利な道具は、作業を速くする。しかし、速くできることと、考えなくてよいことは同じではない。計算機を使っても、どの計算が必要かは人が決める。検索ですぐ情報を得ても、その情報が目的に合うかは確かめなければならない。道具によって省ける作業が増えるほど、人が判断すべき部分を意識する必要がある。","q":"文章全体の主張を、二つの具体例をまとめる形で説明しなさい。","answer":"便利な道具で作業を速くしたり省いたりできても、何をするか、得た情報が適切かなど、人が判断すべき部分までなくなるわけではない。","guide":["【この問題の焦点】複数の具体例を包む共通主張を文章全体から作る。","① 各段落・場面の中心内容を一言ずつ書く。","② 具体例・対比・転換と結論の位置を整理する。","③ 複数箇所に共通する筆者の主張や作品の中心を一文にまとめる。","④ 具体例・対比・結論をつなぎ、文章全体の中心から外れていないか確かめる。"],"retry":"文章全体の主張を、二つの具体例をまとめる形で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の具体例を包む共通主張を文章全体から作る。"},{"id":"p215","skill":"設問分析","level":4,"stage":"exam","passage":"設問「第四段落で筆者が示した問題点を、第二段落の具体例との関係が分かるように、本文中の言葉を用いて六十字以内で説明しなさい。」","q":"この設問に答えるために必要な作業を、読む範囲と答案の条件に分けて整理しなさい。","answer":"第四段落から筆者の問題点を確認し、第二段落の具体例との関係を捉える。答案では本文中の言葉を使い、その関係が分かるよう六十字以内で説明する。","guide":["【この問題の焦点】複数段落の関係と複数の答案条件を同時に処理する。","① 設問の疑問語・条件・指定字数・解答形式に印を付ける。","② 条件ごとに本文のどの部分が根拠になるか対応表を作る。","③ 答案を作った後、問われた要素がすべて入っているか照合する。","④ 参照箇所・求められる内容・指定語・字数などの条件を漏れなく整理したか確かめる。"],"retry":"この設問に答えるために必要な作業を、読む範囲と答案の条件に分けて整理しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数段落の関係と複数の答案条件を同時に処理する。"},{"id":"p216","skill":"選択肢照合","level":4,"stage":"exam","passage":"筆者は、失敗を記録するだけでは十分でないと述べる。成功したときの条件も残して比べれば、何が結果に影響したかを考えやすいからだ。ただし、一度の成功と失敗だけで原因を決めつけてはいけないとも述べている。","q":"本文に最も合うものを選びなさい。\nア 成功だけを記録すれば原因が分かる。\nイ 成功と失敗を比べれば一度で原因を断定できる。\nウ 成功と失敗の条件を比較することは有効だが、少数の結果だけで原因を断定すべきではない。\nエ 失敗の記録は原因を考える妨げになる。","answer":"ウ","guide":["【この問題の焦点】本文の複数箇所を統合し、一部一致の誤答を除く。","① 選択肢を意味のまとまりごとに区切る。","② 各まとまりが本文のどこに対応するか探す。","③ 一部だけ一致する選択肢や、本文にない断定・因果を含むものを除く。","④ 各選択肢の断定や限定を本文と照らし、一部一致の誤答を除いたか確かめる。"],"retry":"本文に最も合うものを選びなさい。\nア 成功だけを記録すれば原因が分かる。\nイ 成功と失敗を比べれば一度で原因を断定できる。\nウ 成功と失敗の条件を比較することは有効だが、少数の結果だけで原因を断定すべきではない。\nエ 失敗の記録は原因を考える妨げになる。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"本文の複数箇所を統合し、一部一致の誤答を除く。"},{"id":"p217","skill":"抜き出し","level":4,"stage":"exam","passage":"話し合いでは、意見が違うとすぐ結論を比べたくなる。しかし、同じ言葉を別の意味で使っているために意見が違って見える場合もある。そこで、まず互いが言葉をどのような意味で使っているかを確かめる。そのうえで理由を比べると、本当に異なる点が見つけやすい。","q":"意見の違いを確かめる前に行うべきことを表す部分を、本文から二十五字以内で抜き出しなさい。","answer":"互いが言葉をどのような意味で使っているかを確かめる","guide":["【この問題の焦点】離れた説明との意味対応と字数条件を同時に満たす箇所を探す。","① 設問の意味に対応する本文の表現を候補として複数探す。","② 指定字数・始まりと終わり・表記条件を候補ごとに確認する。","③ 前後の文脈に入れて意味が合うかを最後に検証する。","④ 本文の語句を変えず、抜き出す範囲と字数・指定条件を満たしたか確かめる。"],"retry":"意見の違いを確かめる前に行うべきことを表す部分を、本文から二十五字以内で抜き出しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"離れた説明との意味対応と字数条件を同時に満たす箇所を探す。"},{"id":"p218","skill":"記述","level":4,"stage":"exam","passage":"学校では紙の連絡と電子連絡のどちらを使うか検討した。電子連絡はすぐ届き、変更もしやすい。一方、端末をいつでも確認できるとは限らない家庭もある。紙は配布に時間がかかるが、手元に残して確認しやすい。担当者は一方に統一せず、急な変更は電子、長く保存する予定表は紙にした。","q":"担当者が連絡方法を一つに統一しなかった理由を、二つの方法の特徴に触れて八十字以内で説明しなさい。","answer":"電子連絡は速く変更しやすいが常に確認できるとは限らず、紙は配布に時間がかかるが保存して確認しやすいため、目的に応じて使い分けたから。","guide":["【この問題の焦点】対立する複数根拠をまとめ、設問の因果関係に組み替える。","① 設問の問い方から、答案に必要な要素を二つ以上整理する。","② それぞれの要素を支える本文の箇所を探し、関係を矢印で結ぶ。","③ 指定字数と文末表現を守り、根拠から飛躍しない一文にまとめる。","④ 必要な根拠と説明をそろえ、指定語・字数などの条件を満たしたか確かめる。"],"retry":"担当者が連絡方法を一つに統一しなかった理由を、二つの方法の特徴に触れて八十字以内で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"対立する複数根拠をまとめ、設問の因果関係に組み替える。"},{"id":"p219","skill":"要約","level":4,"stage":"exam","passage":"新しい情報を集めることは大切だが、多ければ多いほど判断しやすくなるとは限らない。目的と関係の薄い情報まで増えると、重要な違いが見えにくくなるからだ。一方、最初から情報を絞りすぎれば、予想外の可能性を見落とす。必要なのは、目的を基準に集めながら、途中で必要性を見直すことである。","q":"文章の対立する二つの注意点と結論を残して、八十字以内で要約しなさい。","answer":"情報は増やしすぎると重要点が見えにくく、絞りすぎると可能性を見落とすため、目的を基準に集めつつ必要性を見直すことが大切である。","guide":["【この問題の焦点】対立する注意点と結論を残し、複数段落相当の内容を圧縮する。","① 段落・場面ごとに中心情報を短く書き出す。","② 例・繰り返し・補足と、残すべき主張や対比を分ける。","③ 重要な関係を保ったまま圧縮し、本文にない判断を足さない。","④ 中心の主張と必要な対比・因果を残し、具体例だけの羅列になっていないか確かめる。"],"retry":"文章の対立する二つの注意点と結論を残して、八十字以内で要約しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"対立する注意点と結論を残し、複数段落相当の内容を圧縮する。"},{"id":"p220","skill":"心情変化","level":4,"stage":"exam","passage":"文化祭の展示係になった陽菜は、最初「説明は紙に書いておけば十分」と考え、来場者に声をかけなかった。ところが、小学生が展示の前で何度も説明カードを読み直しているのを見て、「どこが分かりにくい？」と尋ねた。答えを聞いた陽菜は、模型を動かしながら説明した。帰りの会では「説明する側が待っているだけでは伝わらない」と話した。","q":"陽菜の考えはどのように変化しましたか。きっかけと行動を含めて説明しなさい。","answer":"説明は書いておけば十分だという考えから、小学生が説明カードを読み直す姿をきっかけに、相手の理解を確かめながら自分から伝え方を工夫する必要があるという考えへ変化した。","guide":["【この問題の焦点】離れた行動・発言を結び、変化前→きっかけ→変化後を作る。","① 変化前の言動と変化後の言動をそれぞれ抜き出す。","② 間に起きた出来事・相手の言葉を変化のきっかけとして確認する。","③ 初めの気持ち→きっかけ→変化後の気持ちの順でまとめる。","④ 変化前・きっかけ・変化後の三つがそろっているか確かめる。"],"retry":"陽菜の考えはどのように変化しましたか。きっかけと行動を含めて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"離れた行動・発言を結び、変化前→きっかけ→変化後を作る。"},{"id":"p221","skill":"心情変化","level":4,"stage":"exam","passage":"悠斗は合唱練習で自分の声が目立つことを気にし、小さな声で歌っていた。録音を聞くと、先生が「声が大きいかではなく、周りと息が合うかを聞いてみよう」と言った。もう一度聞いた悠斗は、隣の人と息を合わせる練習を始め、本番後には「消すんじゃなくて合わせればよかったんだ」と話した。","q":"悠斗の心情・考えの変化を、録音を聞く前後で説明しなさい。","answer":"自分の声を目立たせないよう抑えようとしていた状態から、周囲と息を合わせれば自分の声を生かせると考え、積極的に合わせようとする状態へ変化した。","guide":["【この問題の焦点】離れた行動・発言を結び、変化前→きっかけ→変化後を作る。","① 変化前の言動と変化後の言動をそれぞれ抜き出す。","② 間に起きた出来事・相手の言葉を変化のきっかけとして確認する。","③ 初めの気持ち→きっかけ→変化後の気持ちの順でまとめる。","④ 変化前・きっかけ・変化後の三つがそろっているか確かめる。"],"retry":"悠斗の心情・考えの変化を、録音を聞く前後で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"離れた行動・発言を結び、変化前→きっかけ→変化後を作る。"},{"id":"p222","skill":"因果関係","level":4,"stage":"exam","passage":"図書委員会では新刊紹介を入口に置いたが、貸出数はほとんど変わらなかった。調べると、紹介カードには題名とあらすじだけがあり、どんな人に向く本か分かりにくかった。そこで「短い話が好きな人へ」などの言葉を加えた。すると、普段その棚を見ない生徒も本を手に取るようになり、貸出数が増えた。","q":"貸出数が増えた理由を、改善前の問題点から順に説明しなさい。","answer":"紹介カードでは本がどんな人に向くか分かりにくかったため、読者に合う言葉を加えたところ、自分に関係のある本だと気づく生徒が増え、本を手に取るようになったから。","guide":["【この問題の焦点】問題点→改善→結果の三段階で因果をつなぐ。","① 結果を表す部分を先に探し、そこに至る出来事をさかのぼる。","② 直接の原因と、その間にある行動・工夫・条件を区別する。","③ 原因→途中の変化→結果の順に矢印で結び、飛躍がないか確かめる。","④ 原因・途中の過程・結果を区別し、飛躍がないか確かめる。"],"retry":"貸出数が増えた理由を、改善前の問題点から順に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"問題点→改善→結果の三段階で因果をつなぐ。"},{"id":"p223","skill":"因果関係","level":4,"stage":"exam","passage":"植物の成長を比べる実験で、一方だけ水の量も置く場所も変えてしまったため、成長差の原因を判断できなかった。次の実験では置く場所を同じにし、水の量だけを変えた。すると結果の違いを水の量との関係から考えられるようになった。","q":"二回目の実験で原因を考えやすくなった理由を、一回目との違いを含めて説明しなさい。","answer":"一回目は水の量と場所の二条件が違って原因を絞れなかったが、二回目は場所をそろえ水の量だけを変えたため、その条件と結果の関係を比べられたから。","guide":["【この問題の焦点】問題点→改善→結果の三段階で因果をつなぐ。","① 結果を表す部分を先に探し、そこに至る出来事をさかのぼる。","② 直接の原因と、その間にある行動・工夫・条件を区別する。","③ 原因→途中の変化→結果の順に矢印で結び、飛躍がないか確かめる。","④ 原因・途中の過程・結果を区別し、飛躍がないか確かめる。"],"retry":"二回目の実験で原因を考えやすくなった理由を、一回目との違いを含めて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"問題点→改善→結果の三段階で因果をつなぐ。"},{"id":"p224","skill":"文章全体","level":4,"stage":"exam","passage":"「分かりやすい説明」と聞くと、短い説明を思い浮かべるかもしれない。確かに不要な言葉を減らすことは大切だ。しかし、初めて聞く人に必要な前提まで削れば、短くても理解できない。反対に、相手がすでに知っていることを長く説明すれば、重要な部分が埋もれる。説明の長さそのものではなく、相手に必要な情報を選ぶことが分かりやすさにつながる。","q":"文章全体で筆者が最も伝えたいことを、前半の対比を踏まえて説明しなさい。","answer":"分かりやすい説明は単に短ければよいのではなく、相手が知っていることや必要としていることに応じて情報を選ぶことが大切だということ。","guide":["【この問題の焦点】具体例や対比を材料に、文章全体を包む主張へ抽象化する。","① 各段落・場面の中心内容を一言ずつ書く。","② 具体例・対比・転換と結論の位置を整理する。","③ 複数箇所に共通する筆者の主張や作品の中心を一文にまとめる。","④ 具体例・対比・結論をつなぎ、文章全体の中心から外れていないか確かめる。"],"retry":"文章全体で筆者が最も伝えたいことを、前半の対比を踏まえて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"具体例や対比を材料に、文章全体を包む主張へ抽象化する。"},{"id":"p225","skill":"文章全体","level":4,"stage":"exam","passage":"道に迷わないためには、詳しい地図ほどよいと思うかもしれない。だが、歩いて駅へ向かう人には自動車専用道路の細かな情報は必要ない。一方、目印になる建物や曲がり角は省けない。情報は多さではなく、目的に応じて必要なものが選ばれているときに役立つ。これは地図だけでなく、資料や説明にも当てはまる。","q":"地図の例を通して筆者が文章全体で述べている考えをまとめなさい。","answer":"情報は多いほどよいのではなく、目的に応じて必要なものを選ぶことで役立つという考え。","guide":["【この問題の焦点】具体例や対比を材料に、文章全体を包む主張へ抽象化する。","① 各段落・場面の中心内容を一言ずつ書く。","② 具体例・対比・転換と結論の位置を整理する。","③ 複数箇所に共通する筆者の主張や作品の中心を一文にまとめる。","④ 具体例・対比・結論をつなぎ、文章全体の中心から外れていないか確かめる。"],"retry":"地図の例を通して筆者が文章全体で述べている考えをまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"具体例や対比を材料に、文章全体を包む主張へ抽象化する。"},{"id":"p226","skill":"選択肢照合","level":4,"stage":"exam","passage":"失敗したとき、原因を一つに決めると安心することがある。しかし実際には、準備時間、方法、周囲の条件など複数の要因が重なる場合がある。原因を考えるときは、最初に思いついた説明だけで終わらず、別の可能性も確かめる必要がある。","q":"本文に最も合うものを選びなさい。\nア 失敗には必ず一つの原因がある。\nイ 最初に思いついた原因は無視すべきだ。\nウ 複数の要因が関係する可能性を考え、別の説明も確かめる必要がある。\nエ 原因を考えるより結果だけを記録すればよい。","answer":"ウ","guide":["【この問題の焦点】一部一致ではなく、本文の条件や限定まで含めて照合する。","① 選択肢を意味のまとまりごとに区切る。","② 各まとまりが本文のどこに対応するか探す。","③ 一部だけ一致する選択肢や、本文にない断定・因果を含むものを除く。","④ 各選択肢の断定や限定を本文と照らし、一部一致の誤答を除いたか確かめる。"],"retry":"本文に最も合うものを選びなさい。\nア 失敗には必ず一つの原因がある。\nイ 最初に思いついた原因は無視すべきだ。\nウ 複数の要因が関係する可能性を考え、別の説明も確かめる必要がある。\nエ 原因を考えるより結果だけを記録すればよい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一部一致ではなく、本文の条件や限定まで含めて照合する。"},{"id":"p227","skill":"選択肢照合","level":4,"stage":"exam","passage":"他人の意見を理解することは、その意見に賛成することと同じではない。なぜそう考えたのかをたどれば、自分と異なる前提が見えることがある。その違いを確認したうえで、賛成か反対かを判断すればよい。","q":"本文に最も合うものを選びなさい。\nア 理解した意見には賛成しなければならない。\nイ 賛否を決める前に、その意見の理由や前提を理解することが大切である。\nウ 自分と違う前提の意見は理解できない。\nエ 意見の理由より、賛成か反対かを先に決めるべきだ。","answer":"イ","guide":["【この問題の焦点】一部一致ではなく、本文の条件や限定まで含めて照合する。","① 選択肢を意味のまとまりごとに区切る。","② 各まとまりが本文のどこに対応するか探す。","③ 一部だけ一致する選択肢や、本文にない断定・因果を含むものを除く。","④ 各選択肢の断定や限定を本文と照らし、一部一致の誤答を除いたか確かめる。"],"retry":"本文に最も合うものを選びなさい。\nア 理解した意見には賛成しなければならない。\nイ 賛否を決める前に、その意見の理由や前提を理解することが大切である。\nウ 自分と違う前提の意見は理解できない。\nエ 意見の理由より、賛成か反対かを先に決めるべきだ。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一部一致ではなく、本文の条件や限定まで含めて照合する。"},{"id":"p228","skill":"抜き出し","level":4,"stage":"exam","passage":"観察するとき、予想を持つことは見るべき点を決める助けになる。ただし、予想に合うものだけを探すと、別の変化を見落とす。そこで、予想した点を確かめると同時に、予想外の変化も記録することが必要である。","q":"予想を持って観察するとき、予想に合わない変化について必要なことを表す部分を、三十字以内で本文から抜き出しなさい。","answer":"予想外の変化も記録すること","guide":["【この問題の焦点】設問を言い換えてから、意味と字数の両条件に合う箇所を取る。","① 設問の意味に対応する本文の表現を候補として複数探す。","② 指定字数・始まりと終わり・表記条件を候補ごとに確認する。","③ 前後の文脈に入れて意味が合うかを最後に検証する。","④ 本文の語句を変えず、抜き出す範囲と字数・指定条件を満たしたか確かめる。"],"retry":"予想を持ちながら観察するとき必要なことを表す部分を、三十字以内で抜き出しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"設問を言い換えてから、意味と字数の両条件に合う箇所を取る。"},{"id":"p229","skill":"抜き出し","level":4,"stage":"exam","passage":"話し合いで結論が一致しても、理由まで同じとは限らない。今は同じ結論でも、条件が変われば判断が分かれる可能性がある。そのため、結論だけでなく、そこに至った理由も確かめておくことが大切である。","q":"条件が変わった場合に備えて確認すべきことを、本文から二十字以内で抜き出しなさい。","answer":"そこに至った理由","guide":["【この問題の焦点】設問を言い換えてから、意味と字数の両条件に合う箇所を取る。","① 設問の意味に対応する本文の表現を候補として複数探す。","② 指定字数・始まりと終わり・表記条件を候補ごとに確認する。","③ 前後の文脈に入れて意味が合うかを最後に検証する。","④ 本文の語句を変えず、抜き出す範囲と字数・指定条件を満たしたか確かめる。"],"retry":"条件が変わった場合に備えて確認すべきことを、本文から二十字以内で抜き出しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"設問を言い換えてから、意味と字数の両条件に合う箇所を取る。"},{"id":"p230","skill":"記述","level":4,"stage":"exam","passage":"学校の花壇で、日当たりのよい場所の花がよく育っていた。生徒は「日光が原因だ」と考えたが、その場所だけ水やりの回数も多いと分かった。そこで次は水の量をそろえて観察することにした。","q":"生徒が水の量をそろえる必要がある理由を、七十字以内で説明しなさい。","answer":"日当たりと水やりの両方が違うままでは、花の成長差がどちらの条件によるものか判断できないため。","guide":["【この問題の焦点】複数の本文情報を因果・比較の形に組み替えて答案化する。","① 設問の問い方から、答案に必要な要素を二つ以上整理する。","② それぞれの要素を支える本文の箇所を探し、関係を矢印で結ぶ。","③ 指定字数と文末表現を守り、根拠から飛躍しない一文にまとめる。","④ 必要な根拠と説明をそろえ、指定語・字数などの条件を満たしたか確かめる。"],"retry":"生徒が水の量をそろえる必要がある理由を、七十字以内で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の本文情報を因果・比較の形に組み替えて答案化する。"},{"id":"p231","skill":"記述","level":4,"stage":"exam","passage":"地域紹介の記事を書くため、昔から住む人だけに話を聞くと、「静かな町」という意見が多かった。一方、最近引っ越してきた人からは「交通が便利」という意見が出た。担当者は両方を記事に載せた。","q":"担当者が両方の意見を載せた理由を、八十字以内で説明しなさい。","answer":"住んできた期間によって町の見え方が異なり、一方だけでは地域の特徴を偏って伝えることになるため、異なる立場の見方を示す必要があるから。","guide":["【この問題の焦点】複数の本文情報を因果・比較の形に組み替えて答案化する。","① 設問の問い方から、答案に必要な要素を二つ以上整理する。","② それぞれの要素を支える本文の箇所を探し、関係を矢印で結ぶ。","③ 指定字数と文末表現を守り、根拠から飛躍しない一文にまとめる。","④ 必要な根拠と説明をそろえ、指定語・字数などの条件を満たしたか確かめる。"],"retry":"担当者が両方の意見を載せた理由を、八十字以内で説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の本文情報を因果・比較の形に組み替えて答案化する。"},{"id":"p232","skill":"要約","level":4,"stage":"exam","passage":"計画を立てると、何をいつ行うかが明確になる。しかし、計画どおりに進めること自体が目的になると、状況が変わっても無理に続けてしまう。計画は行動を縛るものではなく、目的へ進むための見通しである。途中で状況を確かめ、必要なら直すことで役立つ。","q":"対比と結論を残して七十字以内で要約しなさい。","answer":"計画は行動を明確にするが、守ること自体を目的にせず、目的へ進むため状況に応じて見直すことが大切である。","guide":["【この問題の焦点】文章の対比・原因・結論を見分け、骨組みだけを指定字数に残す。","① 段落・場面ごとに中心情報を短く書き出す。","② 例・繰り返し・補足と、残すべき主張や対比を分ける。","③ 重要な関係を保ったまま圧縮し、本文にない判断を足さない。","④ 中心の主張と必要な対比・因果を残し、具体例だけの羅列になっていないか確かめる。"],"retry":"対比と結論を残して七十字以内で要約しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"文章の対比・原因・結論を見分け、骨組みだけを指定字数に残す。"},{"id":"p233","skill":"要約","level":4,"stage":"exam","passage":"多くの人の意見を集めれば、必ず公平になるわけではない。質問の仕方や答えた人の偏りによって結果は変わるからだ。人数の多さだけを見るのではなく、誰にどのように尋ねたかも確かめる必要がある。","q":"原因と結論を残して六十字以内で要約しなさい。","answer":"意見調査は質問方法や回答者の偏りで結果が変わるため、人数だけでなく誰にどう尋ねたかも確認する必要がある。","guide":["【この問題の焦点】文章の対比・原因・結論を見分け、骨組みだけを指定字数に残す。","① 段落・場面ごとに中心情報を短く書き出す。","② 例・繰り返し・補足と、残すべき主張や対比を分ける。","③ 重要な関係を保ったまま圧縮し、本文にない判断を足さない。","④ 中心の主張と必要な対比・因果を残し、具体例だけの羅列になっていないか確かめる。"],"retry":"原因と結論を残して六十字以内で要約しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"文章の対比・原因・結論を見分け、骨組みだけを指定字数に残す。"},{"id":"p234","skill":"主語・主体","level":4,"stage":"exam","passage":"発表準備で、真帆は資料の図を直し、圭太は説明文を短くした。先生が「数字の出典も確かめて」と言うと、真帆は図の下の数字を指した。圭太は元の資料を開き、掲載年を確認して書き加えた。そのあと「これで図だけ見ても分かる」と言って、真帆に画面を戻した。","q":"「掲載年を確認して書き加えた」のは誰ですか。前後の動作を根拠に答えなさい。","answer":"圭太。元の資料を開いて掲載年を確認した人物が、その流れで書き加えているから。","guide":["【この問題の焦点】複数人物が連続して登場する中で、動作・発言のつながりから主体を追う。","① 動作を表す語を順に丸で囲み、各動作の直前・直後の人物名を探す。","② 主語が省略された箇所は、会話の話者と動作の連続性を照合する。","③ 設問で指定された動作ごとに主体を対応させ、混同していないか確かめる。","④ 動作ごとの主体と、その判断の根拠を確かめる。"],"retry":"「掲載年を確認して書き加えた」のは誰ですか。前後の動作を根拠に答えなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数人物が連続して登場する中で、動作・発言のつながりから主体を追う。"},{"id":"p235","skill":"主語・主体","level":4,"stage":"exam","passage":"美術部で、彩は作品を壁に並べ、遥は題名カードを置いていた。彩が「入口からだと奥が見えにくいね」と言うと、遥は一度廊下へ出た。戻ってくると中央の台を少し動かし、「これなら最後まで見える」と言った。彩はその位置に合わせて作品を並べ直した。","q":"「中央の台を少し動かした」のは誰ですか。人物の移動と発言を根拠に答えなさい。","answer":"遥。廊下へ出て見え方を確かめ、戻って「これなら最後まで見える」と言った人物が台を動かしているから。","guide":["【この問題の焦点】複数人物が連続して登場する中で、動作・発言のつながりから主体を追う。","① 動作を表す語を順に丸で囲み、各動作の直前・直後の人物名を探す。","② 主語が省略された箇所は、会話の話者と動作の連続性を照合する。","③ 設問で指定された動作ごとに主体を対応させ、混同していないか確かめる。","④ 動作ごとの主体と、その判断の根拠を確かめる。"],"retry":"「中央の台を少し動かした」のは誰ですか。人物の移動と発言を根拠に答えなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数人物が連続して登場する中で、動作・発言のつながりから主体を追う。"},{"id":"p236","skill":"指示語","level":4,"stage":"exam","passage":"班では最初、発表資料を読む順番どおりに作っていた。しかし聞き手から「結論が最後まで分からない」と言われた。そこで最初に結論を示し、そのあと理由と具体例を置く構成に変えた。すると聞き手は、何に注目して聞けばよいか分かりやすくなった。この工夫によって、同じ内容でも伝わり方が変わった。","q":"「この工夫」が指す内容を、変更前との違いが分かるように答えなさい。","answer":"結論を最後に示す構成から、最初に結論を示してから理由と具体例を説明する構成へ変えたこと。","guide":["【この問題の焦点】一語ではなく、前の複数文の内容をまとめて指示内容にする。","① 設問にある指示語を本文で見つけ、その前後の文を区切る。","② 候補となる内容を複数拾い、指示語がまとめている範囲を確かめる。","③ 指示語を具体的な表現に置き換え、文意が通るか検証する。","④ 指示内容に含める出来事と、前後の変化が欠けていないか確かめる。"],"retry":"「この工夫」が指す内容を、変更前との違いが分かるように答えなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一語ではなく、前の複数文の内容をまとめて指示内容にする。"},{"id":"p237","skill":"指示語","level":4,"stage":"exam","passage":"校内新聞では、記事を学年別に並べていたが、読みたい内容を探しにくいという声があった。そこで学年ではなく「行事」「部活動」「学習」など内容別に分け、各欄に見出しを付けた。読む人は興味のある欄へ直接進めるようになった。こうした整理は、情報の量を減らさなくても探しやすさを変えられる例である。","q":"「こうした整理」が指す内容を具体的に説明しなさい。","answer":"記事を学年別ではなく内容別に分け、それぞれに見出しを付けたこと。","guide":["【この問題の焦点】一語ではなく、前の複数文の内容をまとめて指示内容にする。","① 設問にある指示語を本文で見つけ、その前後の文を区切る。","② 候補となる内容を複数拾い、指示語がまとめている範囲を確かめる。","③ 指示語を具体的な表現に置き換え、文意が通るか検証する。","④ 指示内容に含める出来事と、前後の変化が欠けていないか確かめる。"],"retry":"「こうした整理」が指す内容を具体的に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一語ではなく、前の複数文の内容をまとめて指示内容にする。"},{"id":"p238","skill":"接続関係","level":4,"stage":"exam","passage":"練習回数を増やせば上達することは多い。ところが、同じ間違いを繰り返したまま回数だけ増やしても改善しない。間違えた場所と理由を確かめ、方法を変えて試す必要がある。したがって、練習では量だけでなく、途中で方法を見直すことが重要である。","q":"「ところが」と「したがって」は、筆者の考えをどのように展開する働きをしていますか。","answer":"「ところが」は練習量を増やすだけでは不十分という反対面を示し、「したがって」はその理由を受けて方法を見直す重要性を結論として示している。","guide":["【この問題の焦点】複数の接続表現をつないで文章の論理展開を説明する。","① 接続語の前後をそれぞれ短い文に言い換える。","② 前後が逆接・理由・補足・言い換えのどの関係か、内容から判断する。","③ 接続語の働きと前後の具体的内容を分けて説明する。","④ 各接続語の働きと、文章全体の論理の流れを対応させる。"],"retry":"「ところが」と「したがって」は、筆者の考えをどのように展開する働きをしていますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の接続表現をつないで文章の論理展開を説明する。"},{"id":"p239","skill":"接続関係","level":4,"stage":"exam","passage":"資料を細かく作れば、正確な説明ができる。一方で、細部が多すぎると中心が見えにくくなることもある。そこで、詳しい資料は残しつつ、発表では必要な部分だけを示す方法が考えられる。つまり、情報を減らすか残すかではなく、目的に応じて見せ方を変えることが大切なのである。","q":"「一方で」「そこで」「つまり」の三つが作る論理の流れを説明しなさい。","answer":"「一方で」が詳しさの問題点を示し、「そこで」がその問題への方法を提示し、「つまり」がそれらを目的に応じた見せ方という考えにまとめている。","guide":["【この問題の焦点】複数の接続表現をつないで文章の論理展開を説明する。","① 接続語の前後をそれぞれ短い文に言い換える。","② 前後が逆接・理由・補足・言い換えのどの関係か、内容から判断する。","③ 接続語の働きと前後の具体的内容を分けて説明する。","④ 各接続語の働きと、文章全体の論理の流れを対応させる。"],"retry":"「一方で」「そこで」「つまり」の三つが作る論理の流れを説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の接続表現をつないで文章の論理展開を説明する。"},{"id":"p240","skill":"事実・推測","level":4,"stage":"exam","passage":"昼休み、校庭のサッカーゴールには使用禁止の札が掛かっていた。亮はボールを持って校庭まで来たが、札を見ると体育館へ向かった。体育館では友人がバスケットボールをしていた。亮が何をするかは本文には書かれていない。","q":"「亮はバスケットボールをすることにした」と断定できますか。複数の事実を使って答えなさい。","answer":"断定できない。亮が使用禁止の札を見て体育館へ向かい、そこにバスケットボールをする友人がいたことは事実だが、亮が参加すると本文には書かれていないから。","guide":["【この問題の焦点】複数の事実から推測できても、断定できる範囲を越えない。","① 本文で実際に起きたこと・観察されたことに線を引く。","② 人物の予想や判断を別に囲み、事実と混ぜない。","③ 設問の断定が本文の情報だけで可能か、不明な点を明示する。","④ 直接書かれた事実と推測を分け、断定しすぎていないか確かめる。"],"retry":"「亮はバスケットボールをすることにした」と断定できますか。複数の事実を使って答えなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の事実から推測できても、断定できる範囲を越えない。"},{"id":"p241","skill":"事実・推測","level":4,"stage":"exam","passage":"朝、菜月は傘を持って家を出た。空は曇っていたが、雨は降っていなかった。駅で友人に「午後は降るみたいだよ」と言われると、菜月は「持ってきてよかった」と答えた。","q":"「菜月は家を出る前に午後の雨を知っていた」と言えますか。本文の事実と推測を分けて説明しなさい。","answer":"言えない。傘を持って出たことは事実だが、その理由は書かれていない。午後の雨については駅で友人から聞いているため、家を出る前から知っていたとは断定できない。","guide":["【この問題の焦点】複数の事実から推測できても、断定できる範囲を越えない。","① 本文で実際に起きたこと・観察されたことに線を引く。","② 人物の予想や判断を別に囲み、事実と混ぜない。","③ 設問の断定が本文の情報だけで可能か、不明な点を明示する。","④ 直接書かれた事実と推測を分け、断定しすぎていないか確かめる。"],"retry":"「菜月は家を出る前に午後の雨を知っていた」と言えますか。本文の事実と推測を分けて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の事実から推測できても、断定できる範囲を越えない。"},{"id":"p242","skill":"心情","level":4,"stage":"exam","passage":"試合に出られなかった玲奈は、片づけの間もほとんど話さなかった。帰り際、監督から「相手の動きを記録してくれて助かった」と言われると、玲奈はノートを開き、「次はここも見ておきます」と答えた。駅へ向かう途中には、次の対戦相手のページに付箋を貼っていた。","q":"後半の玲奈の心情を、前半との違いと行動を根拠に説明しなさい。","answer":"試合に出られず沈んでいた気持ちから、自分の記録もチームの役に立つと気づき、次も貢献しようと前向きになる気持ち。","guide":["【この問題の焦点】離れた複数の行動を根拠に、直接書かれない心情を説明する。","① 気持ちが問われる場面の発言・行動・描写を拾う。","② 同じ人物の前後の行動を比べ、気持ちを直接表す語がなくても推測する。","③ 感情の名称だけで終えず、そのように判断した本文の根拠を添える。","④ 気持ちの説明が行動・発言などの根拠と結びついているか確かめる。"],"retry":"後半の玲奈の心情を、前半との違いと行動を根拠に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"離れた複数の行動を根拠に、直接書かれない心情を説明する。"},{"id":"p243","skill":"心情","level":4,"stage":"exam","passage":"作品展で賞を逃した航は、結果の紙を折ってかばんに入れた。帰る前、他校の作品の前で長く立ち止まり、写真を撮っていた。友人に「もう帰る？」と聞かれると、「この光の使い方だけ見てから」と答えた。翌日のノートには、新しい構図の案が三つ描かれていた。","q":"航の心情を、結果を知った直後とその後の行動を結びつけて説明しなさい。","answer":"賞を逃して落胆した様子も見られるが、、他の作品から学んで次の制作に生かそうという意欲を取り戻している。","guide":["【この問題の焦点】離れた複数の行動を根拠に、直接書かれない心情を説明する。","① 気持ちが問われる場面の発言・行動・描写を拾う。","② 同じ人物の前後の行動を比べ、気持ちを直接表す語がなくても推測する。","③ 感情の名称だけで終えず、そのように判断した本文の根拠を添える。","④ 気持ちの説明が行動・発言などの根拠と結びついているか確かめる。"],"retry":"航の心情を、結果を知った直後とその後の行動を結びつけて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"離れた複数の行動を根拠に、直接書かれない心情を説明する。"},{"id":"p244","skill":"きっかけ","level":4,"stage":"exam","passage":"学級新聞の文章を何度直しても長くなり、結衣は小さな字にして収めようとした。印刷した紙を離れて見ると、題名まで読みにくくなっていた。そこで文章をもう一度読み、「なくても意味が変わらない説明」に線を引いて削った。","q":"結衣が文字を小さくする方法をやめた直接のきっかけと、その後の判断を答えなさい。","answer":"印刷した紙を離れて見て題名まで読みにくいと分かったことがきっかけで、文字ではなく不要な説明を削ると判断した。","guide":["【この問題の焦点】変化の直前の出来事と、そこから生じた気づきを分ける。","① 人物の考え・行動が変わる前と後を比べる。","② その間に起きた出来事と、人物がそこから気づいたことを分ける。","③ 単なる出来事の紹介ではなく、変化とのつながりを説明する。","④ 直接のきっかけと、その後の判断や行動を混同していないか確かめる。"],"retry":"結衣が文字を小さくする方法をやめた直接のきっかけと、その後の判断を答えなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"変化の直前の出来事と、そこから生じた気づきを分ける。"},{"id":"p245","skill":"きっかけ","level":4,"stage":"exam","passage":"健は発表で質問されるのが嫌で、想定質問への答えをすべて原稿に加えようとした。しかし練習を聞いた友人から「情報が多くて中心が分からない」と言われた。健は質問用のメモを別に作り、発表原稿には中心内容だけを残した。","q":"健が原稿と質問用メモを分けることにしたきっかけと気づきを説明しなさい。","answer":"友人に情報が多く中心が分からないと言われたことがきっかけで、質問への備えと発表で伝える中心内容は分けた方がよいと気づいた。","guide":["【この問題の焦点】変化の直前の出来事と、そこから生じた気づきを分ける。","① 人物の考え・行動が変わる前と後を比べる。","② その間に起きた出来事と、人物がそこから気づいたことを分ける。","③ 単なる出来事の紹介ではなく、変化とのつながりを説明する。","④ 直接のきっかけと、その後の判断や行動を混同していないか確かめる。"],"retry":"健が原稿と質問用メモを分けることにしたきっかけと気づきを説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"変化の直前の出来事と、そこから生じた気づきを分ける。"},{"id":"p246","skill":"人物像","level":4,"stage":"exam","passage":"図書係の紗季は、返却棚が乱れていると自分で全部直すのではなく、分類番号が見えるよう一冊だけ置き直した。そして後から来た係に「この並び方なら、次はどこだと思う？」と尋ねた。相手が直し始めると、紗季は別の作業へ移った。","q":"紗季の人物像を、二つ以上の行動を根拠に説明しなさい。","answer":"自分で答えを与えるのではなく手がかりや問いを示し、相手が自分で考えて作業できるよう支える人物。","guide":["【この問題の焦点】複数場面・複数行動に共通する性質を抽象化する。","① 同じ人物の異なる場面での言動を二つ以上拾う。","② 一回限りの行動と、複数場面に共通する姿勢を区別する。","③ 人物の特徴を抽象語で示し、具体的な行動を根拠として添える。","④ 性格を表す言葉だけでなく、複数の行動を根拠に示したか確かめる。"],"retry":"紗季の人物像を、二つ以上の行動を根拠に説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数場面・複数行動に共通する性質を抽象化する。"},{"id":"p247","skill":"人物像","level":4,"stage":"exam","passage":"大会前、部長の大地は自分の練習を早く終えたが、すぐ帰らなかった。初心者の練習を見ると、失敗するたびに直す点を一つだけ伝えた。最後に「今日はここまでできた」と記録を渡し、自分の反省ノートにも指導に時間を使いすぎなかったかを書いた。","q":"大地の人物像を、初心者への接し方と自分への振り返りの両方から説明しなさい。","answer":"相手が取り組みやすいよう課題を絞って支援するとともに、自分の指導の仕方も振り返って改善しようとする人物。","guide":["【この問題の焦点】複数場面・複数行動に共通する性質を抽象化する。","① 同じ人物の異なる場面での言動を二つ以上拾う。","② 一回限りの行動と、複数場面に共通する姿勢を区別する。","③ 人物の特徴を抽象語で示し、具体的な行動を根拠として添える。","④ 性格を表す言葉だけでなく、複数の行動を根拠に示したか確かめる。"],"retry":"大地の人物像を、初心者への接し方と自分への振り返りの両方から説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数場面・複数行動に共通する性質を抽象化する。"},{"id":"p248","skill":"会話文","level":4,"stage":"exam","passage":"展示の説明を作るとき、優斗が「全部書かないと誤解される」と言った。杏は「読む人が一番知りたいことは何だろう」と尋ねた。優斗は来場者アンケートを見直し、「作り方より、なぜ作ったかを先に知りたい人が多い」と気づき、説明の順番を変えた。","q":"杏の発言は優斗にどのような考え直しをさせましたか。","answer":"情報をすべて載せることから、読む人が知りたい内容を基準に情報の優先順位を決めることへ考えを向けさせた。","guide":["【この問題の焦点】一つの発言が相手の判断基準や話し合いの進め方をどう変えたか読む。","① 発言の話者と相手を整理し、発言順に番号を付ける。","② 問いかけ・提案・反論が何に対するものか前の発言と結ぶ。","③ 会話後の行動や考えの変化を確認し、発言の役割を説明する。","④ 発言の意図と、発言後の行動・反応を区別して説明したか確かめる。"],"retry":"杏の発言は優斗にどのような考え直しをさせましたか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一つの発言が相手の判断基準や話し合いの進め方をどう変えたか読む。"},{"id":"p249","skill":"会話文","level":4,"stage":"exam","passage":"話し合いで二つの案が対立したとき、陸は「どっちが正しいか決めよう」と言った。美咲は「二つの案は、何を一番大事にしているの？」と尋ねた。調べると、一方は費用、もう一方は使いやすさを重視していた。陸は「条件を決めてから比べよう」と言い直した。","q":"美咲の発言は話し合いの進め方をどう変えましたか。","answer":"案の結論だけを比べる進め方から、それぞれが重視する条件を明らかにし、共通の基準を決めて比較する進め方へ変えた。","guide":["【この問題の焦点】一つの発言が相手の判断基準や話し合いの進め方をどう変えたか読む。","① 発言の話者と相手を整理し、発言順に番号を付ける。","② 問いかけ・提案・反論が何に対するものか前の発言と結ぶ。","③ 会話後の行動や考えの変化を確認し、発言の役割を説明する。","④ 発言の意図と、発言後の行動・反応を区別して説明したか確かめる。"],"retry":"美咲の発言は話し合いの進め方をどう変えましたか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"一つの発言が相手の判断基準や話し合いの進め方をどう変えたか読む。"},{"id":"p250","skill":"具体と抽象","level":4,"stage":"exam","passage":"料理の手順書では重要な温度を太字にし、避難経路図では出口を目立つ記号で示し、教科書では重要語を囲んでいる。使う場面は違うが、いずれもすべての情報を同じ強さで示してはいない。","q":"三つの例に共通する情報の示し方を抽象的にまとめなさい。","answer":"情報に重要度の差をつけ、必要な部分を視覚的に目立たせて見つけやすくする方法。","guide":["【この問題の焦点】異なる場面の具体例を、共通する目的・方法へ抽象化する。","① 本文中の具体的な例や行動を複数探す。","② 各例に共通する性質を、例にない言葉で短くまとめる。","③ まとめた抽象的な表現がすべての例に当てはまるか確認する。","④ 具体例の列挙で終わらず、共通する上位の考えを示したか確かめる。"],"retry":"三つの例に共通する情報の示し方を抽象的にまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"異なる場面の具体例を、共通する目的・方法へ抽象化する。"},{"id":"p251","skill":"具体と抽象","level":4,"stage":"exam","passage":"スポーツでは練習後に動画を見返し、理科では実験結果を表にし、学習では間違えた問題に印を付ける。いずれも活動そのものが終わったあとに記録を利用している。","q":"三つの具体例に共通する目的を、一段抽象的にまとめなさい。","answer":"活動の記録を振り返って結果や問題点を確認し、次の行動や改善に生かすこと。","guide":["【この問題の焦点】異なる場面の具体例を、共通する目的・方法へ抽象化する。","① 本文中の具体的な例や行動を複数探す。","② 各例に共通する性質を、例にない言葉で短くまとめる。","③ まとめた抽象的な表現がすべての例に当てはまるか確認する。","④ 具体例の列挙で終わらず、共通する上位の考えを示したか確かめる。"],"retry":"三つの具体例に共通する目的を、一段抽象的にまとめなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"異なる場面の具体例を、共通する目的・方法へ抽象化する。"},{"id":"p252","skill":"人物関係","level":4,"stage":"exam","passage":"入部したころ、美緒は先輩の葵に毎回手順を確認していた。しばらくすると葵は「まず自分の案を見せて」と言うようになり、美緒も案を作ってから相談するようになった。大会前には、葵が美緒に「この部分は任せる」と伝え、美緒が後輩へ指示を出した。","q":"美緒と葵の関係の変化を三つの時期を踏まえて説明しなさい。","answer":"美緒が葵の指示を受ける関係から、自分で考えて相談する関係へ進み、最後には葵から役割を任される関係へ変化した。","guide":["【この問題の焦点】複数時点を比べ、二人の役割や協力の仕方の変化を統合する。","① 登場人物ごとに発言・行動を分けて記録する。","② 人物間の関係が変わった前後と、その間の出来事を整理する。","③ 一方の行動が他方に与えた影響までつないで説明する。","④ 人物間の関係を、変化前後の行動とともに説明したか確かめる。"],"retry":"美緒と葵の関係の変化を三つの時期を踏まえて説明しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数時点を比べ、二人の役割や協力の仕方の変化を統合する。"},{"id":"p253","skill":"人物関係","level":4,"stage":"exam","passage":"最初、拓也と修は互いの案の欠点ばかり指摘していた。先生に「共通して残したい点は？」と聞かれ、二人はどちらの案にも安全性を重視する部分があると気づいた。その後は共通部分を土台にし、違う部分だけを比較して一つの案を作った。","q":"拓也と修の関係・協力の仕方はどのように変わりましたか。","answer":"互いの案を否定し合う状態から、共通する目的を確認し、その共通点を土台に違いを調整して協力する状態へ変わった。","guide":["【この問題の焦点】複数時点を比べ、二人の役割や協力の仕方の変化を統合する。","① 登場人物ごとに発言・行動を分けて記録する。","② 人物間の関係が変わった前後と、その間の出来事を整理する。","③ 一方の行動が他方に与えた影響までつないで説明する。","④ 人物間の関係を、変化前後の行動とともに説明したか確かめる。"],"retry":"拓也と修の関係・協力の仕方はどのように変わりましたか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数時点を比べ、二人の役割や協力の仕方の変化を統合する。"},{"id":"p254","skill":"表現効果","level":4,"stage":"exam","passage":"発表直前まで教室には紙をめくる音や話し声が続いていた。名前を呼ばれた瞬間、海斗には時計の秒針だけがやけに大きく聞こえた。壇上へ歩き始めると、今度は自分の靴音が一歩ずつ響いた。","q":"秒針や靴音を強調する表現にはどのような効果がありますか。","answer":"周囲の音が意識から消え、細かな音だけが強く感じられる描写によって、海斗の緊張と発表直前の張りつめた感覚を印象づけている。","guide":["【この問題の焦点】特徴的な描写を、心情と場面全体の印象へ結びつける。","① 問われた描写をそのまま確認し、文字どおりの内容を捉える。","② 比喩・反復・情景などの表現が強調する印象を考える。","③ その印象を人物の心情や場面の意味と結びつけて答える。","④ 描写そのものと読者に与える印象を結び、本文にない事実を断定していないか確かめる。"],"retry":"秒針や靴音を強調する表現にはどのような効果がありますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"特徴的な描写を、心情と場面全体の印象へ結びつける。"},{"id":"p255","skill":"表現効果","level":4,"stage":"exam","passage":"引っ越しの日、空になった部屋の壁には、机を置いていた部分だけ色の違う四角形が残っていた。瑞希は荷物を持って出たあと一度戻り、その四角形を指でなぞってから電気を消した。","q":"壁に残った「色の違う四角形」の描写はどのような効果をもっていますか。","answer":"家具がなくなった後にも以前の生活の痕跡が残る様子によって、瑞希の過ごした時間への名残惜しさを印象づけている。","guide":["【この問題の焦点】特徴的な描写を、心情と場面全体の印象へ結びつける。","① 問われた描写をそのまま確認し、文字どおりの内容を捉える。","② 比喩・反復・情景などの表現が強調する印象を考える。","③ その印象を人物の心情や場面の意味と結びつけて答える。","④ 描写そのものと読者に与える印象を結び、本文にない事実を断定していないか確かめる。"],"retry":"壁に残った「色の違う四角形」の描写はどのような効果をもっていますか。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"特徴的な描写を、心情と場面全体の印象へ結びつける。"},{"id":"p256","skill":"設問分析","level":4,"stage":"exam","passage":"設問「第五段落の『この判断』とはどのような判断か。第一段落の問題点と第四段落で示された変化の両方に触れ、本文中の言葉を使って七十字以内で説明しなさい。」","q":"この設問で、本文から探す内容と答案で守る条件をすべて整理しなさい。","answer":"第五段落の「この判断」の内容を確認し、第一段落の問題点と第四段落の変化を関連づける。答案はその両方に触れ、本文中の言葉を使い七十字以内で説明する。","guide":["【この問題の焦点】複数の参照箇所・答案条件・禁止条件を分解し、解答前に必要部品を整理する。","① 設問の疑問語・条件・指定字数・解答形式に印を付ける。","② 条件ごとに本文のどの部分が根拠になるか対応表を作る。","③ 答案を作った後、問われた要素がすべて入っているか照合する。","④ 参照箇所・求められる内容・指定語・字数などの条件を漏れなく整理したか確かめる。"],"retry":"この設問で、本文から探す内容と答案で守る条件をすべて整理しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の参照箇所・答案条件・禁止条件を分解し、解答前に必要部品を整理する。"},{"id":"p257","skill":"設問分析","level":4,"stage":"exam","passage":"設問「筆者が二つの例を挙げた目的を、第三段落の主張との関係が分かるように説明しなさい。ただし、例の内容そのものを並べるだけの答えにしないこと。」","q":"この設問で求められている答案と、してはいけない答え方を整理しなさい。","answer":"二つの例が第三段落の主張をどのように支えているかを説明する必要があり、二つの例の内容を単に列挙するだけではいけない。","guide":["【この問題の焦点】複数の参照箇所・答案条件・禁止条件を分解し、解答前に必要部品を整理する。","① 設問の疑問語・条件・指定字数・解答形式に印を付ける。","② 条件ごとに本文のどの部分が根拠になるか対応表を作る。","③ 答案を作った後、問われた要素がすべて入っているか照合する。","④ 参照箇所・求められる内容・指定語・字数などの条件を漏れなく整理したか確かめる。"],"retry":"この設問で求められている答案と、してはいけない答え方を整理しなさい。\n本文のどの表現を根拠にしたかも確認し、根拠となる箇所に線を引いてから、もう一度答えなさい。","explain":"複数の参照箇所・答案条件・禁止条件を分解し、解答前に必要部品を整理する。"}],"bigsets":[{"id":"b1","genre":"物語","title":"相談するということ","level":"標準","passage":"放課後、教室には机を動かす音だけが残っていた。文化祭の展示について、班で最後の相談をすることになっていたからだ。健太は、これまで何度も自分の案を出そうとして、そのたびに言葉をのみ込んでいた。自分の考えを話せば、話し合いが長引くかもしれない。みんながすでに決めかけていることを、わざわざ変える必要はないのではないか。そう思うと、手を挙げるきっかけを失ってしまうのだった。\n\nその日も、展示の説明文を短くする案で話がまとまりかけていた。すると美咲が、「健太はどう思う？」と尋ねた。急に名前を呼ばれ、健太は一瞬答えに詰まった。「別に、いいと思う」と言いかけたが、美咲は急がせず、机の上の資料を見ながら待っていた。その様子を見て、健太は、思いついていたことを少しだけ話してみることにした。\n\n「説明を短くするのはいいけど、初めて見る人には、どうしてこの展示を作ったのか分からなくならないかな。」\n\n言い終えた瞬間、健太は余計なことを言ったかもしれないと思った。しかし、班の一人が「確かに、理由がないと写真だけ見て終わるかも」と言い、別の一人も資料を読み返した。美咲は「じゃあ、長い説明を残すんじゃなくて、最初に一文だけ目的を書いたらどうかな」と提案した。話し合いは少し長くなったが、さっきまでより多くの意見が出た。\n\n帰り道、健太は美咲に「さっき、聞いてくれて助かった」と言った。美咲は首をかしげ、「私は聞いただけだよ」と笑った。その言葉を聞いて、健太は考えた。相談するとは、答えを教えてもらうことだけではない。自分でもまだ形にできていない考えを、相手に受け止めてもらいながら確かめていくことも、相談なのかもしれない。\n\n翌日、別の係の生徒が展示場所について困っているのを見たとき、健太はすぐに解決策を言おうとはしなかった。まず「どこで困っているの？」と尋ね、相手の話を最後まで聞いた。前日の美咲のようにできたかどうかは分からない。それでも、相手が話し終えたあと、「話したら少し整理できた」と言ったのを聞き、健太は昨日の出来事の意味をもう一度理解した。","questions":[{"skill":"心情","q":"健太が最初、自分の案を言い出せなかった理由を説明しなさい。","answer":"自分の考えを話すと話し合いが長引き、決まりかけていることを変えてしまうかもしれないと考えたから。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 行動・表情・発言を探し、そこから読み取れる気持ちと本文に明記された事実を分ける。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"きっかけ","q":"健太が自分の考えを話してみようと思った直接のきっかけは何ですか。","answer":"美咲が健太の考えを尋ね、答えを急がせずに待ってくれたこと。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 行動や考えが変わる直前の出来事を探し、背景の事情と直接のきっかけを区別する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"心情変化","q":"健太の「相談すること」への考えは、出来事を通してどのように変化しましたか。","answer":"答えを教えてもらうことだけでなく、相手に受け止めてもらいながら自分の考えを確かめることも相談だと考えるようになった。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 変化前の心情、転機となる出来事、変化後の心情を順に抜き出す。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"記述","q":"翌日、健太が困っている生徒にすぐ解決策を言わず、まず話を聞いた理由を説明しなさい。","answer":"美咲に話を聞いてもらった経験から、相手の考えを整理するには、すぐ答えを示すより先に話を受け止めることが大切だと気づいたから。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 設問が要求する要素を二つ以内に分解し、それぞれの根拠がある段落を確認する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]}]},{"id":"b2","genre":"説明文","title":"便利さと選ぶ力","level":"標準","passage":"私たちは、便利な道具を使うことで、多くの時間を節約している。地図を見なくても目的地まで案内してもらえ、調べたい言葉を入力すれば、必要そうな情報がすぐに並ぶ。便利さは、できなかったことをできるようにするだけでなく、迷ったり考えたりする時間まで短くしてくれる。\n\nしかし、時間が短くなることと、考える必要がなくなることは同じではない。たとえば、検索結果の一番上に表示された説明が、自分の知りたいことに本当に合っているとは限らない。道案内が示した道も、工事や混雑の状況によっては最もよい道ではないことがある。道具が示す答えは、私たちの代わりに最終的な判断までしてくれるものではない。\n\n便利な道具が増えるほど、私たちは「選ぶ」という仕事から解放されるように感じる。けれども実際には、選択肢が見えにくくなっているだけの場合がある。自動的に示された一つの答えをそのまま受け入れると、ほかの可能性を検討したことさえ意識しなくなるからだ。\n\nここで大切なのは、便利な道具を使わないことではない。むしろ、道具に任せる部分と、自分で確かめる部分を区別することである。計算そのものは機械に任せても、どの数値を使うかは人が考える。目的地までの経路は案内してもらっても、その道を選ぶ理由は自分で判断する。情報を探す時間を短くできたなら、そこで生まれた時間を、複数の情報を比べるために使うこともできる。\n\n便利さとは、考えることをなくす力ではなく、考える場所を変える力だと言える。道具が多くの作業を引き受ける時代だからこそ、私たちは「何を任せ、何を自分で決めるのか」を意識する必要がある。その区別ができたとき、便利さは初めて、自分で選ぶ力を弱めるものではなく、その力を支えるものになる。","questions":[{"skill":"接続関係","q":"第二段落の「しかし」は、どのような内容の対比を示していますか。","answer":"便利な道具は考える時間を短くする一方で、最終的な判断まで不要にするわけではないという対比。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 接続語の直前と直後の内容を短く言い換え、逆接・順接・補足などの関係を特定する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"具体と抽象","q":"検索結果や道案内の例は、どのようなことを説明するために挙げられていますか。","answer":"道具が示した答えが、目的や状況に照らして最もよいとは限らず、人が確かめて判断する必要があること。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 具体例をそれぞれ短く言い換え、共通して説明している考えを探す。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"選択肢照合","q":"「便利な道具が増えれば、人は何も選ばなくてよくなる」という説明が本文と合わない理由を書きなさい。","answer":"道具は作業を助けても、何を任せ何を自分で決めるかという選択や判断は人に残ると述べているから。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 選択肢の主語・条件・程度・因果を分解し、本文と一致しない部分を特定する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"要約","q":"筆者の主張を、道具に任せることと自分で判断することの関係が分かるように要約しなさい。","answer":"便利な道具には作業を任せつつ、目的に合うかを自分で確かめて判断することで、便利さを選ぶ力の支えにできる。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 繰り返される中心語と筆者の結論を探し、例示と主張を分ける。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]}]},{"id":"b3","genre":"物語","title":"役割を任せる","level":"発展","passage":"学級新聞の編集係になった直人は、最初の打ち合わせからほとんど一人で仕事を進めていた。記事の配置を考えるのも、見出しを決めるのも、写真を選ぶのも、自分でやった方が早いと思っていたからだ。ほかの係に頼めば説明する時間がかかるし、思った通りにならなければ直す必要もある。締め切りを考えると、自分で済ませるのが一番確実に見えた。\n\nところが、発行日の一週間前になって、予定していた記事が一つ届かないことが分かった。直人は空いた場所を埋めるため、新しい記事を書こうとした。しかし、その日は委員会もあり、写真の整理も残っていた。机の上に仕事を並べていると、同じ編集係の沙耶が「見出しなら私が考えようか」と声をかけた。\n\n直人は反射的に「大丈夫」と答えた。けれども、沙耶は帰らず、「全部を一人でやるのが係の仕事なの？」と聞いた。その言葉に、直人は手を止めた。自分は責任を果たそうとしているつもりだった。しかし、いつの間にか、ほかの人が仕事に関わる機会までなくしていたのかもしれない。\n\n直人は迷った末、写真選びを沙耶に任せた。条件だけを説明し、どの写真にするかは任せることにした。翌日、沙耶が選んだ写真を見ると、直人なら選ばなかった一枚が入っていた。最初は替えようと思ったが、その写真には記事を書いた生徒だけでなく、準備をしている周囲の生徒も写っていた。「記事の内容だけじゃなくて、みんなで作った感じが出ると思って」と沙耶は言った。\n\n完成した新聞を見た直人は、自分一人で作ったときよりも、紙面にいろいろな視点が入っていることに気づいた。任せるとは、自分の仕事を減らすためだけの方法ではない。相手が考え、工夫する余地を渡すことでもあるのだ。\n\n次の号の打ち合わせで、直人は最初に仕事を分けた。ただし、何もかも任せきりにはしなかった。締め切りや目的は全員で確認し、途中で一度見せ合うことにした。以前の直人なら、それを「自分でやった方が早い」と感じただろう。今は、少し時間がかかっても、複数の人が関わることで生まれるものがあると知っている。","questions":[{"skill":"会話文","q":"直人が最初、編集の仕事をほとんど一人で進めていたのはなぜですか。","answer":"人に説明したり直したりするより自分で進める方が早く、締め切りにも確実に間に合うと考えていたから。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 発言者と聞き手を確認し、発言前後の行動・反応を照合する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"人物像","q":"直人が仕事の進め方を見直すきっかけとなった沙耶の言葉を書き抜きなさい。","answer":"全部を一人でやるのが係の仕事なの？","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 異なる場面での行動・発言を二つ探し、共通する人物の特徴を考える。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"文章全体","q":"沙耶が選んだ写真を見て、直人はどのようなことに気づきましたか。","answer":"自分とは異なる視点を取り入れることで、記事を書いた人だけでなく準備に関わった人たちも伝えられると気づいた。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 冒頭の問題提起と結末の結論を比べ、途中の具体例が果たす役割を確認する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"記述","q":"次の号で直人が仕事を分けつつ締め切りや目的を全員で確認したのはなぜですか。","answer":"任せることで相手の工夫を生かしながらも、目的や進み具合を共有して係全体で責任を持つため。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 設問が要求する要素を二つ以内に分解し、それぞれの根拠がある段落を確認する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]}]},{"id":"b4","genre":"説明文","title":"失敗を記録する意味","level":"標準","passage":"失敗したとき、多くの人はできるだけ早く忘れたいと考える。間違えた答えやうまくいかなかった方法を見ると、自分の不得意な部分を見せられているようで、気分がよくないからだ。そのため、正しい答えだけを書き直し、失敗した跡を消してしまうこともある。\n\nしかし、学習という点から見ると、失敗には成功とは違う情報が含まれている。正解したという事実から分かるのは、そのときその問題を解けたということである。一方、失敗を詳しく見ると、どの段階で判断を誤ったのか、何を知っていて何を知らなかったのか、どの考え方を別の場面にも使ってしまったのかが分かる。\n\nたとえば計算問題で符号を間違えたとする。「不注意だった」とだけ記録すれば、それ以上のことは分からない。だが、途中式を残しておけば、負の数を引くところで間違えたのか、移項したときに符号を変え忘れたのかを区別できる。二つの間違いは結果だけ見れば同じ不正解でも、次に練習すべき内容は異なる。\n\n記録することには、もう一つ意味がある。人は、自分の失敗の傾向を正確には覚えていない。何度も同じ種類の間違いをしていても、その都度「たまたま」と考えてしまうことがある。記録を並べれば、同じところでつまずいていることが目に見える。すると、問題数を増やす前に、必要な考え方だけを練習するという選択ができる。\n\nもちろん、失敗を細かく記録すること自体が目的になってはいけない。記録に時間をかけすぎれば、学習する時間が減ってしまう。大切なのは、「何を間違えたか」「なぜ間違えたか」「次に何をするか」という三点が分かる程度に残すことである。\n\n失敗の記録は、過去の間違いを保存するためのものではない。次に同じ場面に出会ったとき、別の行動を選べるようにするためのものである。そう考えると、失敗は消すべき跡ではなく、次の学習の方向を示す印になる。","questions":[{"skill":"接続関係","q":"第二段落の「しかし」は、どのような考えの転換を示していますか。","answer":"失敗を早く忘れたいという考えから、失敗には次の学習に役立つ情報があるという考えへの転換。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 接続語の直前と直後の内容を短く言い換え、逆接・順接・補足などの関係を特定する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"具体と抽象","q":"計算問題の符号の間違いの例は、何を説明するために挙げられていますか。","answer":"同じ不正解でも間違えた箇所や原因が違えば、次に練習すべき内容が異なること。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 具体例をそれぞれ短く言い換え、共通して説明している考えを探す。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"要約","q":"筆者が考える「失敗を記録する意味」を、次の行動との関係が分かるように説明しなさい。","answer":"間違いの原因や繰り返す傾向を確かめ、次に必要な練習や行動を選べるようにすること。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 繰り返される中心語と筆者の結論を探し、例示と主張を分ける。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"選択肢照合","q":"失敗を詳しく記録しさえすればよい、という考えが本文と合わない理由を書きなさい。","answer":"記録そのものが目的ではなく、学習時間との釣り合いを考えて原因と次の行動が分かる程度に残すことが大切だから。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 選択肢の主語・条件・程度・因果を分解し、本文と一致しない部分を特定する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]}]},{"id":"b5","genre":"物語","title":"言わなかった理由","level":"発展","passage":"昼休み、図書委員の仕事を終えた彩は、返却された本を棚に戻していた。入口の近くでは、一年生らしい生徒が何度も同じ棚の前を行き来している。何かを探しているようだったが、彩は声をかけなかった。困っているなら、そのうち受付に聞くだろうと思ったからだ。\n\nしばらくして、その生徒は一冊の本を手に取った。しかし、表紙を見たあと、また棚に戻した。彩には、その本が探しているものではないことが分かった。声をかけようとして、一歩近づいたが、ちょうど友人に呼ばれ、そのまま別の作業へ移った。\n\n放課後、彩が貸出記録を整理していると、昼休みの生徒が受付に来た。「地域の昔の写真が載っている本を探しているんです」と言う。総合学習で使うらしい。彩はすぐに資料の場所を思い出し、郷土資料の棚へ案内した。生徒は本を見つけると、ほっとしたように何度も礼を言った。\n\nその帰り、彩は昼休みの自分の行動を思い返した。場所を知っていたのだから、あのとき声をかければよかった。しかし同時に、知らない上級生から突然話しかけられることを嫌がる人もいるかもしれない、と考えていたことも思い出した。だから声をかけなかったのは、単に面倒だったからではない。\n\n翌日の昼休み、別の生徒が検索用の端末の前で立ち止まっていた。彩はすぐに使い方を説明するのではなく、「何か探していますか」とだけ尋ねた。相手は「大丈夫です」と答え、自分で操作を続けた。彩はそれ以上言わずに離れた。\n\n少しして、その生徒が「やっぱり一つだけ聞いてもいいですか」と声をかけてきた。彩は必要な操作だけを説明した。昨日までの彩なら、声をかけるか、何もしないかの二つしか考えていなかった。しかし、相手が助けを必要としているか確かめ、その答えに合わせて関わり方を変えることもできる。\n\n彩は、昼休みに言わなかった言葉を後悔したからこそ、次の日には別の声のかけ方を選べたのだと思った。何も言わなかったという出来事も、その理由を考え直せば、次の行動を変える材料になる。","questions":[{"skill":"心情","q":"彩が昼休みに困っていそうな生徒へ声をかけなかった理由を二つ説明しなさい。","answer":"困っていれば受付に聞くだろうと考えたことと、知らない上級生に突然話しかけられるのを嫌がる人もいると思ったこと。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 行動・表情・発言を探し、そこから読み取れる気持ちと本文に明記された事実を分ける。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"会話文","q":"彩が翌日、端末の前の生徒に最初にかけた言葉を書き抜きなさい。","answer":"何か探していますか","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 発言者と聞き手を確認し、発言前後の行動・反応を照合する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"心情変化","q":"彩の「困っている人への関わり方」は、前日と翌日でどのように変化しましたか。","answer":"声をかけるか何もしないかの二択ではなく、まず相手の必要を確かめ、返答に合わせて助け方を変えるようになった。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 変化前の心情、転機となる出来事、変化後の心情を順に抜き出す。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"記述","q":"題名「言わなかった理由」と結末の関係を説明しなさい。","answer":"彩が声をかけなかった理由を振り返ったことで、相手の気持ちを考えながら声のかけ方を選ぶという次の行動につながったことを表す。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 設問が要求する要素を二つ以内に分解し、それぞれの根拠がある段落を確認する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]}]},{"id":"b6","genre":"説明文","title":"分かりやすさの落とし穴","level":"発展","passage":"説明は、分かりやすいほどよい。そう言われると、多くの人が賛成するだろう。難しい言葉をやさしい言葉に置き換え、長い文章を短くし、図や例を使えば、読む人の負担は小さくなる。学校の授業でも、説明書でも、分かりやすさは大切な目標である。\n\nところが、分かりやすさを求めるあまり、大切な違いまで消してしまうことがある。たとえば、二つの考え方に共通点が多いからといって「ほとんど同じ」と説明すると、実際には重要な条件が異なるかもしれない。また、複雑な出来事を一つの原因だけで説明すれば覚えやすくなるが、本当は複数の原因が関係していることもある。\n\n分かりやすい説明が危険なのではない。問題は、分かりやすくする過程で何を省いたのかが見えなくなることである。説明する人は、相手に伝えるために情報を選ぶ。つまり、説明とは情報をそのまま渡す作業ではなく、必要だと判断した部分を残し、それ以外をいったん脇に置く作業でもある。\n\nだから、説明を受け取る側にも役割がある。最初は単純な説明で全体像をつかみ、そのあとで「例外はないか」「どんな条件なら成り立たないか」と問い直すのである。これは、最初の説明を疑って捨てるという意味ではない。説明を出発点として、少しずつ細部を戻していくということだ。\n\n地図を考えると分かりやすい。駅までの道を知りたい人に、町にあるすべての建物や細い道を示す必要はない。必要な情報だけを残した地図の方が役に立つ。しかし、その地図だけを見て町のすべてを知ったと思えば間違える。目的が変われば、必要な情報も変わるからである。\n\nよい説明とは、あらゆる情報を詰め込んだ説明ではない。同時に、ただ短く単純な説明でもない。何を理解するための説明なのかが明確で、その目的に必要な情報が選ばれている説明である。そして受け取る側は、分かりやすさをゴールにせず、必要に応じて省かれた部分を確かめる。その往復があって初めて、分かりやすさは理解の入口として働く。","questions":[{"skill":"接続関係","q":"第二段落の「ところが」は、前の段落に対してどのような内容を示していますか。","answer":"説明を分かりやすくすることの利点に対し、単純化しすぎると重要な違いや条件を失う危険を示している。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 接続語の直前と直後の内容を短く言い換え、逆接・順接・補足などの関係を特定する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"具体と抽象","q":"地図の例は、説明についてどのようなことを示すために使われていますか。","answer":"目的に応じて情報を省くことは役立つが、省いた情報まで含めてすべて理解したと思ってはいけないこと。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 具体例をそれぞれ短く言い換え、共通して説明している考えを探す。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"要約","q":"筆者が考える「よい説明」の条件を一文でまとめなさい。","answer":"何を理解するための説明かが明確で、その目的に必要な情報が適切に選ばれていること。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 繰り返される中心語と筆者の結論を探し、例示と主張を分ける。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]},{"skill":"記述","q":"分かりやすい説明を受け取った側が、そのあとにすべきことを本文に即して説明しなさい。","answer":"まず単純な説明で全体像をつかみ、その後で例外や成り立たない条件など、省かれた情報を必要に応じて確かめること。","guide":["① 設問を読み、何を答えるか（理由・内容・変化・主張など）に印をつける。","② 設問が要求する要素を二つ以内に分解し、それぞれの根拠がある段落を確認する。","③ 設問で求められた要素に対応する本文の言葉を確認する。","④ 根拠にない推測を足さず、求められた形で答えをまとめる。"]}]},{"title":"物語「一度止めた時計」","genre":"物語文","level":"長文・入試接続","passage":"理科室の壁には、古い丸時計が掛かっていた。電池を替えても一日に数分ずつ遅れるため、授業で使われることはない。それでも誰も外そうとはせず、針は毎日少しずつ正しい時刻から離れていった。\n\n科学部の悠人は、その時計が気になっていた。文化祭で部の活動を紹介することになり、展示物を探していたからだ。「直して展示したら面白いんじゃない？」と一年生の真帆が言った。悠人も最初はそう思った。壊れた時計を自分たちで直せば、科学部らしい展示になる。\n\n二人は時計を外し、裏ぶたを開けた。歯車のような複雑な仕組みを想像していたが、中にあったのは小さな機械だった。悠人は少し拍子抜けした。それでも原因を調べようと、電池を替え、針の動きを記録した。翌日には三分、二日後には六分遅れていた。\n\n「部品を交換すればいいのかな。」\n真帆が言ったが、悠人は返事をしなかった。交換すれば時計は動くだろう。しかし、それでは自分たちが何を調べたことになるのか分からない気がした。\n\n顧問の先生に相談すると、「直すことが目的なの？」とだけ聞かれた。悠人はすぐに答えられなかった。文化祭の展示なのだから、直った時計を見せる方がよいと思っていた。けれども、先生の問いを聞いてから、それまで取った記録をもう一度見直した。\n\n記録には、遅れた分数だけでなく、室温や電池の種類、時計を置いた場所まで書いてあった。真帆が「せっかくだから」と書き加えていたものだ。比べてみると、条件を変えても遅れ方はほとんど同じだった。原因はまだ分からない。だが、「何を変えても同じように遅れた」ということも一つの結果だった。\n\n悠人は展示の計画を書き直した。完成した時計を見せるのではなく、調べた方法と記録を並べ、最後に「原因はまだ分かっていない」と書くことにした。真帆はその案を見て、「直ってないものを展示するの？」と笑ったが、すぐに「でも、こっちの方が私たちがやったことは分かるね」と言った。\n\n文化祭の日、展示を見た小学生が「結局、どうして遅れるの？」と尋ねた。悠人は一瞬困ったが、「まだ分からないんだ」と答えた。そして、これまで試したことを説明した。小学生は時計を見上げ、「じゃあ、次は何を試すの？」と聞いた。\n\nその質問を聞いたとき、悠人は不思議にうれしくなった。以前なら、答えが出ていないことを失敗だと感じただろう。しかし今は、分からないことが残っているからこそ、次に確かめることが生まれるのだと思えた。\n\n文化祭が終わったあと、時計は再び理科室の壁に戻された。ただし、今度は針を止めたままにした。時計の下には、悠人たちが作った小さな記録表が置かれている。止まった時計を見るたびに、悠人は、答えを出すことだけが調べることではない、と考えるようになった。","questions":[{"skill":"心情変化","q":"悠人の「答えが出ていないこと」に対する考えは、文化祭までにどのように変化しましたか。60字以内で書きなさい。","answer":"答えが出ないことを失敗だと感じていたが、分からないことが次に確かめることを生むと考えるようになった。","guide":["① 「以前なら、答えが出ていないことを」の段落と最後の段落を探す。","② 【変化前】【きっかけ】【変化後】に分ける。","③ 先生と小学生の問いがどう働いたか整理する。","④ 前後の考えを一文につなぐ。"]},{"skill":"きっかけ","q":"悠人が展示計画を書き直す直接のきっかけとなったものを説明しなさい。","answer":"顧問に「直すことが目的なの？」と問われ、これまでの記録を見直したこと。","guide":["① 顧問の先生の質問から「展示の計画を書き直した」までを読む。","② 出来事と、その後の行動を分ける。","③ 何が記録の見方を変えたか確認する。","④ 人物＋出来事で答える。"]},{"skill":"文章全体","q":"題名「一度止めた時計」は、文章全体の内容とどのように関係していますか。70字以内で説明しなさい。","answer":"時計を直すことより調べる過程に意味を見いだした悠人の変化を、最後に時計をあえて止めて戻す行動が象徴している。","guide":["① 冒頭の展示目的と、最後に時計を戻す場面を比べる。","② 時計の状態と悠人の考えを分ける。","③ 最初の目的と最後の行動を対比する。","④ 「時計」と「悠人の変化」を両方入れる。"]},{"skill":"要約","q":"この物語を、悠人の考えの変化を中心に80字以内でまとめなさい。","answer":"悠人は壊れた時計を直すことを目標に調査を始めたが、記録や周囲の問いを通して、答えが出なくても調べる過程と次の問いに意味があると気づいた。","guide":["① 時計を直そうとした場面、先生の質問、文化祭後の考えを順に探す。","② 作業の細部は削る。","③ 三つを時間順につなぐ。","④ 主語を悠人にそろえる。"]}],"id":"b7"},{"title":"説明文「比べることで見えるもの」","genre":"説明文","level":"長文・入試接続","passage":"一つのものを詳しく観察すれば、そのものについてよく分かる。これは当然のように思える。しかし、ある特徴が本当にそのもの特有のものなのかを知るためには、一つだけを見ていても十分ではない。別のものと比べることで、初めて見えてくる特徴があるからだ。\n\nたとえば、毎日通っている道について考えてみよう。いつも同じ道を歩いていると、その道の坂の多さや道幅を特別なものとは感じない。ところが、別の町を歩いたあとで戻ってくると、「この道は曲がり角が多い」「店が道路の近くに並んでいる」といった特徴に気づくことがある。道そのものが変化したのではない。比較する相手ができたことで、以前からあった特徴が目に入るようになったのである。\n\n比較には、違いを見つける働きだけがあるわけではない。一見まったく異なるものの共通点を見つけることもできる。鳥の翼と魚のひれは形も使われる場所も異なるが、どちらも生き物が移動するときに使うという点では共通している。共通点に注目すると、表面的な形ではなく、働きという別の観点からものを見ることができる。\n\nただし、比較すれば必ず正しい理解に近づくわけではない。何を基準に比べるかによって、見えるものが変わるからである。二つの学校を生徒数だけで比べれば規模の違いは分かるが、授業の特色までは分からない。図書館を蔵書数だけで比べれば本の多さは分かっても、利用しやすさを判断することはできない。\n\nつまり、比較するときには「何が違うか」だけでなく、「何について比べているのか」を意識する必要がある。基準を変えれば、同じ二つのものから別の関係が見えてくる。\n\nさらに、比較は自分自身を理解するときにも役立つ。ただし、他人より優れているか劣っているかを決めるための比較ではない。以前の自分と現在の自分を比べれば、変化した点に気づける。自分と異なる考え方をする人の意見と比べれば、自分が当然だと思っていた前提に気づくこともある。\n\n私たちは「よく見る」というと、一つの対象に長く注意を向けることを想像しやすい。しかし、ときには視線をいったん別の対象へ移し、そこから戻ってくる方がよく見えることがある。比較とは、対象から目をそらすことではない。別のものとの関係を利用して、対象を新しい角度から見直す方法なのである。","questions":[{"skill":"具体と抽象","q":"筆者は「毎日通っている道」の例を何を説明するために挙げていますか。50字以内で書きなさい。","answer":"比較する相手ができることで、それまで気づかなかった対象の特徴が見えるようになること。","guide":["① 「たとえば、毎日通っている道」の前後の段落を読む。","② 道の話と一般的な説明を分ける。","③ 例に共通する考えへ一段抽象化する。","④ 「比較すると～」の形にする。"]},{"skill":"接続関係","q":"「ただし」以降で、筆者はそれまでの説明にどのような制限を加えていますか。","answer":"比較するだけで正しく理解できるのではなく、比較する基準によって見えるものが変わるという制限。","guide":["① 「ただし、比較すれば」の前後を読む。","② 前＝比較の働き、後＝注意点に分類する。","③ 後で否定されている考えを確認する。","④ 「～だけではなく」の形で整理する。"]},{"skill":"文章全体","q":"筆者が述べる「比較」の働きを二つ挙げ、それぞれ簡潔に説明しなさい。","answer":"違いや共通点を通して対象の特徴を見つける働きと、別の観点から対象や自分自身を見直す働き。","guide":["① 「違い」「共通点」「自分自身」という三つの記述を探す。","② 似た内容をまとめる。","③ 具体例は除き、働きだけ残す。","④ 二つが重ならないようにする。"]},{"skill":"要約","q":"本文全体を90字以内で要約しなさい。","answer":"比較は違いや共通点から対象の特徴を見つける方法だが、基準によって見え方が変わるため観点を意識する必要があり、対象や自分を新しい角度から見直すことにも役立つ。","guide":["① 最初の二段落、比較の基準を述べた段落、最終段落を読む。","② 具体例を削る。","③ 「比較の働き→注意→結論」の順にする。","④ 同じ意味の表現を一つにまとめる。"]}],"id":"b8"},{"title":"物語「同じ場所から見る」","genre":"物語文","level":"長文・入試接続","passage":"写真部の校内展に出す作品を決める日、結衣は一枚の写真を机の中央に置いた。夕方の校庭を写した写真だった。手前には使われていないサッカーゴールがあり、その向こうを数人の生徒が歩いている。空は明るいが、人物の顔はほとんど見えない。\n\n「これを出したい。」\n結衣が言うと、同じ班の拓海は少し首をかしげた。\n「悪くないけど、何を撮りたかったのか分かりにくくない？」\n結衣はすぐには答えなかった。自分でも、撮ったときに何を考えていたのか、うまく言葉にできなかったからだ。\n\nその写真を撮った日は、部活動が休みだった。結衣は忘れ物を取りに学校へ戻り、誰もいないと思っていた校庭で、文化祭の準備を終えた生徒たちが帰っていくのを見た。にぎやかな時間が終わったあとの校庭は、いつもより広く感じられた。結衣はその感じを残したくてシャッターを切った。\n\n拓海は別の写真を示した。昼休みに友達が笑っている場面で、表情がはっきり写っている。「こっちなら、楽しい感じがすぐ伝わる」と言う。結衣にもその良さは分かった。見た人が迷わず意味を受け取れる写真だった。\n\n顧問の先生は二人の話を聞き、「同じ場所を撮った写真を並べてみたら」と提案した。そこで部員たちは、これまで校庭で撮った写真を机に広げた。運動会の日、雨の日、朝練の時間、雪が残った朝。どれも同じ校庭なのに、写っているものも印象も大きく違った。\n\n結衣は、自分の夕方の写真をもう一度見た。すると、最初には気づかなかったことが目に入った。写真の端に、片づけられた長机が少しだけ写っている。その奥には、まだ教室の明かりが一つ残っていた。人がほとんどいないからこそ、少し前までそこに多くの人がいたことが想像できるように思えた。\n\n一方、拓海は運動会の写真を見ながら、「同じ校庭なのに、こっちは狭く見える」と言った。大勢の人が写っているためだった。二人は、場所そのものだけを撮っているのではなく、そのときそこにあった時間まで写真に写り込むのかもしれない、と話した。\n\n展示当日、結衣は夕方の写真一枚だけではなく、朝の校庭を撮った写真と二枚並べて展示した。題名は「同じ場所」にした。説明文は付けなかった。\n\n見に来た生徒の一人が、二枚をしばらく見比べてから、「朝の方が静かなはずなのに、夕方の方が静かに見える」と友達に言った。別の生徒は、「夕方の方は、何かが終わった感じがする」と言った。結衣が撮ったときに感じたことと完全に同じではない。それでも、二枚を比べることで、見る人がそれぞれ何かを考えていることがうれしかった。\n\n展示が終わったあと、拓海は「最初は分かりにくいと思ったけど、分からない部分があるから見るのかもね」と言った。結衣は笑って、「全部分からないのも困るけどね」と答えた。\n\n帰りに二人で校庭を通ると、サッカー部が練習をしていた。ボールを追う声が響き、夕方の校庭はあの日とはまるで違って見えた。結衣はカメラを取り出しかけて、やめた。今は撮らずに見ておこうと思った。同じ場所でも、いつも同じものが見えるわけではない。そして、写真にすることで見えるものもあれば、写真にしないからこそ覚えていられるものもあるような気がした。","questions":[{"skill":"心情","q":"結衣が、展示を見た生徒たちの感想を聞いて「うれしかった」のはなぜですか。60字以内で書きなさい。","answer":"自分と同じ感じ方でなくても、二枚の写真を比べた人がそれぞれ写真から意味を考えてくれたから。","guide":["① 展示で感想を述べる生徒の場面と「それでも」の後を読む。","② 生徒の反応と結衣の評価を分ける。","③ 「完全に同じではない。それでも」に注目する。","④ 原因→心情の順でまとめる。"]},{"skill":"心情変化","q":"拓海の結衣の写真に対する見方は、初めと展示後でどう変化しましたか。70字以内で書きなさい。","answer":"初めは何を撮りたいのか分かりにくい写真だと考えたが、展示後には分からない部分が見る人に考えさせる働きを持つと捉えるようになった。","guide":["① 冒頭の拓海の発言と展示後の拓海の発言を比べる。","② 初め／途中／最後に分ける。","③ 何を価値として認めたか整理する。","④ 対比の形で一文にする。"]},{"skill":"表現効果","q":"最後に結衣が「カメラを取り出しかけて、やめた」とあることには、どのような効果がありますか。","answer":"写真に残すことだけでなく、撮らずにその場を見て覚えておくことにも意味があると気づいた結衣の変化を、行動で示している。","guide":["① 結末の「カメラを取り出しかけて、やめた」の直後を読む。","② 最後の行動を事実として整理する。","③ 直後の考えと結び付ける。","④ 行動が示す人物の変化を書く。"]},{"skill":"要約","q":"この物語を、結衣と拓海の写真に対する考えの変化を中心に100字以内でまとめなさい。","answer":"分かりやすい写真をよいと考える拓海と、言葉にできない感覚を写した結衣は、同じ場所の写真を比べて展示する経験から、写真には見る人が考える余地や、時間の違いを見せる働きもあると気づいた。","guide":["① 二人の写真の選び方、並べて展示した理由、展示後の発言を探す。","② 写真を並べたことを転換点にする。","③ 展示後の気づきをまとめる。","④ 細かな出来事は削る。"]}],"id":"b9"},{"title":"説明文「余白は何もしない場所か」","genre":"説明文","level":"長文・入試接続","passage":"ノートを書くとき、紙いっぱいに文字が並んでいると、多くの情報が入っているように見える。反対に、何も書かれていない部分が多いと、紙を十分に使っていないように感じる人もいるだろう。しかし、情報を伝えるという点では、空いている場所が必ずしも無駄とは限らない。\n\n文章の見出しの周りに少し空間があると、そこが一つのまとまりの始まりだと分かりやすい。図と説明文の間に適度な間隔があれば、どの説明がどの図に対応しているのか判断しやすくなる。何もない部分は、それ自体が情報を持っていないように見えるが、実際には、情報同士の関係を見せる役割を果たしている。\n\n音楽でも似たことが言える。音が途切れる時間は、単に音楽が存在しない時間ではない。短い休止があることで、その前の音が強く感じられたり、次の音を待つ感覚が生まれたりする。会話でも、相手が話し終える前にすぐ言葉を重ねるのと、少し間を置いてから答えるのとでは、同じ言葉でも受け取られ方が違う。\n\nこのように考えると、「何もない」という状態を、単純に「役割がない」と判断することはできない。周囲に何があるかによって、空白や沈黙の意味は変わるからだ。\n\nただし、余白を増やせば増やすほど分かりやすくなるわけではない。教科書の一ページに一文しか書かれていなければ、ページをめくる回数が増え、かえって内容のつながりを追いにくくなる。会話で長い沈黙が続けば、相手は返事がないと感じるかもしれない。余白や間は、情報との関係の中で働くのであって、それだけを取り出して価値を決めることはできない。\n\n大切なのは、情報を増やすことと、伝わる情報を増やすことを区別することである。文字を一つ増やせば、紙の上の情報量は確かに増える。しかし、その文字のために重要な部分が見つけにくくなれば、読む人が受け取れる情報はかえって減ることもある。\n\nこれは、勉強するときのノートにも当てはまる。先生が言ったことを一字一句書こうとすると、書くことに集中して説明の関係を考える余裕がなくなる場合がある。一方、重要な語句の周りを空けておけば、あとから理由や例を書き足すことができる。余白は、今ある情報を整理する場所であると同時に、あとから考えを加えるための場所にもなる。\n\n私たちは、目に見えるものだけを「ある」と考えがちである。しかし、情報の世界では、置かれなかったものや、あえて空けられた場所も全体の意味に関わっている。余白を見るとは、何もないところを眺めることではない。そこを空けることで、周囲の情報がどのように見えるようになったかを考えることなのである。","questions":[{"skill":"具体と抽象","q":"筆者が音楽や会話の例を挙げているのは、どのようなことを説明するためですか。60字以内で書きなさい。","answer":"何もないように見える休止や沈黙も、周囲との関係によって前後の情報の受け取られ方を変える役割を持つこと。","guide":["① 「音楽でも似たことが言える」から次の段落までを読む。","② 個別の例と一般的な主張を分ける。","③ 「何もない」のに何が起こるか整理する。","④ 二つの例に共通する形で答える。"]},{"skill":"接続関係","q":"「ただし」の段落は、それ以前の主張にどのような注意を加えていますか。","answer":"余白や間には役割があるが、多ければよいのではなく、周囲の情報との関係によって適切さが決まるという注意。","guide":["① 「ただし、余白を増やせば」の前後を読む。","② 前の主張と後の制限を分ける。","③ 教科書と沈黙の例の共通点を探す。","④ 「～だが、～ではない」でまとめる。"]},{"skill":"文章全体","q":"本文でいう「情報を増やすこと」と「伝わる情報を増やすこと」の違いを説明しなさい。","answer":"前者は文字などの量そのものを増やすことで、後者は配置や余白も利用して重要な内容や関係を受け取りやすくすることである。","guide":["① 「大切なのは、情報を増やすことと」の段落を読む。","② それぞれの意味を別々に書く。","③ ノートの例で確かめる。","④ 「前者／後者」で対比する。"]},{"skill":"要約","q":"筆者の主張を100字以内で要約しなさい。","answer":"余白や沈黙は単なる無ではなく、周囲との関係によって情報を整理し受け取り方を変える働きを持つ。ただし多ければよいのではなく、伝える目的に応じて情報とのバランスを考える必要がある。","guide":["① 余白の働き、増やしすぎた場合、最後の結論を探す。","② 音楽やノートなどの例は削る。","③ 余白の役割と条件を残す。","④ 最後に筆者の結論を置く。"]}],"id":"b10"},{"title":"物語「返さなかったノート」","genre":"物語文","level":"長文・入試実戦","passage":"卒業まであと二か月になったころ、真琴は図書室の返却台で一冊のノートを見つけた。学校の備品ではない。紺色の表紙に、小さく「記録」とだけ書かれている。落とし物だと思い、職員室へ届けようとして表紙を開くと、最初のページに「放送委員会」とあった。\n\n真琴も放送委員だった。ノートには、昼の放送で起きた失敗や、そのときどう対応したかが、日付順に細かく書かれていた。「音楽が流れない。コードを確認」「原稿が一枚足りない。前の話題を長くして時間をつなぐ」。筆跡は一人分ではなく、何人もの先輩が書き足してきたものらしい。\n\n真琴はその日の委員会でノートを見せた。担当の先生は懐かしそうに、「まだ残っていたんだ」と言った。以前は放送室に置かれ、失敗したことを次の人に伝えるために使われていたが、数年前から誰も書かなくなったという。\n\n「もう捨ててもいいですか。」\n委員長の圭介が尋ねた。今は機械の操作方法も新しくなり、昔の記録がそのまま役立つことは少ない。先生は「みんなで決めていいよ」と答えた。\n\n真琴も最初は、残しておく必要はないと思った。ところが家に帰ってから、なぜかノートの一文を思い出した。「失敗した人を責める前に、次の人が同じ失敗をしない方法を書く。」短い一文だった。\n\n翌日、真琴は放送室でノートを読み直した。あるページには、昼の放送中にマイクを切り忘れ、放送室の会話が校内に流れてしまった失敗が書かれていた。その下に、別の筆跡で「終わったら赤いランプを見る」とある。さらに後のページには、「赤いシールをスイッチの横に貼った」と続いていた。失敗が注意だけで終わらず、仕組みの変更につながっていた。\n\n真琴は、自分たちの委員会でも似たことがあったのを思い出した。先月、担当者が原稿を忘れたとき、みんなで「次から気をつけよう」と言った。しかし、次の週には別の生徒が同じように原稿を忘れた。気をつける人を増やすだけでは、同じことが繰り返される場合がある。\n\n委員会で真琴がその話をすると、圭介は「でも、このノートを残すだけじゃ、また誰も読まなくなるよ」と言った。真琴は言い返そうとして、やめた。確かに、古い記録を大切に保管することと、そこから学ぶことは同じではない。\n\n話し合いの結果、ノートそのものは資料として保管し、現在も使える内容だけを一枚の「放送室チェック表」にまとめることになった。ただし、真琴はチェック表の一番下に小さな欄を作った。「困ったこと／次に変えること」と書く欄である。\n\n数週間後、一年生の担当者が放送開始の時刻を間違えた。その生徒は落ち込んでいたが、真琴は「どうして間違えたの？」とは聞かなかった。代わりに「次に同じことが起きにくくするには、何を変えたらいいと思う？」と尋ねた。二人で考え、放送開始五分前に鳴るタイマーを置くことにした。\n\n卒業前、真琴は最後の委員会を終え、紺色のノートを棚に戻した。最初に見つけたときよりも、ノートは少し重く感じられた。もちろん、本当に重さが変わったわけではない。そこに書かれた失敗の数を重く感じたのでもなかった。一つ一つの失敗のあとに、誰かが次の人のために考えた時間が積み重なっているように思えたのである。\n\n真琴は新しいチェック表をノートの隣に置いた。古いノートをそのまま使い続けることはしなかったが、捨てることもしなかった。残すべきなのは紙そのものではなく、失敗を次の工夫へ変えていく考え方なのだと、今は思っている。","questions":[{"skill":"心情変化","q":"真琴のノートに対する考えは、初めから最後までどのように変化しましたか。80字以内で書きなさい。","answer":"初めは古く実用性が低いので残す必要はないと考えたが、失敗を次の工夫へ変える先輩たちの考えを知り、紙ではなくその考え方を受け継ぐ価値があると考えるようになった。","guide":["① 「残しておく必要はない」と「残すべきなのは」を比べる。","② ノートそのものと、そこにある考え方を分ける。","③ 何をきっかけに評価が変わったか整理する。","④ 変化前→変化後でまとめる。"]},{"skill":"会話文","q":"圭介の「このノートを残すだけじゃ、また誰も読まなくなるよ」という発言には、どのような役割がありますか。","answer":"ノートを保存すること自体を目的にせず、記録を現在の行動や仕組みに生かす必要があると真琴に気づかせる役割。","guide":["① 圭介の発言からチェック表を作る場面までを読む。","② 圭介が否定していることを確認する。","③ その後の話し合いで何が決まったか結ぶ。","④ 発言→気づきの形で答える。"]},{"skill":"表現効果","q":"「ノートは少し重く感じられた」と表現したのはなぜですか。60字以内で説明しなさい。","answer":"ノートの物理的な重さではなく、失敗のあとに次の人のため工夫してきた先輩たちの思いや時間の積み重なりを感じたから。","guide":["① 「ノートは少し重く感じられた」の後の三文を読む。","② 実際の重さと比喩的な重さを分ける。","③ 何が積み重なっているか探す。","④ 「～を感じたから」でまとめる。"]},{"skill":"記述","q":"本文を踏まえ、「失敗を残すこと」の意味を90字以内で説明しなさい。","answer":"失敗そのものを保存して責めたり後悔したりするためではなく、原因や対応を振り返り、同じ失敗を起こしにくくする具体的な工夫へ変え、次の人へ引き継ぐためである。","guide":["① マイクの失敗の記録と新しいチェック表を比べる。","② 「残す目的」と「残した後にすること」を分ける。","③ 本文中の具体例を一般化する。","④ 目的→方法→次への効果で書く。"]},{"skill":"要約","q":"この物語を、真琴の発見と考えの変化を中心に120字以内でまとめなさい。","answer":"放送委員の真琴は古い失敗記録のノートを見つけ、当初は不要だと考える。しかし、先輩たちが失敗を仕組みの改善へつなげていたと知り、保存だけでは不十分だとも気づく。現在用のチェック表を作り、失敗を次の工夫へ変える考え方を受け継ごうとする。","guide":["① ノートを見つけた場面、圭介の発言、最後の行動を探す。","② 細かな失敗例は削る。","③ 真琴を主語に流れをつなぐ。","④ 最後の気づきを必ず残す。"]}],"id":"b11"},{"title":"説明文「速さと理解のあいだ」","genre":"説明文","level":"長文・入試実戦","passage":"文章を速く読めることは、多くの場面で役に立つ。限られた時間で必要な情報を探すとき、すべての文を同じ速さで丁寧に読んでいては間に合わないことがある。見出しを見て必要な部分を選んだり、知っている内容を素早く確認したりする読み方は、日常でも学習でも重要である。\n\nそのため、「読む力」を一分間に読める文字数のような速さで測りたくなる。しかし、読むという行為には、単に文字を目で追う以上のことが含まれている。\n\nたとえば、「植物は光を受けて成長する」という説明を読んだとする。内容をすでに知っている人なら、ほとんど立ち止まらずに理解できるだろう。一方、その説明がそれまでの知識と食い違っていたり、「ただし」という言葉のあとに条件が示されたりすれば、読み手は速度を落として前の文との関係を確かめる必要がある。\n\nつまり、よく読む人がいつも速く読んでいるとは限らない。必要なところで速度を落とせることも、読む力の一部なのである。\n\n道路を運転するときのことを考えると分かりやすい。まっすぐで見通しのよい道と、曲がり角の多い細い道を、同じ速度で走ることが安全だとは言えない。大切なのは最高速度ではなく、状況に合わせて速度を変えられることである。読書でも、文章の難しさや目的によって適切な速さは変わる。\n\nただし、この例から「ゆっくり読めばよく理解できる」と結論づけるのも正しくない。意味のまとまりを無視して一語ずつ確認すると、かえって文全体の関係を見失うことがある。また、すでに理解している説明を必要以上にゆっくり読めば、重要な部分とそうでない部分の区別がつきにくくなる。\n\nでは、読む速さはどのように決めればよいのだろうか。手がかりの一つは、自分が今何を確かめようとしているかを意識することである。資料から日付だけを探すなら、文章全体を精読する必要はない。筆者の主張とその理由を考えるなら、接続語や具体例の位置に注意しながら、段落同士の関係を追う必要がある。物語で人物の心情変化を問われているなら、出来事の前後で人物の言葉や行動がどう変わったかを確かめる。\n\nこのように、読む目的が変われば、注意を向ける場所も速度も変わる。速読と精読は、どちらか一方を選ぶものではない。一つの文章の中でも、速く通る部分と立ち止まる部分を使い分けることができる。\n\nさらに重要なのは、「分からない」と気づけることである。読んでいる最中には、文字を追えているだけで理解した気になることがある。ところが、内容を説明しようとすると言葉にできない。このとき必要なのは、最初から全部を読み直すこととは限らない。どこから分からなくなったのかを探し、その部分の前後に戻ればよい。\n\n読み返すことを、読むのが遅い証拠だと考える必要はない。むしろ、自分の理解が途切れた場所を見つけ、必要な範囲へ戻ることは、読み方を調整しているということである。\n\n文章を読む力とは、ただ速く進む力でも、すべてを慎重に読む力でもない。目的と文章の状態、自分の理解の状態を見ながら、進む、止まる、戻るを選択する力である。速さはその結果として変わる。大切なのは、一定の速さを守ることではなく、理解するために速さを使い分けることなのである。","questions":[{"skill":"具体と抽象","q":"筆者が道路の運転を例に挙げたのは、読むことのどのような特徴を説明するためですか。60字以内で書きなさい。","answer":"読む力では常に速く読むことより、文章の難しさや目的に応じて読む速度を変えることが重要だという特徴。","guide":["① 「道路を運転するとき」から次の段落までを読む。","② 道路と読書で対応するものを探す。","③ 具体例を読書一般の表現へ戻す。","④ 「常に～ではなく、～」でまとめる。"]},{"skill":"接続関係","q":"「ただし、この例から」で始まる段落は、直前までの説明をどのように補っていますか。","answer":"必要なら速度を落とすことが重要だという説明に対し、遅ければ遅いほど理解が深まるわけではないという注意を加えている。","guide":["① 「ただし、この例から」の段落を読む。","② 後で否定される誤解を見つける。","③ 二つの主張が矛盾しない形にする。","④ 「～だが、～ではない」で答える。"]},{"skill":"文章全体","q":"筆者は「読む目的」が読み方にどう関係すると述べていますか。本文中の例を一般化して説明しなさい。","answer":"読む目的によって必要な情報や注目すべき箇所が異なるため、読む場所の選び方や速度、読み返す範囲を目的に応じて調整する必要があると述べている。","guide":["① 日付、筆者の主張、物語の心情を読む三例を探す。","② 三例に共通する関係を探す。","③ 個別の内容は削る。","④ 目的→注目場所→読み方の順で書く。"]},{"skill":"記述","q":"本文でいう「進む、止まる、戻る」とは、それぞれどのような読み方ですか。100字以内で説明しなさい。","answer":"理解済みや目的に不要な部分は速く進み、重要・難解な部分では速度を落として関係を確かめ、理解が途切れたと気づいたときは必要な前後へ読み返すという読み方である。","guide":["① 「進む、止まる、戻る」を述べた結論と前の具体例を対応させる。","② それぞれ「いつ」「何をする」に分ける。","③ 三項目を並列にそろえる。","④ 具体例を使わず一般化する。"]},{"skill":"要約","q":"本文全体を120字以内で要約しなさい。","answer":"読む力は単純な速さでは測れず、遅く読めばよいわけでもない。読む目的や文章の難しさ、自分の理解状態に応じて、必要な箇所を速く読み、重要な所で止まり、分からなくなった所へ戻るなど、速度と読み方を調整することが重要である。","guide":["① 冒頭の速さの利点と、最終段落の「読む力」を比べる。","② 中盤の注意点を一つ残す。","③ 運転などの具体例は削る。","④ 「何ではないか→何が重要か」で構成する。"]}],"id":"b12"},{"title":"物語「先に帰った日」","genre":"物語文","level":"長文・入試実戦","passage":"美術部の片づけが終わるころ、窓の外はすっかり暗くなっていた。文化祭まで三週間。二年生の菜月たちは、廊下に飾る大きな共同作品を作っていた。六人で一枚の絵を仕上げるのは思っていたより難しく、予定より作業が遅れている。\n\nその日、菜月は時計を何度も見ていた。家を出る前、母から「今日は祖母の病院に寄るから、弟の夕飯をお願い」と言われていたからだ。六時には帰るつもりだったが、背景の色を塗り直すことになり、もう五時半を過ぎている。\n\n「菜月、この辺もう一回お願いできる？」\n部長の莉子が筆を渡した。\n菜月は受け取りかけて、「ごめん、今日は先に帰らないと」と言った。\n\n一瞬、部屋が静かになったように感じた。実際には、隣で水を替える音も、紙を切る音も続いていた。それでも菜月には、みんなの手が止まったように思えた。\n\n「そっか。じゃあ、ここは私やるよ。」\n莉子はそれだけ言った。\n\n菜月は急いで道具を洗い、部室を出た。階段を下りながら、胸の奥が落ち着かなかった。誰にも責められてはいない。それなのに、自分だけ仕事を残して帰ることが、共同作品から抜け出すことのように感じられた。\n\n翌日、菜月はいつもより早く部室へ行った。昨日の分まで進めようと思ったのだ。ところが、絵を見ると、菜月が頼まれていた場所はすでに塗り終わっていた。しかも、自分が考えていた色とは少し違う。\n\n「ここ、変えたんだ。」\n思わずそう言うと、莉子が振り向いた。\n「うん。隣の色と合わせたら、この方がいいかなって。」\n菜月は「そうなんだ」と答えたが、すぐには筆を取れなかった。自分がいなかった間にも作品が進み、自分の考えとは違う形になっていたことが、少し寂しかった。\n\nその日の帰り、同じ部員の航が「昨日、菜月が帰ったあと結構大変だったよ」と笑った。菜月はやはり迷惑をかけたのだと思い、「ごめん」と言った。すると航は、「何で謝るの。莉子が色を変えたら、むしろ全体まとまったし」と続けた。\n\n菜月は返事に困った。迷惑をかけたことを否定されたからではない。「自分がいない方がよかった」と言われたように、一瞬だけ聞こえたからだ。しかし航は、そんな菜月の表情に気づかず、「一人抜けても進められるようにしとかないと、共同制作じゃないよな」と言った。\n\nその言葉は、帰宅してからも残った。\n\n次の日、菜月は自分の担当部分について、使う色や考えていることを簡単なメモにして机に置いた。莉子が「今日は帰らなくて大丈夫なの？」と尋ねると、菜月は「大丈夫。でも、誰かが急に帰ることもあるから」と答えた。\n\nそれから部では、作業を始める前に、その日の担当と途中の考えを短く共有するようになった。誰かが休んでも、残った人が続きを判断できる。逆に、本人が戻ってきたときにも、なぜ変更したのかが分かる。\n\n文化祭前日、今度は莉子が体調を崩して休んだ。以前なら、部長がいないことで作業が止まったかもしれない。しかし、その日は莉子が残したメモを見ながら、全員で相談して最後の仕上げを進めた。\n\n完成した作品を廊下に運んだとき、菜月は少し離れた場所から絵を見た。自分が塗った部分を探そうとしたが、すぐには分からなかった。以前なら、それを寂しいと思ったかもしれない。今は、誰がどこを塗ったか分からないほど一枚につながっていることが、共同作品らしく思えた。\n\n文化祭当日、作品の前で莉子が「菜月が先に帰った日から、やり方変わったよね」と言った。菜月は、あの日の居心地の悪さを思い出した。あのときは、自分が最後まで残ることが責任だと思っていた。しかし今は、自分がいなくても続けられるようにしておくことも、誰かと一緒に仕事をする責任なのだと思う。\n\n菜月は絵の中から、自分が最初に塗ろうとしていた場所を見つけた。そこには結局、自分の選んだ色は使われていない。それでも、直したいとは思わなかった。","questions":[{"skill":"心情","q":"菜月が、自分がいない間に塗られた部分を見て「少し寂しかった」のはなぜですか。60字以内で書きなさい。","answer":"自分がいない間にも共同作品が進み、自分が考えていたのとは違う形になって、自分の役割がなくなったように感じたから。","guide":["① 「少し寂しかった」の場面と直前の出来事を読む。","② 起きた事実と菜月の受け止めを分ける。","③ 「自分がいなかった間」「違う形」に注目する。","④ 事実→感じたことの順にまとめる。"]},{"skill":"会話文","q":"航の「一人抜けても進められるようにしとかないと、共同制作じゃないよな」という発言は、菜月にどのような影響を与えましたか。","answer":"一人が最後まで作業することだけを責任と考えていた菜月に、誰かが不在でも続けられるよう情報を共有する必要性を考えさせた。","guide":["① 航の発言と、その後に菜月が取った行動を探す。","② 発言の翌日に菜月がした行動を見る。","③ 発言と行動の因果をつなぐ。","④ 「～と考え、～するようになった」と整理する。"]},{"skill":"心情変化","q":"共同作品に対する菜月の考えは、物語の初めと終わりでどのように変化しましたか。80字以内で書きなさい。","answer":"初めは自分の担当を最後までやり抜くことが責任だと思っていたが、周囲と役割を調整し、皆で完成させることも責任だと考えるようになった。","guide":["① 初めに帰った場面と、完成したときの菜月の考えを比べる。","② 「責任」の意味がどう変わったか探す。","③ 自分の部分へのこだわりの変化も確認する。","④ 前後を対比して書く。"]},{"skill":"表現効果","q":"最後の「それでも、直したいとは思わなかった。」という一文にはどのような効果がありますか。","answer":"自分の考えた色が残ることより、皆で完成させた作品全体を大切にするようになった菜月の変化を、短い行動判断で印象づけている。","guide":["① 最後に「直したい」と思わなかった場面の前後を読む。","② 以前の菜月ならどう感じたか比べる。","③ 最後の判断が示す価値観を考える。","④ 人物の変化＋表現上の効果で答える。"]},{"skill":"要約","q":"この物語を、菜月の「共同制作」への考えの変化を中心に120字以内でまとめなさい。","answer":"共同作品の作業を残して先に帰った菜月は、自分がいない間に作品が進んだことを寂しく感じる。しかし仲間の言葉をきっかけに、情報を共有して誰かが不在でも続けられる仕組みを作り、自分の担当にこだわるより皆で一枚を完成させることが共同制作だと気づく。","guide":["① 帰る場面、航の発言、完成場面を順に探す。","② 色など細部は削る。","③ 菜月の考えの変化を軸にする。","④ 最後の気づきを結論にする。"]}],"id":"b13"},{"title":"説明文「問いを持つということ」","genre":"説明文","level":"長文・入試実戦","passage":"授業で「何か質問はありますか」と聞かれたとき、質問が思い浮かばず、黙ってしまった経験のある人は少なくないだろう。説明がよく分かったから質問がない場合もある。しかし、分からないところはあるのに、何を質問すればよいのか分からないこともある。\n\nこの二つは同じ「質問がない」状態に見えるが、中身は大きく異なる。後者の場合、理解できていないことそのものより、自分がどこまで理解し、どこから理解できていないのかを区別できていないことが問題なのである。\n\n問いは、知らないことから突然生まれるものだと思われがちである。けれども実際には、ある程度知っているからこそ生まれる問いも多い。\n\nたとえば、初めて見る機械を前にして、その仕組みをまったく知らなければ、「どうなっているのだろう」とは思っても、具体的な質問を作るのは難しい。ところが、歯車で力を伝える仕組みを知っていれば、「この機械では、なぜこの大きさの歯車を使うのか」と問うことができる。知識が増えると答えが増えるだけでなく、以前は見えなかった疑問も見えるようになる。\n\n地図についても同じである。何も知らない土地の地図を見ても、地名を眺めるだけで終わるかもしれない。しかし、その地域に大きな川が流れていることを知っていれば、「なぜ町は川のこちら側に集中しているのか」と考えられる。産業について学んでいれば、港と工場の位置関係が気になるかもしれない。\n\nこのことから、問いを持つことと知識を得ることは反対ではないと分かる。知識は問いに答えるためだけのものではなく、新しい問いを作るための材料にもなる。\n\nただし、知識があれば自然によい問いが生まれるわけではない。知っていることをそのまま受け入れるだけなら、疑問は生まれにくい。必要なのは、新しく得た情報を、すでに知っていることと比べることである。\n\n「前に学んだ場合と何が違うのか」「もし条件が変わったら同じことが言えるのか」「この説明では扱われていないものは何か」。こうした比べ方をすると、知識と知識の間にあるずれや空白が見える。そのずれが問いになる。\n\nここで注意したいのは、問いにはすぐ答えが出るものだけがあるわけではないということだ。「この語句の意味は何か」という問いなら辞書で調べられる。一方、「なぜこの人物はこの場面で何も言わなかったのか」という問いには、文章中の複数の手がかりを集めて考える必要がある。さらに、調べても一つに決められない問いもある。\n\n学校では、問題には正解があり、それを答えることが求められる場面が多い。そのため、自分で問いを作るときにも、「答えが一つに決まる立派な質問を作らなければならない」と考えてしまうことがある。しかし、学び始めるための問いは、最初から完成している必要はない。\n\nたとえば「なぜだろう」という漠然とした疑問があったら、「どこが予想と違ったのか」「何と比べて不思議だと思ったのか」と言葉を足してみる。すると、調べる対象が少しずつ絞られる。問いは、頭の中に完成した形で現れるものというより、考えながら形を整えていくものなのである。\n\nまた、問いを言葉にすると、自分の理解の状態も見えやすくなる。「ここまでは分かるが、この先がつながらない」と説明できれば、必要なのは最初から全部を学び直すことではない。分からない境目に戻って確かめればよい。\n\nだから、よい問いを持つことは、単に好奇心が強いということではない。自分の知識を確かめ、別の情報と比べ、分からない境目を見つけることである。そして問いを作ることは、学習の最後に残った疑問を尋ねる作業ではなく、次にどこを学べばよいかを決める作業でもある。\n\n「質問はありますか」と聞かれてすぐに言葉が出なくても、それだけで考えていないとは限らない。そんなときは、「何が分からないか」を無理に探すより、まず「どこまでは分かっているか」を確かめてみるとよい。問いは、分からない側だけを見るのではなく、分かっている側との境目を見るところから始まる。","questions":[{"skill":"具体と抽象","q":"筆者が機械と地図の例を挙げているのは、どのようなことを説明するためですか。60字以内で書きなさい。","answer":"知識が増えると答えが増えるだけでなく、それまで気づかなかった具体的な疑問や問いも見えるようになること。","guide":["① 機械と地図の例を読み、共通する変化を探す。","② 共通して起きている変化を探す。","③ 機械・地図という具体語を外す。","④ 「知識が増えると～」で一般化する。"]},{"skill":"接続関係","q":"「ただし、知識があれば」で始まる段落は、それ以前の説明にどのような条件を加えていますか。","answer":"知識を持つだけでは問いは生まれず、新しい情報を既知のことと比較し、違いや空白に気づく必要があるという条件。","guide":["① 「ただし」の前後で知識と問いの関係を比べる。","② 前＝知識の働き、後＝必要な条件に分ける。","③ 「自然に」の否定に注目する。","④ 知識＋何が必要かを書く。"]},{"skill":"文章全体","q":"本文では、問いを作ることにどのような二つの役割があると述べられていますか。","answer":"知識同士のずれや分からない点を明確にする役割と、自分が次にどこを調べたり学んだりすべきかを決める役割。","guide":["① 「ずれ」と「次にどこ」の二つの記述を探す。","② 役割を二つに分ける。","③ 具体例は除く。","④ 二つが重ならない表現にする。"]},{"skill":"記述","q":"筆者の考えに従うと、質問が思い浮かばないとき、どのような手順で問いを作ればよいですか。100字以内で説明しなさい。","answer":"まず自分がどこまで理解しているかを確認し、新しい情報を既知の内容と比べて違いやつながらない境目を見つけ、漠然とした疑問に「何と比べて」「どこが違うか」などを加えて問いを具体化する。","guide":["① 理解を確かめる場面から問いを具体化する説明までを読む。","② 手順を時間順に並べる。","③ 「理解確認→比較→境目→具体化」と整理する。","④ 本文の具体例は一般化する。"]},{"skill":"要約","q":"本文全体を120字以内で要約しなさい。","answer":"問いは単に知らないことから生まれるのではなく、知識を新しい情報と比べ、そのずれや理解できない境目を見つけることで形になる。問いを言葉にして具体化することは、自分の理解を確かめ、次に何を調べ学ぶべきかを決めることにもつながる。","guide":["① 知識の働き、問いの作り方、結論の段落を探す。","② 問いの作り方を取る。","③ 問いの役割を取る。","④ 具体例を削り三点をつなぐ。"]}],"id":"b14"},{"title":"物語「最後の係」","genre":"物語文","level":"長文・入試実戦","passage":"三学期の学級会で、卒業前の「三年生を送る会」の係を決めることになった。美咲のクラスは、体育館に飾る大きな掲示を担当する。学級委員が「全体をまとめる人、誰かやってくれる？」と聞くと、何人かが美咲の方を見た。\n\n美咲は一年生のころから、行事のたびに係を引き受けてきた。予定表を作り、必要なものを確認し、遅れている人に声をかける。自分から進んでやっていたわけではないが、一度始めると途中で放っておけなかった。\n\n「美咲なら慣れてるし。」\n隣の席の奈緒が言った。\n美咲は少し迷ってから、「じゃあ、やる」と答えた。\n\n放課後、係の六人が集まった。掲示のテーマはすぐに決まったが、作業の分担になると、みんな美咲の顔を見た。美咲は紙に名前を書き、「奈緒と健太は文字、私と翔は背景、残り二人は写真」と割り振った。\n\n作業は順調に始まった。しかし数日後、写真を担当した二人が、どの写真を使えばよいか決められずにいた。美咲は自分の作業を止めて候補を選んだ。次の日には文字の大きさが合わないと言われ、美咲が定規で測り直した。\n\n「結局、全部美咲が決めてない？」\n奈緒が笑いながら言った。\n「だって、止まってたら間に合わないし。」\n美咲は答えた。\n\nその週の金曜日、美咲は熱を出して学校を休んだ。夕方、スマートフォンを見ると、係の連絡には「今日は作業なしにした」と書かれていた。美咲は布団の中でため息をついた。自分が一日いないだけで作業が止まることに腹が立ったが、同時に、どこかで「やっぱり私がいないと進まない」と思っている自分にも気づいた。\n\n月曜日、登校すると、掲示は金曜日からほとんど変わっていなかった。\n「ごめん、美咲がいないと何をすればいいか分からなくて。」\n健太が言った。\n美咲は「別にいいよ」と答えたが、すぐ作業の指示を出す気にはなれなかった。\n\n昼休み、担任が途中の掲示を見に来た。「よく進んでるね」と言ったあと、美咲に「まとめるの、大変じゃない？」と尋ねた。\n「みんなが聞いてくるので。」\n美咲が答えると、先生は「聞けば美咲が決めてくれるって、みんな知ってるからね」と言った。\n\n責められたような気がして、美咲は黙った。しかし先生は続けた。\n「まとめる人が全部答えを持っている必要はないよ。」\n\nその言葉の意味を、美咲はすぐには理解できなかった。\n\n放課後、美咲はいつものように「今日はここまでやろう」と言いかけて、やめた。代わりに、「あと何が残ってる？」と全員に聞いた。最初は誰も答えなかったが、奈緒が掲示を見ながら「写真の位置と、タイトルの色」と言った。健太が「あと、端の飾り」と続けた。\n\n「じゃあ、どれからやる？」\n美咲が聞くと、今度は翔が「写真を決めないと飾りの場所も決めにくい」と言った。\n\n美咲は不思議な感じがした。自分が決めなくても、話は少しずつ進んでいく。もちろん、意見が分かれて時間がかかる場面もあった。以前なら、そこで自分の案を出して終わらせただろう。しかしその日は、二つの案を実際に並べて比べることにした。\n\n作業終了の時刻になっても、予定していたところまでは終わらなかった。美咲は落ち着かなかった。それでも、次の日に来ると、奈緒たちは先に集まって昨日の続きを始めていた。\n\n「ここ、昨日の二案の中間にしてみた。」\n奈緒が言った。美咲が考えていなかった方法だったが、全体を見るとよく合っていた。\n\n送る会の前日、掲示は完成した。最初の予定より一日遅かった。美咲が一人で管理していたら、もっと早く終わったかもしれない。しかし、完成した掲示には、美咲の知らないところで選ばれた写真や、他の人が考えた飾りがいくつも入っていた。\n\n当日、体育館の壁に掲示を取り付けたあと、奈緒が「最後の係、美咲だけの作品にならなくてよかったね」と言った。\n「最初から私の作品じゃないけど。」\n美咲は笑った。\n\nそう答えてから、美咲は、一週間前なら同じ言葉を同じ気持ちでは言えなかっただろうと思った。あのころの自分は、みんなの仕事だと言いながら、予定どおり進める責任まで一人で抱え、それを手放すのが少し怖かったのだ。\n\n掲示を見上げると、文字の一部がほんの少し傾いていた。美咲なら貼り直したかもしれない。しかし、今はそのままでいいと思えた。","questions":[{"skill":"人物像","q":"物語前半の美咲には、どのような性格や行動の特徴がありますか。本文の行動を根拠に60字以内で書きなさい。","answer":"仕事が止まるのを放っておけず、周囲が迷うと自分で判断して進めようとする、責任感が強い一方で仕事を抱え込みやすい人物。","guide":["① 美咲が仕事を割り振る場面と困ったときの行動を探す。","② 行動と性格を分ける。","③ 長所だけでなく問題につながる特徴も見る。","④ 根拠→人物像の形でまとめる。"]},{"skill":"会話文","q":"担任の「まとめる人が全部答えを持っている必要はないよ」という言葉は、美咲のその後の行動をどう変えましたか。","answer":"自分が指示や答えを出す代わりに、残っている作業や進め方を皆に問い、他の人が考えて決めるのを待つようになった。","guide":["① 先生の発言とその翌日の美咲の行動を比べる。","② 以前の美咲の進め方と比べる。","③ 「言う」から何に変わったか探す。","④ 発言→具体的変化で答える。"]},{"skill":"心情変化","q":"美咲の「まとめる人」に対する考えは、物語を通してどのように変化しましたか。80字以内で書きなさい。","answer":"初めは自分が指示して仕事を終えることが責任だと思っていたが、後には仲間の考えを聞き、協力して進めることも責任だと考えるようになった。","guide":["① 最初の分担と後半の話し合いで「責任」がどう扱われるか探す。","② 「責任」の中身の変化を見る。","③ 先生の言葉を転換点として整理する。","④ 前→後を対比して書く。"]},{"skill":"表現効果","q":"結末で「文字の一部がほんの少し傾いていた」ことを示したのはなぜですか。","answer":"以前なら自分で直していた不完全さを受け入れる姿を通して、完成度を一人で管理するより皆で作ったことを大切にする美咲の変化を示すため。","guide":["① 結末の掲示物の「傾き」の前後を読む。","② 前半なら美咲がどうしたか確認する。","③ 今は「そのままでいい」と思った理由を考える。","④ 具体物→人物の変化で説明する。"]},{"skill":"要約","q":"この物語を、美咲の役割に対する考えの変化を中心に120字以内でまとめなさい。","answer":"係をまとめる美咲は、作業が止まるたび自分で判断し、仕事を抱え込んでいた。欠席で作業が止まったことや担任の言葉をきっかけに、答えを自分で出さず仲間に問いかけるようになる。皆が考えて完成させる経験から、任せることもまとめる役割だと気づく。","guide":["① 最初の係の進め方、先生の言葉、結末を探す。","② 掲示の細部は削る。","③ 美咲の行動変化と考えの変化を対応させる。","④ 最後の気づきで締める。"]}],"id":"b15"},{"title":"説明文「分類すると失われるもの」","genre":"説明文","level":"長文・入試実戦","passage":"私たちは、たくさんのものを理解するとき、それらを分類する。図書館では本を分野ごとに分け、店では商品を種類ごとに並べる。生物を特徴によって分類したり、歴史上の出来事を時代ごとに整理したりもする。分類は、複雑な世界を扱いやすくするための重要な方法である。\n\nもし図書館の本が何の規則もなく置かれていたら、目的の一冊を探すのは難しい。分類によって「この本はこの辺りにあるはずだ」と範囲を狭めることができる。つまり分類には、ものの共通点を利用して、探したり考えたりする負担を減らす働きがある。\n\nしかし、分類された結果だけを見ると、分類する前には見えていたものが見えにくくなることもある。\n\nたとえば、学校の図書室で「科学」の棚と「文学」の棚が分かれているとする。科学者の人生を描いた伝記は、科学の本とも人物を描いた読み物とも考えられる。どちらか一方の棚に置けば探しやすくなる一方、もう一方との関係は見えにくくなる。\n\n色も同じである。私たちは赤、橙、黄などの名前を使って色を分ける。しかし、実際の色は境界線のところで突然別の色に変わるわけではない。赤と橙の間には、どちらとも言える色が無数にある。それでも名前を付けて区切ることで、私たちは色について話しやすくなる。\n\nここから分かるのは、分類の境界が、いつも対象そのものの中にはっきり存在しているとは限らないということだ。何を目的にするかによって、便利な分け方は変わる。\n\nたとえば、同じ植物でも、食べられるかどうかで分ける場合と、育つ地域で分ける場合とでは、同じ仲間になる植物が異なる。どちらかが間違っているのではない。目的が違うため、注目する特徴が違うのである。\n\nこの点を忘れると、分類は理解を助ける道具ではなく、対象そのものを決めつける枠になってしまう。「この種類だから必ずこうだ」と考えると、同じ分類の中にある違いを見落とす。また、境界付近にあるものを無理にどちらかへ入れようとして、その特徴を十分に見なくなることもある。\n\n一方で、「分類には限界があるのだから、分類しない方がよい」と考えるのも適切ではない。分類なしに、一つ一つをすべて別のものとして扱えば、共通点を見つけたり知識を整理したりすることが難しくなる。\n\n重要なのは、分類を答えではなく、見方の一つとして使うことである。\n\n学習でも、これは役に立つ。国語の文章を「物語文」「説明文」と分ければ、それぞれで注目しやすい点を整理できる。しかし、実際の文章には、説明の中に筆者自身の経験が語られたり、物語の中に考えを説明する部分が入ったりする。分類名を覚えるだけでは、その文章を読んだことにはならない。\n\nまた、数学の問題を「方程式」「関数」「図形」と分類することも、解き方を探す手がかりになる。しかし、一つの問題で複数の分野の考え方を使う場合もある。分類は最初の入口にはなっても、そこから先の考え方まで自動的に決めてくれるわけではない。\n\n私たちが何かを分類するとき、同時に二つのことをしている。一つは、似ているものをまとめること。もう一つは、連続していたものや複数の面を持つものに境界を引くことである。前者だけを見ると分類は世界を整理してくれる。しかし後者にも目を向けると、その整理の仕方によって見えなくなる関係があることに気づく。\n\nだから、分類されたものを見るときには、「これは何に分類されているか」だけでなく、「なぜこの分け方をしたのか」「別の分け方をしたら何が見えるか」と考える必要がある。分類を疑うとは、分類を捨てることではない。分類によって見えるものと見えなくなるものの両方を知り、その目的に応じて使い直すことなのである。","questions":[{"skill":"具体と抽象","q":"科学者の伝記と色の例には、どのような共通点がありますか。60字以内で説明しなさい。","answer":"分類すると扱いやすくなる一方、複数の分類に関係する性質や、実際には連続している境界付近の特徴が見えにくくなる点。","guide":["① 科学者の伝記と色の分類の二例を読む。","② 便利になる点と失う点を分ける。","③ 科学・文学・色名という具体語を外す。","④ 共通する構造で答える。"]},{"skill":"因果関係","q":"本文によれば、分類の目的が変わると分類結果も変わるのはなぜですか。","answer":"目的によって対象のどの特徴に注目するかが変わり、共通点として用いる基準が異なるから。","guide":["① 植物を目的別に分類する例とその説明を読む。","② 「目的→注目する特徴→分類結果」の順に整理する。","③ 具体例を一般化する。","④ 理由を「～から」で答える。"]},{"skill":"接続関係","q":"「一方で、」で始まる段落には、文章全体でどのような役割がありますか。","answer":"分類の問題点を述べた後で、だから分類をやめればよいという極端な結論を退け、分類を適切に使うという筆者の主張へつなぐ役割。","guide":["① 「一方で、分類には限界が」の前後を読む。","② 前＝問題点、後＝筆者の結論に分ける。","③ ここで否定される考えを確認する。","④ 前後をつなぐ役割として説明する。"]},{"skill":"文章全体","q":"筆者が述べる分類の「利点」と「注意点」を、それぞれ説明しなさい。","answer":"利点は共通点でまとめて情報を探し整理する負担を減らせること。注意点は、境界や複数の面を単純化し、別の関係や個々の違いを見えにくくすること。","guide":["① 分類の便利さと境界の問題を述べる段落を探す。","② 具体例を除く。","③ 二つを対比できる表現にする。","④ 「利点は～、注意点は～」でまとめる。"]},{"skill":"要約","q":"本文全体を120字以内で要約しなさい。","answer":"分類は共通点を利用して複雑な情報を整理しやすくするが、目的に応じて引いた境界によって別の関係や個々の違いを見えにくくすることもある。分類を固定的な答えとせず、何のための分け方かを考え、必要に応じて別の見方で使い直すことが重要である。","guide":["① 分類の利点、限界、「見方の一つ」という結論を探す。","② 図書館や色などの例は削る。","③ 「しかし」で限界をつなぐ。","④ 最後に筆者が勧める使い方を書く。"]}],"id":"b16"},{"title":"物語「名前のない仕事」","genre":"物語文","level":"長文・入試実戦","passage":"体育祭の準備期間、二年三組では毎日のように放課後の作業が続いていた。応援旗を描く人、競技で使う道具を確認する人、クラスの応援練習を進める人。それぞれに担当が決まっていた。\n\n悠斗は用具係だった。仕事は、借りた道具の数を確認し、使い終わったものを倉庫へ戻すことだった。目立つ仕事ではないが、やることがはっきりしているので悠斗は気に入っていた。\n\n同じ係の亮は、仕事が終わるとすぐ教室へ戻って応援旗を手伝った。悠斗は倉庫の鍵を職員室へ返してから教室へ行くため、いつも少し遅れた。\n\nある日、教室に戻ると、旗の周りに十人ほどが集まっていた。\n「今日かなり進んだよ。」\n亮が言った。手には青い絵の具がついている。\n「すごいな。」\n悠斗が答えると、亮は「悠斗も塗れば？」と言った。\n\n悠斗は少し迷ったが、「まだ廊下に段ボール残ってるから」と答えた。競技用品が入っていた箱が、体育館から教室までの通路にいくつも置かれていたのだ。\n\n「それ、明日でもよくない？」\n亮は悪気なく言った。\n\n悠斗もそう思った。誰かに頼まれた仕事ではない。用具係の仕事にも入っていない。しかし、朝になれば他のクラスも廊下を使う。悠斗は旗の方を一度見てから、段ボールを運び始めた。\n\n翌日の学級活動で、担任が体育祭準備の進み具合を確認した。\n「応援旗、昨日ずいぶん進んだね。」\nそう言われると、旗を担当した生徒たちがうれしそうに顔を見合わせた。亮もその中にいた。\n\n悠斗は何となく机の中を見た。自分も昨日は遅くまで残った。しかし、何をしたのかと聞かれれば、「段ボールを片づけた」としか言えない。それをわざわざ言うほどでもない気がした。\n\nその日の放課後、体育館へ行くと、競技練習で使ったビブスが床に置かれていた。誰の担当か分からない。悠斗は拾って枚数を数え、袋へ戻した。\n\n数日後には、掲示物を貼ったあとのテープの切れ端が廊下に散らばっていた。悠斗はほうきを借りて掃いた。作業をしていると、通りかかった一年生が「ありがとうございます」と言った。悠斗は「いや、別に」と答えた。\n\n体育祭前日、クラスでは最後の確認が行われた。応援旗が完成すると拍手が起こった。練習をまとめてきた生徒にも、担任から「よく頑張ったね」と声がかかった。\n\n悠斗は自分の役割表を見た。用具係の欄には、すべて赤い丸がついている。それで十分なはずだった。それなのに、少しだけ取り残されたような気がした。\n\n帰り際、担任が悠斗を呼び止めた。\n「これ、どこにあった？」\n先生が持っていたのは、体育館用の延長コードだった。\n「ステージの横です。明日使うと思って、用具箱に入れました。」\n「やっぱり悠斗か。」\n\n先生は笑った。\n「最近、誰がやったか分からないけど片づいてることが多くてね。」\n\n悠斗は、ほめられたのだと思った。しかし、思ったほど気持ちは明るくならなかった。\n「でも、別に僕の仕事じゃないです。」\n自分でも、なぜそんな言い方をしたのか分からなかった。\n\n先生は少し考えてから、「そうだね。だから助かってる」と言った。\n\n体育祭当日、朝から風が強かった。開会式の少し前、クラスの掲示が一枚はがれかけているのを悠斗は見つけた。テープを取りに行こうとすると、亮が先に走ってきた。\n「悠斗、そこ押さえといて。」\n亮は新しいテープを持っていた。\n\n二人で貼り直していると、亮が言った。\n「最近、こういうの見つけるようになった。」\n「こういうの？」\n「担当じゃないけど、誰かやらないと困るやつ。」\n\n悠斗は笑った。\n「名前のない係だな。」\n「それ、係にしたら名前つくじゃん。」\n亮も笑った。\n\n体育祭が終わり、片づけが始まった。旗の前では記念写真を撮る生徒が集まっていた。悠斗も呼ばれたが、その前に、風で飛ばされたプログラムを拾い集めた。\n\n今度は亮も一緒だった。\n\n写真を撮るころには、何人かが先に帰っていた。全員そろった写真にはならなかった。それでも悠斗は気にならなかった。完成した旗や写真に残る仕事だけが、体育祭を作ったわけではないと分かったからだ。\n\n教室へ戻る途中、廊下にはもう段ボールも紙くずもなかった。誰が最後に片づけたのか、悠斗には分からなかった。分からないままでいいような気がした。","questions":[{"skill":"心情","q":"悠斗が「少しだけ取り残されたような気がした」のはなぜですか。60字以内で書きなさい。","answer":"自分も準備に取り組んだのに、旗など目立つ仕事は評価され、自分の担当外の片づけは知られていないと感じたから。","guide":["① 応援旗への拍手の場面と悠斗の役割表を見る場面を比べる。","② 悠斗がしてきた仕事と比べる。","③ 「仕事をしていない」のではない点に注意する。","④ 比較→気持ちの順にまとめる。"]},{"skill":"会話文","q":"担任の「そうだね。だから助かってる」という言葉には、どのような意味がありますか。","answer":"決められた担当ではないからこそ、誰も担当していない必要な仕事に悠斗が気づいて行動していることに価値があるという意味。","guide":["① 担任と悠斗の会話の前後を読む。","② 先生が否定せず「そうだね」と答えた理由を考える。","③ 「だから」の因果を整理する。","④ 担当外であることと価値を結ぶ。"]},{"skill":"人物関係","q":"亮と悠斗の関係は、物語の前半と後半でどのように変化していますか。80字以内で説明しなさい。","answer":"前半の亮は目立つ作業を優先して悠斗の片づけを後回しにしたが、後半は担当外の仕事にも気づき、悠斗と一緒に行動するようになった。","guide":["① 段ボールの場面と、亮が掲示を直す場面を比べる。","② 亮の言葉と行動の変化を見る。","③ 悠斗自身ではなく二人の関係に焦点を当てる。","④ 前半→影響→後半で書く。"]},{"skill":"表現効果","q":"最後の「分からないままでいいような気がした。」という表現は、悠斗のどのような変化を示していますか。","answer":"誰がした仕事か認められることを気にしていた悠斗が、名前や評価が残らなくても必要な仕事が行われること自体に意味を感じるようになった変化。","guide":["① 結末の「分からないままでいい」の前後を読む。","② 中盤で悠斗が感じた寂しさと対比する。","③ 評価されることへの考えがどう変わったか見る。","④ 前後の価値観を対比する。"]},{"skill":"記述","q":"題名「名前のない仕事」が表しているものを、本文全体を踏まえて100字以内で説明しなさい。","answer":"役割表には書かれず、誰が行ったかも残らないが、誰かがしなければ皆が困る片づけや小さな対応を指し、目立つ成果や評価だけでなく、そうした自発的な行動も行事を支えていることを表している。","guide":["① 段ボール・ビブス・掲示の片づけの共通点を探す。","② 共通点を一般化する。","③ 題名の「名前がない」の意味を考える。","④ 具体例→作品全体の意味へ広げる。"]},{"skill":"要約","q":"この物語を、悠斗の考えの変化を中心に120字以内でまとめなさい。","answer":"用具係の悠斗は、担当外の片づけを続けながら、目立つ仕事だけが評価されることに寂しさを感じる。担任の言葉や、影響を受けた亮と一緒に行動する経験を通して、誰がしたか分からなくても必要な仕事そのものに価値があり、それも行事を支えるのだと気づく。","guide":["① 悠斗の片づけ、寂しさ、担任の言葉、結末を順に読む。","② 個々の片づけの例は減らす。","③ 亮と先生は変化のきっかけとして扱う。","④ 最後の価値観の変化を残す。"]}],"id":"b17"},{"title":"説明文「測ることで見えるもの、隠れるもの」","genre":"説明文","level":"長文・入試実戦","passage":"私たちは、何かを比べるとき数字を使う。身長、時間、気温、点数、売上、人数。数字にすれば、「多い」「少ない」「速い」「高い」といった違いを、感覚だけに頼らず示すことができる。\n\n測ることの大きな利点は、異なる人が同じ基準を共有できることである。「今日は暑い」と言っても、暑さの感じ方は人によって違う。しかし「気温が三十二度だった」と言えば、少なくとも何を基準に話しているかは明確になる。\n\n学校のテストも、学習の一部を点数として表す仕組みである。同じ問題を同じ条件で解けば、どこまでできたかをある程度比較できる。前回と今回の点数を比べれば、自分の変化を見る手がかりにもなる。\n\nこのように、測定は曖昧なものを共通の尺度に置き換え、比較や記録を可能にする。\n\nところが、数字が示されると、私たちはその数字が対象のすべてを表しているように感じることがある。\n\nたとえば、二人の生徒が同じ八十点を取ったとする。一人は計算問題をほぼ正解したが文章題を多く間違え、もう一人はその逆だったかもしれない。同じ点数でも、できることとできないことの中身は異なる。\n\n読書について、一年間に読んだ本の冊数を記録する場合も同じである。十冊より五十冊の方が「多く読んだ」と言える。しかし、冊数だけから、一冊一冊をどのように読み、何を考えたかまでは分からない。短い本を五十冊読んだ人と、一冊の長い本を何度も読み返した人を、冊数だけで単純に比べることはできない。\n\nこれは数字が不正確だからではない。数字は、測ると決めたものについては正確でも、測っていないものについては何も語らないからである。\n\nこの違いは重要である。「数字は信用できない」と考えるのではなく、「この数字は何を測った数字なのか」と問い直す必要がある。\n\nたとえば、走る力を調べるために五十メートル走の時間を測ったとする。その数字は短い距離を走る速さについては役立つ。しかし、長い距離を走り続ける力や、球技の中で相手を見ながら動く力まで同じ数字で表すことはできない。目的が変われば、必要な測り方も変わる。\n\nさらに、測るものを決めること自体が、人の行動を変える場合がある。\n\n図書館で「一か月に何冊借りたか」を目標にすると、利用者は冊数を意識するようになるだろう。それ自体が悪いわけではない。多くの本に触れるきっかけになることもある。しかし、冊数だけが評価されれば、読み終えることを急いだり、短い本ばかり選んだりする人が出てくるかもしれない。\n\nつまり、測定は現実をただ写し取るだけではない。何を大切だと考えるかを示し、ときには人の行動をその方向へ動かす。\n\nだから、何かを数値化するときには二つの問いが必要になる。一つは、「この数字は本当に知りたいことをどこまで表しているか」。もう一つは、「この数字を使うことで、人の行動はどう変わるか」である。\n\nもちろん、すべてを数字にしない方がよいということではない。数字がなければ、変化を確かめたり、多くの情報から傾向を見つけたりすることは難しい。大切なのは、数字を使うことと、数字だけを見ることを区別することである。\n\n学習でも同じことが言える。テストの点数が上がれば、一つの成果として喜んでよい。しかし、点数だけを見て「国語ができるようになった」「数学が苦手になった」と決めるのは早い。どの問題が解けるようになり、どこで迷ったのかまで見れば、次に何を学ぶべきかが分かる。\n\n数字は、複雑なものを一つの尺度から見せてくれる。そのため、見えやすくなるものがある。同時に、一つの尺度に入らないものは見えにくくなる。\n\n測ることの目的は、複雑な現実を数字に置き換えて終わることではない。数字によって見えたことを手がかりに、もう一度その中身を見ることである。数字は結論というより、詳しく見る場所を教えてくれる入口なのである。","questions":[{"skill":"指示語","q":"「この違いは重要である」の「この違い」とは、どのような違いですか。本文に即して説明しなさい。","answer":"数字は測ると決めた対象については情報を示すが、測定の対象に含めていない性質や中身については示さないという違い。","guide":["① 「これは数字が不正確だからではない」の前後を読む。","② 「数字が正確かどうか」の話ではない点に注意する。","③ 測ったもの／測っていないものを対比する。","④ 指示語を具体的な内容に置き換える。"]},{"skill":"具体と抽象","q":"八十点の二人、読書冊数、五十メートル走の例に共通していることを60字以内で説明しなさい。","answer":"一つの数字はある側面の比較には役立つが、それだけでは対象の異なる能力や内容など全体を表せないということ。","guide":["① 八十点、冊数、五十メートル走の三例を読む。","② 各例で数字から分からないものを探す。","③ 具体的な点数・冊数・走力を外す。","④ 「役立つが、～までは表せない」でまとめる。"]},{"skill":"因果関係","q":"筆者は、測るものを決めることが人の行動を変える場合があるのはなぜだと考えていますか。","answer":"特定の数字が目標や評価の対象になると、人はその数字を高めることを意識し、その尺度で評価されやすい行動を選ぶようになることがあるから。","guide":["① 図書館の貸出冊数が目標になる例を読む。","② 「評価されるもの→意識→行動」の順にする。","③ 例を一般化する。","④ 原因と結果を明確につなぐ。"]},{"skill":"文章全体","q":"数値化するときに必要だと筆者が述べる二つの問いは、なぜ必要なのですか。80字以内で説明しなさい。","answer":"数字は知りたい対象の一部しか表さず、評価に使うことで人の行動を変える場合もあるため、測定の範囲と影響を確かめる必要があるから。","guide":["① 「二つの問い」が示される段落と直前の説明を読む。","② それぞれが何の問題に対応するか前の段落から探す。","③ 二つを別々に説明してから結ぶ。","④ 「～ため」で理由としてまとめる。"]},{"skill":"記述","q":"本文を踏まえ、テストの点数を学習に生かすにはどうすればよいか。100字以内で説明しなさい。","answer":"点数を学習成果の一つの手がかりとして前回などと比較しつつ、点数だけで得意不得意を決めず、正誤の内容や迷った箇所まで確認して、次に学ぶべき内容を判断する。","guide":["① 最後のテストの点数の例を読む。","② 点数の「使える点」と「不足する点」を分ける。","③ 数字の後に何を見るべきか探す。","④ 手順として書く。"]},{"skill":"要約","q":"本文全体を120字以内で要約しなさい。","answer":"数値化は共通の尺度で比較や記録を可能にする一方、測らない側面を隠し、評価する数字が行動を変えることもある。数字だけで結論を出さず、何を測ったかとその影響を確かめ、対象の中身も見ることが重要である。","guide":["① 数字の利点、限界、行動への影響、結論を探す。","② 個別の具体例は削る。","③ 「一方」で限界を示す。","④ 最後は数字の使い方についての主張で締める。"]}],"id":"b18"},{"title":"物語「途中の地図」","genre":"物語文","level":"長文・入試実戦","passage":"校外学習の班別行動で、直人たちの班は古い商店街を調べることになった。目的は、地域の変化を調べ、最後に地図と文章で発表することだった。\n\n班長の直人は、出発前に道順を細かく決めた。駅から時計店、昔からある和菓子屋、川沿いの公園、最後に資料館。地図には赤い線を引き、それぞれの場所に着く予定時刻まで書いた。\n\n「ここまで決めなくてもよくない？」\n美優が言った。\n「時間なくなったら困るから。」\n直人は答えた。\n\n当日、最初の時計店までは予定どおりだった。店主に話を聞くと、昔は商店街に映画館があったことを教えてくれた。\n「その跡、今も少し残ってるよ。一本裏の道。」\n美優が「行ってみたい」と言ったが、直人は時計を見た。\n「予定にないし、次の店の時間がある。」\n\n班はそのまま和菓子屋へ向かった。\n\nところが、和菓子屋の主人からも映画館の話が出た。映画が終わる時刻になると通りに人が増え、店も夜まで開けていたという。\n「映画館がなくなってから、この辺の人の流れも変わったね。」\n\n店を出ると、美優がまた言った。\n「やっぱり跡を見に行かない？」\n直人は地図の赤い線を見た。次の公園まで十五分。寄り道をすれば、資料館の見学時間が短くなる。\n「資料館に昔の写真があるかもしれないから、そっちでいいよ。」\nそう言って歩き出した。\n\n公園で写真を撮り、予定より三分早く資料館に着いた。しかし、資料館は臨時休館だった。\n\n入口の前で、班の四人はしばらく黙った。\n「どうする？」\n美優が聞いた。\n\n直人は地図を見た。そこには、この先の予定がもうなかった。きれいに引いた赤い線が、急に役に立たないものに見えた。\n\n「駅に戻る？」\n直人が言うと、美優は少し考えてから、「さっきの映画館の跡、今からなら行けるんじゃない？」と言った。\n\n今度は直人も反対しなかった。\n\n裏通りに入ると、商店街の表側とは雰囲気が違った。新しい住宅の間に、古い石の階段が残っていた。その先の駐車場の壁に、「中央劇場」とかすれた文字が見えた。\n\n「これか。」\n直人は思わず声を上げた。\n\n近くで植木に水をやっていた女性が、「映画館を調べてるの？」と話しかけてきた。事情を説明すると、その女性は子どものころ家族で映画を見に来たこと、閉館後しばらく建物が倉庫として使われていたことを教えてくれた。\n\n「表の通りだけ見ても、昔のことは分からないものね。」\n女性はそう言った。\n\n帰り道、美優は地図の余白に、映画館跡の位置と聞いた話を書き込んでいた。\n「その地図、もう道順ぐちゃぐちゃだな。」\n直人が言うと、美優は「でも、来る前より情報増えたよ」と答えた。\n\n直人は自分の地図を見た。赤い線は出発前と同じだった。しかし、その周りには何も書かれていない。\n\n学校へ戻り、班で発表資料を作ることになった。直人は最初、予定していた四か所を順番に紹介しようとした。だが、資料館には入れず、逆に予定外の映画館跡で多くの話を聞いたため、その構成ではうまくまとまらなかった。\n\n「商店街の人の流れがどう変わったか、でまとめたら？」\n班員の健が言った。\n美優も、「時計店と和菓子屋の話が、映画館でつながる」と続けた。\n\n直人はそこで初めて、二つの店で同じ話が出た時点で、それは寄り道ではなく、調べるべき手がかりだったのかもしれないと思った。\n\n発表の日、班は最初に、現在の商店街の地図を示した。次に昔の映画館の位置を加え、人の流れが変化したことを店の人の話とともに説明した。\n\n発表後、先生から「現地で調べたからこそ分かったことは何ですか」と聞かれた。\n\n直人は少し考えてから答えた。\n「最初に決めた場所を見るだけじゃなくて、何度も出てくる話を追ったら、場所どうしのつながりが見えたことです。」\n\n帰宅してから、直人は校外学習で使った地図を机に広げた。赤い道順の横に、映画館跡や聞いた話を書き足した。きれいだった地図は、前より読みにくくなった。\n\nそれでも、直人は新しい紙に書き直そうとは思わなかった。出発前に作った地図と、歩いたあとにできた地図。その違いそのものが、自分たちが調べた跡のように思えたからだ。","questions":[{"skill":"事実・推測","q":"直人が最初の二回、映画館跡へ行くことに消極的だった理由として、本文から確実に言えることと、そこから推測できる考えを分けて書きなさい。","answer":"本文から確実に言えるのは、直人が予定にないことや次の見学時間を理由に映画館跡へ行かなかったこと。そこから、計画どおり進めることを優先していたと推測できる。","guide":["① 時計店と和菓子屋で映画館跡を勧められた場面を読む。","② 本文に直接書かれたことと人物の考えの推測を分ける。","③ 二度の反応に共通するものを見る。","④ 「事実／推測」の形で答える。"]},{"skill":"きっかけ","q":"直人が調査の進め方を変え始める直接のきっかけは何ですか。また、その後どのような行動に変わりましたか。","answer":"予定していた資料館が臨時休館で計画どおり進められなくなったことが直接のきっかけで、美優の提案を受け入れて予定外の映画館跡へ行き、現地で新たな情報を集めた。","guide":["① 資料館が臨時休館だった場面から映画館跡へ行くまでを読む。","② 予定が崩れた出来事を特定する。","③ その前後で直人の行動を比較する。","④ きっかけ→変化で書く。"]},{"skill":"人物関係","q":"美優は直人の考えの変化にどのような役割を果たしていますか。80字以内で説明しなさい。","answer":"美優は映画館跡の調査を提案し、現地で得た情報を地図に書き込むことで、計画を優先する直人に、新しい手がかりを追う大切さを気づかせた。","guide":["① 美優が提案した場面と、地図に書き込む場面を読む。","② 直人との違いを整理する。","③ 最後に直人が何に気づいたか確認する。","④ 美優の行動→直人への影響でまとめる。"]},{"skill":"表現効果","q":"結末で、直人が「前より読みにくくなった」地図を書き直さなかったのはなぜですか。","answer":"予定どおりの道順だけを示す整った地図よりも、現地で予定外の情報を追い、考えを変えながら調査した過程が書き込まれた地図に、学んだことそのものの価値を感じたから。","guide":["① 結末の地図の記述と、出発前の赤い線を比べる。","② 地図に何が増えたかを見る。","③ 地図の変化と直人の考えの変化を対応させる。","④ 書き直さない理由を価値観の変化として説明する。"]},{"skill":"記述","q":"この物語で描かれる「計画」と「調査」の関係について、直人の経験を踏まえて100字以内で説明しなさい。","answer":"計画は調査を効率よく進めるための出発点になるが、現地では予想外の出来事や新しい手がかりが生まれるため、計画だけに従わず、得た情報に応じて調べる対象や進め方を変えることも必要である。","guide":["① 予定どおり進めた場面と、予定外の発見の場面を読む。","② 途中で計画外に得たものを見る。","③ 「計画か自由か」の二択にしない。","④ 両者の関係として一般化する。"]},{"skill":"要約","q":"この物語を、直人の調査に対する考えの変化を中心に120字以内でまとめなさい。","answer":"直人は事前の道順と時刻を守ることを重視し、予定外の映画館跡を避けていた。しかし資料館の休館を機に現地の手がかりを追い、複数の話のつながりを発見する。そこから、計画だけでなく、調査中に得た情報に応じて進め方を変えることに価値があると気づく。","guide":["① 事前の計画、資料館の休館、映画館跡、発表の場面を追う。","② 店名など細部は削る。","③ 変化のきっかけを残す。","④ 調査観の変化で締める。"]}],"id":"b19"},{"title":"説明文「記録は過去を残すだけか」","genre":"説明文","level":"長文・入試実戦","passage":"記録という言葉を聞くと、多くの人は「起きたことを後から確認するために残すもの」を思い浮かべるだろう。日記、写真、試合結果、観察ノート、会議の議事録など、記録にはさまざまな形がある。\n\n確かに、記録には過去を保存する働きがある。人の記憶は時間とともに変化する。同じ出来事でも、細かな順序を忘れたり、自分にとって印象的だった部分だけを強く覚えたりする。そのため、その時点で日時や数値、発言などを残しておけば、後から確かめる手がかりになる。\n\nしかし、記録の役割は過去を保存することだけではない。何を記録するかを決めた時点で、私たちはすでに対象の見方を選んでいる。\n\nたとえば、植物の成長を観察するとする。毎日「高さ」だけを測れば、高さの変化は詳しく分かる。一方、葉の枚数や色、土の乾き方は記録に残らない。逆に、それらも記録すれば、成長を別の面から見ることができる。\n\nつまり記録は、起きたことをそのまま全部保存する箱ではない。現実の中から、記録する人が選んだ部分を残す仕組みなのである。\n\n写真について考えると、このことはさらに分かりやすい。一枚の写真は、その瞬間にカメラの前にあったものを写す。しかし、写真の外側に何があったのか、撮影する直前と直後に何が起きたのかは写らない。撮影者がどこに立ち、どこへカメラを向けたかによって、残るものは変わる。\n\nだからといって、記録は主観的で役に立たない、ということにはならない。むしろ、記録が何を残し、何を残していないのかを理解すれば、より適切に利用できる。\n\nたとえば、ある町の十年前と現在を比べるために写真を使うなら、同じ場所を写した写真を比べることで建物や道路の変化を知ることができる。しかし、その写真だけから住民の暮らしや気持ちまで分かったと考えるのは行き過ぎである。写真が答えられる問いと、答えられない問いを区別する必要がある。\n\nさらに興味深いのは、記録が未来の行動にも影響することである。\n\n学習記録を例にしよう。毎日、勉強した時間だけを記録していると、「今日は何時間できたか」が意識されるようになる。間違えた問題の種類も記録すれば、「どこで間違えやすいか」に注意が向く。記録する項目が変わると、次に見る場所も変わるのである。\n\nスポーツでも同様である。試合の勝敗だけでなく、成功したプレーと失敗したプレー、そのときの状況を記録すれば、次の練習で何を改善するかを考えやすい。記録は過去の結果を眺めるためだけでなく、次の行動を選ぶ材料になる。\n\nここには、一見すると逆向きの働きがある。記録は過去へ向かって出来事を残す。それと同時に、残された記録を読むことで、私たちは未来へ向かって行動を変える。\n\nこの二つの働きを結びつけるのが「問い」である。\n\nただ記録を集めるだけでは、情報が増えるだけになることがある。「なぜ今回はうまくいったのか」「前回と何が違うのか」「次に変えるならどこか」と問いながら記録を見ると、ばらばらだった情報の間に関係が見えてくる。\n\nまた、問いが変われば、必要な記録も変わる。植物が「どれだけ高くなったか」を知りたいなら高さを測ればよい。しかし「どの条件で元気に育つか」を知りたいなら、日当たり、水の量、葉の状態なども必要になるだろう。\n\nしたがって、よい記録とは、項目が多い記録とは限らない。目的に合った情報が残され、後から問いに照らして比べられる記録が役に立つ。\n\n私たちは、ときどき「記録してあるから事実が分かる」と安心する。しかし、記録を見るときには、その記録がどのような目的で、何を選んで残したものかを確かめる必要がある。そして自分が知りたいことに対して、その記録だけで十分なのかを考えなければならない。\n\n記録は過去そのものではない。過去の一部を選んで残し、問いによって読み直すための手がかりである。そして、その手がかりをどう読むかによって、記録は未来の行動を考える道具にもなるのである。","questions":[{"skill":"指示語","q":"「この二つの働き」とは、記録のどのような二つの働きを指しますか。","answer":"過去に起きた出来事を後から確かめられるよう残す働きと、残した情報を読み直して次に何をするかという未来の行動を変える材料になる働き。","guide":["① 「ここには、一見すると逆向きの働きがある」の段落を読む。","② 「過去へ」「未来へ」に対応する内容を探す。","③ 二つを同じ粒度で表す。","④ 「～働きと、～働き」で答える。"]},{"skill":"具体と抽象","q":"植物の観察と写真の例は、記録についてのどのような考えを説明するために挙げられていますか。60字以内で書きなさい。","answer":"記録は現実のすべてをそのまま残すのではなく、記録する目的や人の選択によって、残る情報と残らない情報が生じるという考え。","guide":["① 植物の高さの記録と、写真に写らない範囲の説明を読む。","② 高さや写真という具体語を外す。","③ 共通する記録の性質を探す。","④ 一般化してまとめる。"]},{"skill":"因果関係","q":"筆者は、記録する項目が変わると「次に見る場所も変わる」と述べています。なぜですか。","answer":"記録した項目は後から比較や振り返りの対象となり、その情報を意識して原因や改善点を考えるため、何を記録するかが次に注意を向ける対象を変えるから。","guide":["① 学習時間と間違いの種類を記録する例を読む。","② 記録項目→意識→次の行動の順にする。","③ 具体例を一般化する。","④ 原因から結果へつなげる。"]},{"skill":"選択肢照合","q":"本文の内容に最も合うものを一つ選びなさい。","choices":["ア　記録は主観が入るため、事実を調べる資料として使うべきではない。","イ　できるだけ多くの項目を残した記録ほど、どのような目的にも役立つ。","ウ　記録は目的に応じて現実の一部を残すものであり、問いながら読むことで次の行動にも生かせる。","エ　過去を正確に保存するには、写真による記録が文章による記録より優れている。"],"answer":"ウ","guide":["① 各選択肢の「主観」「項目数」「目的」「写真」に対応する本文を探す。","② 「必ず・どのような目的にも」など強すぎる表現に注意する。","③ 記録の限界だけでなく利点も含むか見る。","④ 結論の段落と最も一致するものを選ぶ。"]},{"skill":"文章全体","q":"本文で「問い」が重要だとされているのはなぜですか。80字以内で説明しなさい。","answer":"問いによって、残された情報をただ集めるのではなく相互に比較して関係を見つけ、次の行動を考えられるうえ、知りたいことに応じて何を記録すべきかも決められるから。","guide":["① 「この二つの働きを結びつけるのが『問い』」の前後を読む。","② 記録を読むとき／記録するときの二方向を見る。","③ 過去と未来をつなぐ働きを整理する。","④ 二つの役割を一文にまとめる。"]},{"skill":"要約","q":"本文全体を120字以内で要約しなさい。","answer":"記録は過去のすべてではなく、目的に応じて選んだ情報を残すものであるため、何が記録され何が欠けているかを確かめる必要がある。また、問いをもって記録を比較すれば情報の関係や改善点が見え、記録を次の行動を考える材料として使うことができる。","guide":["① 記録の選択性、過去と未来の働き、「問い」の段落を読む。","② 植物や写真などの例は削る。","③ 「問い」の役割を残す。","④ 最後の筆者の結論につなげる。"]}],"id":"b20"}],"kaizen":[{"id":"B01","level":"基礎","title":"問1　原因と結果","passage":"雨が降り始めたため、屋外で予定していた発表会は体育館に変更された。","question":"発表会の場所が変更された理由を答えなさい。","wrong":"体育館に変更されたから。","cause":"原因ではなく結果を述べている。","answer":"雨が降り始めたため。"},{"id":"B02","level":"基礎","title":"問2　指示語","passage":"美咲は下書きを読み直し、説明が不足している箇所に印をつけた。この作業を終えてから清書した。","question":"「この作業」とは何ですか。","wrong":"清書すること。","cause":"指示語より後の行動を答えている。","answer":"下書きを読み直し、説明が不足している箇所に印をつけること。"},{"id":"B03","level":"基礎","title":"問3　事実と推測","passage":"朝、校庭はぬれていた。前夜に雨が降ったかどうかは、誰も確認していなかった。","question":"前夜に雨が降ったと断定できますか。","wrong":"校庭がぬれていたので、雨が降った。","cause":"観察事実から原因を一つに断定している。","answer":"断定できない。校庭がぬれていたことは事実だが、前夜の雨が原因かは分からない。"},{"id":"B04","level":"基礎","title":"問4　心情の根拠","passage":"発表を終えた遥は、手元の原稿を何度も折り直しながら、ようやく小さく笑った。","question":"遥の心情を行動を根拠に説明しなさい。","wrong":"うれしかった。","cause":"心情のみで、本文の根拠がない。","answer":"原稿を何度も折り直していたことから緊張していたが、発表を終えて小さく笑い、少し安心したと考えられる。"},{"id":"B05","level":"基礎","title":"問5　対比","passage":"昨年は全員が同じ説明文を読んだ。今年は訪問者の年齢に合わせて説明を変えた。","question":"昨年と今年の説明方法の違いを答えなさい。","wrong":"今年は説明を変えた。","cause":"比較対象の昨年の方法が欠けている。","answer":"昨年は全員に同じ説明をしたが、今年は訪問者の年齢に合わせて変えた。"},{"id":"B06","level":"基礎","title":"問6　条件の見落とし","passage":"兄は道具をそろえ、妹は作業の順序を紙に書いた。その後、二人で棚を組み立てた。","question":"兄と妹の準備をそれぞれ答えなさい。","wrong":"兄が道具をそろえた。","cause":"「それぞれ」という条件の一方を落としている。","answer":"兄は道具をそろえ、妹は作業の順序を紙に書いた。"},{"id":"B07","level":"基礎","title":"問7　具体と抽象","passage":"教室では電気をこまめに消し、使わない紙は裏面も利用している。","question":"この二つの行動に共通する目的を答えなさい。","wrong":"電気を消すこと。","cause":"具体例の一つを繰り返しており、共通点を抽象化できていない。","answer":"資源の無駄を減らすこと。"},{"id":"B08","level":"基礎","title":"問8　理由と目的","passage":"図書委員は本を探しやすくするため、棚に分類表示をつけた。","question":"分類表示をつけた目的を答えなさい。","wrong":"分類表示がなかったから。","cause":"目的ではなく背景を推測している。","answer":"本を探しやすくするため。"},{"id":"B09","level":"基礎","title":"問9　人物の行動","passage":"健太は自分の意見を言いかけて黙った。しかし友人が待ってくれたので、もう一度話し始めた。","question":"健太が再び話し始めたきっかけを答えなさい。","wrong":"自分の意見があったから。","cause":"きっかけとなる直前の出来事を捉えていない。","answer":"友人が急がせずに待ってくれたこと。"},{"id":"B10","level":"基礎","title":"問10　要約","passage":"町の図書館は、利用者が減ったことを受け、子ども向けの読み聞かせを始めた。その結果、親子で訪れる人が増えた。","question":"取り組みと結果を含めて要約しなさい。","wrong":"図書館では読み聞かせを始めた。","cause":"設問が求める結果を落としている。","answer":"図書館が子ども向けの読み聞かせを始めた結果、親子の利用者が増えた。"},{"id":"B11","level":"基礎","title":"問11　選択肢の断定","passage":"調査に参加した生徒の多くは徒歩で登校していたが、自転車で通う生徒もいた。","question":"「全員が徒歩で登校していた」は正しいですか。","wrong":"正しい。多くの生徒が徒歩だったから。","cause":"「多く」と「全員」を混同している。","answer":"正しくない。自転車で通う生徒もいたため。"},{"id":"B12","level":"基礎","title":"問12　表現の効果","passage":"窓の外では、雨粒が小さな太鼓のように屋根をたたいていた。","question":"「小さな太鼓のように」の効果を説明しなさい。","wrong":"雨が降っていたことが分かる。","cause":"比喩による音の印象に触れていない。","answer":"雨粒が屋根に当たる規則的な音を、太鼓にたとえて印象づけている。"},{"id":"A01","level":"発展","title":"問1　対比と理由","passage":"昨年の文化祭では、展示の説明をすべて紙に印刷した。今年は説明を短い動画でも見られるようにした。文字を読むことが難しい来場者にも内容を伝えたいと考えたからだ。","question":"今年、動画を取り入れた理由を、昨年との違いに触れて説明しなさい。","wrong":"来場者に内容を伝えるため。","cause":"昨年は紙の説明だけだったことと、文字を読むことが難しい来場者への配慮を結びつけていない。","answer":"昨年の紙による説明に加え、文字を読むことが難しい来場者にも内容を伝えられるようにするため。"},{"id":"A02","level":"発展","title":"問2　心情の変化","passage":"美羽は自分の絵を人前に出すのをためらっていた。友人が「この色の組み合わせが好き」と言うと、美羽は絵を机の中央に置き直した。","question":"美羽の気持ちの変化を、きっかけと行動を含めて説明しなさい。","wrong":"友人にほめられてうれしくなった。","cause":"当初のためらいと、絵を中央に置き直した行動が示す変化が抜けている。","answer":"初めは絵を見せるのをためらっていたが、友人に色を認められ、自信を持って見せようとする気持ちに変わった。"},{"id":"A03","level":"発展","title":"問3　条件付き要約","passage":"町の公園ではごみが増えていた。住民はごみ箱を増やすだけでなく、持ち帰りを呼びかける掲示も設けた。その後、ごみの量は減った。","question":"問題・対策・結果の三つを含めて要約しなさい。","wrong":"ごみ箱を増やしたら、ごみが減った。","cause":"対策を一つしか挙げず、掲示の取り組みも落としている。","answer":"公園のごみが増えたため、ごみ箱の増設と持ち帰りの呼びかけを行った結果、ごみが減った。"},{"id":"A04","level":"発展","title":"問4　事実と推論","passage":"放課後、図書室の席はほとんど埋まっていた。翌週から試験が始まる。ただし、利用者全員の目的を調べたわけではない。","question":"図書室が混んでいた理由について、言えることと言えないことを区別しなさい。","wrong":"全員が試験勉強をしていた。","cause":"試験が近いことから利用者全員の目的を断定している。","answer":"試験が近いため勉強目的の利用者がいた可能性はあるが、全員が試験勉強をしていたとは断定できない。"},{"id":"A05","level":"発展","title":"問5　主張と根拠","passage":"校内の水筒利用者は昨年より増えた。一方、使い捨て容器のごみは減った。生徒会は水筒の利用をさらに呼びかけたいと考えている。","question":"生徒会の提案を支える二つの事実を挙げなさい。","wrong":"水筒を使う人が増えたこと。","cause":"使い捨て容器のごみが減った事実が欠けている。","answer":"水筒の利用者が昨年より増えたことと、使い捨て容器のごみが減ったこと。"},{"id":"A06","level":"発展","title":"問6　指示語と行動順","passage":"先生は生徒の発表を聞き、良かった点を先に伝えた。その後、改善点を一つだけ示した。この順序にしたのは、生徒が前向きに受け止められるようにするためだ。","question":"「この順序」の内容と目的を説明しなさい。","wrong":"改善点を一つだけ伝えること。","cause":"先に良い点を伝える順序と、その目的が抜けている。","answer":"良かった点を先に伝えてから改善点を一つ示し、生徒が助言を前向きに受け止められるようにする順序。"},{"id":"A07","level":"発展","title":"問7　人物関係と心情","passage":"航は班の作業を一人で進めようとしたが、途中で手が止まった。すると陽菜が「分けてやろう」と声をかけた。航は少し考えてから、資料を半分渡した。","question":"航が資料を渡した理由を、状況と陽菜の言葉を根拠に説明しなさい。","wrong":"陽菜が手伝ってくれたから。","cause":"航が一人では進められなくなった状況が抜けている。","answer":"一人で作業を進められなくなったところに陽菜が分担を提案したため、協力しようと思ったから。"},{"id":"A08","level":"発展","title":"問8　複数資料の照合","passage":"【資料A】校内アンケートでは、読書時間が増えた生徒は40人、減った生徒は25人だった。【資料B】図書室の貸出冊数は前年より減った。","question":"二つの資料から「生徒全体の読書量が増えた」と断定できるか説明しなさい。","wrong":"読書時間が増えた生徒の方が多いので断定できる。","cause":"読書時間と貸出冊数は異なる指標で、全体の読書量を確定できない。","answer":"断定できない。読書時間が増えた生徒は多いが、図書室の貸出冊数は減っており、生徒全体の読書量は分からない。"},{"id":"A09","level":"発展","title":"問9　目的と結果","passage":"商店街は休日に歩行者が安全に歩けるよう、一部の道路を車両通行止めにした。すると、予想以上に多くの家族連れが訪れた。","question":"取り組みの目的と、実際に起きた結果を区別して答えなさい。","wrong":"家族連れを増やすために通行止めにした。","cause":"実際の結果を当初の目的と取り違えている。","answer":"目的は歩行者が安全に歩けるようにすることで、結果として多くの家族連れが訪れた。"},{"id":"A10","level":"発展","title":"問10　対比と筆者の主張","passage":"便利な道具を使えば作業は速くなる。しかし、道具に任せきりでは仕組みを理解する機会が減る。大切なのは、道具を使う場面と自分で考える場面を選ぶことだ。","question":"筆者の主張を、便利さと注意点の両方に触れて説明しなさい。","wrong":"道具に頼らず自分で考えるべきだ。","cause":"道具の便利さを否定してしまい、使い分けるという主張を捉えていない。","answer":"道具は作業を速くする一方、任せきりでは理解が深まらないため、使う場面と自分で考える場面を選ぶべきだ。"},{"id":"A11","level":"発展","title":"問11　表現の効果と場面","passage":"校庭に一人残った紗季の耳に、遠くの歓声が波のように寄せては引いた。紗季は足元の白線を見つめていた。","question":"「波のように」の表現が場面に与える効果を説明しなさい。","wrong":"歓声が大きいことを表している。","cause":"寄せては引く音の変化と、紗季が一人でいる場面との対照を捉えていない。","answer":"歓声が近づいたり遠のいたりするように聞こえる様子を表し、一人でいる紗季と周囲のにぎわいの対照を印象づける。"},{"id":"A12","level":"発展","title":"問12　根拠の範囲","passage":"調査では三年生の80人のうち52人が朝食を毎日食べると答えた。この学校の全学年については調査していない。","question":"「この学校の生徒の大多数は毎日朝食を食べる」と言えるか、調査対象に触れて説明しなさい。","wrong":"52人が毎日食べているので言える。","cause":"三年生80人の調査結果を学校全体へ一般化している。","answer":"言えない。調査対象は三年生80人に限られ、全学年の生徒については分からない。"}],"diag":{"心情":[["A","根拠なし","気持ちだけを想像","①行動・表情・会話へ戻る"],["B","対象不足","何に対する気持ちか不明","②事実と心情を分ける"],["C","根拠不一致","根拠からその心情が言えない","③根拠→心情を整理"]],"心情変化":[["A","片側だけ","変化前か後がない","②前・きっかけ・後に分類"],["B","きっかけ不足","変化の理由がない","③前→きっかけ→後"],["C","時点混同","前後を取り違えた","①前半・後半へ戻る"]],"きっかけ":[["A","直接原因でない","変化から遠い出来事","①変化直前へ戻る"],["B","結果を書いた","変化後を答えている","②前・出来事・後に分類"],["C","抽象的","誰の何か不明","④答案部品を具体化"]],"接続関係":[["A","前後未確認","接続語だけで判断","①前後を囲む"],["B","関係違い","逆接・対比等を誤認","②関係を分類"],["C","説明不足","何と何の関係か不明","④前は～、後は～"]],"具体と抽象":[["A","例の繰返し","具体例をそのまま回答","①一般論へ戻る"],["B","広げすぎ","本文外の一般論","③共通点だけ抽象化"],["C","対応ずれ","別の主張と結んだ","②例と一般論を対応"]],"選択肢照合":[["A","一部一致","一部分だけ見て選択","②一致／不一致に分類"],["B","程度ずれ","少し→完全になど","①程度表現を照合"],["C","因果ずれ","結果は合うが原因違い","③不一致箇所を特定"],["D","主体・時点ずれ","誰が・いつが違う","①主体・時点を照合"]],"要約":[["A","具体例中心","例だけをまとめた","②主張／理由／例に分類"],["B","結論不足","逆接後・結論がない","①接続語・結論へ戻る"],["C","情報過多","細部を残しすぎ","③具体例を削る"],["D","主張改変","本文より強い主張","④全体と照合"]],"記述":[["A","条件落ち","設問指定が抜けた","①設問条件へ戻る"],["B","部品不足","本文情報が足りない","②答案部品を集める"],["C","関係ずれ","因果・前後が違う","③関係を整理"],["D","問いずれ","問われたことと違う","④設問に対応"]],"会話文":[["A","発言だけ","発言＝本心とした","①前後の行動を見る"],["B","想像過多","本文外の意図を追加","②発言と行動に分類"],["C","ずれ見落し","言葉と行動の差を無視","③一致／不一致確認"]],"人物像":[["A","一行動で断定","一つだけで性格判断","①複数行動を探す"],["B","根拠なし","評価語だけ","②行動と特徴を分ける"],["C","一般化過多","本文以上に広げた","③共通特徴だけ残す"]],"文章全体":[["A","出来事列挙","変化が書けない","②初期・転換・最終"],["B","結末だけ","最初との対比なし","①冒頭と結末へ"],["C","転換点不足","なぜ変化したか不明","③一本の線にする"]]}};
